/* Eco-Dost's answer cards — written from Avni's project file and website, then fact-checked (Oct 2026).
   Each card: id, topic, q (question), alts (other ways to ask), keywords, answer, fun (did you know?),
   check {q, a} (quick check), hi (Hindi line), filePage, link, caution.
   To add a card, copy one and change it. Keep answers short and correct. */
window.ECODOST = { cards: [
  {"id": "ci-what-is-sbm", "topic": "clean-india", "q": "What is the Clean India Mission (Swachh Bharat Abhiyan)?", "alts": ["what is swachh bharat abhiyan", "what is clean india mission", "swachh bharat kya hai", "what is SBM", "tell me about swachh bharat mission", "what does swachh bharat mean", "swach bharat abhiyan kya hai", "meaning of swachh bharat abhiyan", "clean india mision"], "keywords": ["clean india mission", "swachh bharat", "abhiyan", "SBM", "meaning"], "answer": "The Clean India Mission, or Swachh Bharat Abhiyan, is India's big cleanliness campaign. 'Swachh' means clean, 'Bharat' means India and 'Abhiyan' means campaign. It began with toilets for everyone. Now it also works on managing garbage and dirty water, in both cities and villages.", "fun": "2 October is also celebrated as Swachh Bharat Diwas, which means Clean India Day!", "check": {"q": "What does the word 'Swachh' mean?", "a": "Clean"}, "hi": "स्वच्छ भारत अभियान भारत का सफ़ाई अभियान है; 'स्वच्छ' का मतलब है साफ़ और 'भारत' यानी हमारा देश।", "filePage": "", "link": "#stage"},
  {"id": "ci-launch", "topic": "clean-india", "q": "When was the Swachh Bharat Mission launched, and by whom?", "alts": ["when did swachh bharat start", "who started clean india mission", "launch date of swachh bharat abhiyan", "in which year was swachh bharat launched", "swachh bharat kab shuru hua", "who launched sbm", "when was clean india mission lanched", "swachh bharat abhiyan kisne shuru kiya"], "keywords": ["2 October 2014", "launched", "Narendra Modi", "2014", "started", "date"], "answer": "Prime Minister Narendra Modi launched it on 2 October 2014 in New Delhi. That day was Mahatma Gandhi's birth anniversary. An easy way to remember the date is 2-10-2014!", "fun": "On launch day, PM Modi picked up a broom and swept in Valmiki Basti, New Delhi, a colony where Gandhi Ji had once stayed.", "check": {"q": "On whose birth anniversary was the mission launched?", "a": "Mahatma Gandhi's (2 October)"}, "hi": "स्वच्छ भारत मिशन 2 अक्टूबर 2014 को गांधी जयंती पर प्रधानमंत्री नरेंद्र मोदी ने शुरू किया था।", "filePage": "", "link": "#stage"},
  {"id": "ci-why-oct-2", "topic": "clean-india", "q": "Why was the mission launched on 2 October (Gandhi Jayanti)?", "alts": ["why 2 october", "why was it started on gandhi jayanti", "why on gandhi ji's birthday", "2 october ko kyon shuru hua", "why gandhi jayanti for swachh bharat", "why october 2nd", "why was the launch date chosen", "gandhi jayanti aur swachh bharat"], "keywords": ["2 October", "Gandhi Jayanti", "birthday", "tribute", "150th", "2019"], "answer": "2 October is Gandhi Ji's birthday, and he believed cleanliness was very important, so the mission was a tribute to him. Its first big goal was a clean, open-defecation-free India by his 150th birth anniversary, 2 October 2019.", "fun": "2 October 2014 was Gandhi Ji's 145th birth anniversary. Five years later, on his 150th, rural India declared itself open defecation free.", "check": {"q": "Gandhi Ji was born in 1869. Which birth anniversary fell on 2 October 2019?", "a": "His 150th"}, "hi": "2 अक्टूबर गांधी जी का जन्मदिन है और उन्हें सफ़ाई बहुत प्रिय थी, इसलिए यह मिशन उन्हें श्रद्धांजलि है।", "filePage": "", "link": "#stage"},
  {"id": "ci-aims", "topic": "clean-india", "q": "Why was the Swachh Bharat Mission started? What are its main aims?", "alts": ["aim of swachh bharat", "objectives of clean india mission", "why do we need swachh bharat", "purpose of swachh bharat abhiyan", "swachh bharat ka uddeshya kya hai", "goals of sbm", "why was clean india mission needed", "main goal of swach bharat"], "keywords": ["aim", "objective", "goal", "purpose", "toilets for all", "waste management"], "answer": "It was started to make India clean and healthy. Its main aims are a toilet for every family, so nobody has to defecate in the open, and proper waste management: collecting, separating and processing garbage. It also wants to change our habits, because a clean India needs everyone's help.", "fun": "The second phase of the city mission, SBM-Urban 2.0, has a big dream: a 'Garbage Free' urban India.", "check": {"q": "Name one main aim of the mission.", "a": "Toilets for all / ending open defecation / better waste management"}, "hi": "इसका लक्ष्य है: हर परिवार के लिए शौचालय, खुले में शौच बंद करना और कचरे का सही प्रबंधन।", "filePage": "", "link": "#viva"},
  {"id": "ci-tagline", "topic": "clean-india", "q": "What is the tagline of the Swachh Bharat Mission?", "alts": ["swachh bharat slogan", "ek kadam swachhata ki or meaning", "motto of clean india", "swachh bharat ka naara", "slogan of swachh bharat abhiyan", "who wrote ek kadam swachhta ki ore", "tagline of clean india mision", "what does ek kadam swachhata ki or mean"], "keywords": ["tagline", "slogan", "Ek Kadam Swachhata Ki Or", "one step towards cleanliness", "Bhagyashree Sheth"], "answer": "The tagline is 'Ek Kadam Swachhata Ki Or', which means 'One step towards cleanliness'. Bhagyashree Sheth of Rajkot, Gujarat wrote it, and it was chosen through a MyGov public contest in 2014. It reminds us that every small step counts!", "fun": "The tagline wasn't written by a government office. An ordinary citizen wrote it, and it won a public contest that had thousands of entries.", "check": {"q": "What does 'Ek Kadam Swachhata Ki Or' mean in English?", "a": "One step towards cleanliness"}, "hi": "स्वच्छ भारत का नारा है 'एक कदम स्वच्छता की ओर', यानी सफ़ाई की तरफ़ एक कदम।", "filePage": "", "link": "#thoughts"},
  {"id": "ci-logo", "topic": "clean-india", "q": "What is the logo of Swachh Bharat, and what does it mean?", "alts": ["swachh bharat logo", "why gandhi glasses in swachh bharat logo", "what does the spectacles logo mean", "gandhi ji ka chashma logo", "who designed swachh bharat logo", "logo of clean india mission", "swach bharat logo meaning", "chashma wala logo"], "keywords": ["logo", "spectacles", "glasses", "tricolour", "Gandhi", "Anant Khasbardar"], "answer": "The logo shows Mahatma Gandhi's round spectacles, and the bridge between the two lenses is in our tricolour. It stands for the whole nation coming together to make Gandhi Ji's dream of a clean India come true. Anant Khasbardar of Kolhapur, Maharashtra designed it.", "fun": "PM Modi gave prizes to the logo designer and the tagline writer on launch day itself, 2 October 2014!", "check": {"q": "Whose spectacles are in the Swachh Bharat logo?", "a": "Mahatma Gandhi's"}, "hi": "स्वच्छ भारत के लोगो में गांधी जी का चश्मा है, और उसका बीच का पुल तिरंगे के रंगों में है।", "filePage": "", "link": ""},
  {"id": "ci-pledge", "topic": "clean-india", "q": "What is the Swachhta Pledge?", "alts": ["swachhta shapath", "clean india pledge", "na gandagi karenge na karne denge", "what promise do we take for swachh bharat", "swachata pledge kya hai", "how many hours does the cleanliness pledge say", "swachh bharat oath", "safai ki shapath"], "keywords": ["pledge", "shapath", "oath", "100 hours", "na gandagi karenge"], "answer": "It is the cleanliness promise people took when the mission began in 2014. We promise to keep ourselves and our surroundings clean, and to give 100 hours a year (about 2 hours a week) to cleanliness work. Its spirit is 'Na gandagi karenge, na karne denge': we won't litter, and we won't let others litter.", "fun": "In the pledge, each person also promises to get 100 more people to take the same pledge!", "check": {"q": "How many hours a year does the pledge ask us to give to cleanliness?", "a": "100 hours (about 2 hours a week)"}, "hi": "स्वच्छता शपथ में मैं वादा करती हूँ: न गंदगी करूँगी, न किसी और को करने दूँगी।", "filePage": "", "link": "#thoughts"},
  {"id": "ci-swachhata-hi-seva", "topic": "clean-india", "q": "What is Swachhata Hi Seva?", "alts": ["swachhta hi seva meaning", "what is SHS campaign", "cleanliness is service", "swachhata hi sewa kab hota hai", "when is swachhata hi seva held", "swachta hi seva kya hai", "yearly cleanliness campaign september october", "what is shramdaan"], "keywords": ["Swachhata Hi Seva", "cleanliness is service", "campaign", "September", "shramdaan"], "answer": "'Swachhata Hi Seva' means 'Cleanliness is service'. It is a cleanliness campaign of the Swachh Bharat Mission that began in 2017. It is held almost every year, usually from mid-September to 2 October (Gandhi Jayanti), when people all over India join cleanliness drives and do shramdaan, which means voluntary work.", "fun": "The 2024 theme was 'Swabhaav Swachhata, Sanskaar Swachhata', meaning cleanliness in our nature and cleanliness in our values.", "check": {"q": "Swachhata Hi Seva ends on which special day?", "a": "2 October, Gandhi Jayanti"}, "hi": "'स्वच्छता ही सेवा' यानी सफ़ाई ही सेवा है; यह सफ़ाई अभियान लगभग हर साल सितंबर के बीच से 2 अक्टूबर तक चलता है।", "filePage": "", "link": "#thoughts"},
  {"id": "ci-urban-grameen", "topic": "clean-india", "q": "What are SBM-Urban and SBM-Grameen?", "alts": ["difference between sbm urban and sbm grameen", "what is sbm-g", "what is sbm-u", "what does grameen mean", "swachh bharat gramin kya hai", "two parts of swachh bharat mission", "urban and rural swachh bharat", "sbm gramin"], "keywords": ["SBM-Urban", "SBM-Grameen", "rural", "cities", "villages", "ministry"], "answer": "The mission has two parts. SBM-Urban works in cities and towns and is run by the Ministry of Housing and Urban Affairs. SBM-Grameen ('grameen' means rural) works in villages and is run by the Ministry of Jal Shakti. My model shows both: a Smart City and a Smart Village!", "fun": "The same department that runs SBM-Grameen also runs the Jal Jeevan Mission, which brings tap water to village homes.", "check": {"q": "Which part of the mission works in villages?", "a": "SBM-Grameen (SBM-G)"}, "hi": "स्वच्छ भारत मिशन के दो भाग हैं: शहरों के लिए SBM-शहरी और गाँवों के लिए SBM-ग्रामीण।", "filePage": "", "link": ""},
  {"id": "ci-urban-toilets", "topic": "clean-india", "q": "What has the Swachh Bharat Mission achieved in our cities?", "alts": ["how many toilets were built in cities", "63 lakh toilets", "what does 108 percent mean", "sbm urban achievements", "how many public toilets were built", "shaharon mein kitne shauchalay bane", "125 percent of target meaning", "achievments of swachh bharat urban"], "keywords": ["63.8 lakh", "6.36 lakh", "108%", "125%", "target", "urban toilets"], "answer": "In our cities, about 63.8 lakh home toilets were built, which is 108% of the target. About 6.36 lakh community and public toilet seats were also built, which is 125% of the target. More than 100% means India built even more than it first planned!", "fun": "63.8 lakh is 63,80,000. That's about 6.38 million home toilets, in cities alone!", "check": {"q": "What does 'more than 100% of the target' mean?", "a": "More toilets were built than planned"}, "hi": "शहरों में लगभग 63.8 लाख घरेलू शौचालय (लक्ष्य का 108%) और 6.36 लाख सामुदायिक व सार्वजनिक शौचालय सीटें (लक्ष्य का 125%) बनीं।", "filePage": "p9", "link": "#stage", "caution": "My file says '6.3 lakh Community & Public Toilets', but call them about 6.36 lakh toilet SEATS."},
  {"id": "ci-grameen-toilets", "topic": "clean-india", "q": "What did Swachh Bharat Mission (Grameen) achieve in villages?", "alts": ["how many toilets were built in villages", "10 crore toilets", "sbm grameen phase 1", "when did villages become odf", "gaon mein kitne shauchalay bane", "achievements of sbm g", "rural toilets swachh bharat", "sbm-g phase one result"], "keywords": ["10 crore", "household toilets", "Phase 1", "2019", "villages", "ODF"], "answer": "In Phase 1 (2014–2019), SBM-Grameen helped build over 10 crore household toilets in villages. By 2 October 2019, villages across India declared themselves Open Defecation Free. Phase 2 began in 2020. It works on keeping villages ODF and managing their garbage and dirty water, which is called ODF Plus.", "fun": "10 crore is 100 million. If you built one toilet every second, 10 crore toilets would take you more than 3 years!", "check": {"q": "By which year did villages declare themselves ODF?", "a": "2019 (by 2 October 2019)"}, "hi": "ग्रामीण मिशन के पहले चरण में 10 करोड़ से ज़्यादा घरेलू शौचालय बने और 2019 तक गाँवों ने ख़ुद को खुले में शौच से मुक्त घोषित किया।", "filePage": "", "link": "#model/villagetoilet"},
  {"id": "ci-odf-meaning", "topic": "clean-india", "q": "What does ODF mean?", "alts": ["what is odf", "full form of odf", "odf ka matlab", "open defecation free meaning", "what is open defecation", "odf stands for", "o d f meaning", "what is opendefecation"], "keywords": ["ODF", "Open Defecation Free", "open defecation", "full form"], "answer": "ODF stands for Open Defecation Free. Open defecation means going to the toilet in open fields, by roadsides or near water instead of using a toilet. A place is ODF when every household has a toilet and everyone uses it.", "fun": "A 2019 Swachh Bharat (Grameen) campaign with Amitabh Bachchan, 'Darwaza Band – Part 2', said toilets are for 'har koi, har roz, hamesha': everyone, every day, always.", "check": {"q": "What is the full form of ODF?", "a": "Open Defecation Free"}, "hi": "ODF का मतलब है 'खुले में शौच से मुक्त', यानी हर घर में शौचालय है और सब उसका इस्तेमाल करते हैं।", "filePage": "ODF page", "link": "#model/citytoilets"},
  {"id": "ci-odf-village", "topic": "clean-india", "q": "What is an ODF village, and why is it good?", "alts": ["odf village meaning", "what is an open defecation free village", "odf gaon kya hota hai", "benefits of odf village", "why is an odf village good", "explain odf villages", "odf vilage", "odf gaon ke fayde"], "keywords": ["ODF village", "household toilets", "drinking water", "diseases", "village"], "answer": "An ODF village is one where nobody defecates in the open and every household has a toilet and uses it. This keeps the village clean, stops diseases from spreading, protects drinking-water sources from germs and makes the village safer for everyone. It is a big step towards a clean, healthy India.", "fun": "Many village toilets are twin-pit toilets. When one pit is full, the other is used, and the waste in the first pit slowly turns into safe manure.", "check": {"q": "Name one benefit of an ODF village.", "a": "Fewer diseases / safe drinking-water sources / safety"}, "hi": "ODF गाँव वह है जहाँ कोई खुले में शौच नहीं करता और हर घर में शौचालय है, जिससे बीमारियाँ कम होती हैं और पानी साफ़ रहता है।", "filePage": "ODF page", "link": "#model/villagetoilet"},
  {"id": "ci-open-defecation-disease", "topic": "clean-india", "q": "How does open defecation spread diseases?", "alts": ["why are toilets important for health", "which diseases spread due to poor sanitation", "how does open defecation pollute water", "sanitation and health", "khule mein shauch se bimari kaise failti hai", "why should we use toilets", "why do we need toilets?", "diseases from dirty water"], "keywords": ["germs", "diseases", "diarrhoea", "cholera", "typhoid", "flies", "sanitation"], "answer": "Human waste has germs. When it is left in the open, flies carry the germs to our food, and rainwater washes them into ponds, rivers and wells. Some can even seep into groundwater. This spreads diseases like diarrhoea, cholera and typhoid. Toilets keep these germs safely away from people and water.", "fun": "In 2018, a WHO study estimated that Swachh Bharat (Grameen) could help prevent over 3 lakh deaths from diarrhoea and malnutrition between 2014 and 2019.", "check": {"q": "Name two diseases spread by poor sanitation.", "a": "Any two: diarrhoea, cholera, typhoid"}, "hi": "खुले में शौच के कीटाणु मक्खियों और बारिश के पानी से हमारे खाने-पानी तक पहुँचते हैं और दस्त, हैज़ा, टाइफ़ाइड जैसी बीमारियाँ फैलाते हैं।", "filePage": "", "link": "#model/citytoilets"},
  {"id": "ci-odf-still-work", "topic": "clean-india", "q": "Is India now completely free of open defecation?", "alts": ["is there no open defecation in india now", "is india 100 percent odf", "does everyone use toilets now", "kya ab koi khule mein shauch nahi karta", "is the swachh bharat work finished", "has open defecation stopped completely", "is india fully odf", "odf sustain karna kya hai"], "keywords": ["completely", "sustain", "still", "maintain toilets", "100 percent"], "answer": "Not fully. The mission hugely improved toilet access, and villages declared themselves ODF in 2019. But some people still go in the open, and toilets must be used every day, kept clean and repaired. So the next job is to sustain ODF, which means keeping it going. That is the first part of ODF Plus.", "fun": "World Toilet Day is on 19 November every year. The United Nations made it an official day in 2013.", "check": {"q": "After becoming ODF, what is the next big job?", "a": "Keeping it ODF by using and maintaining toilets"}, "hi": "शौचालय बहुत बढ़े हैं, पर काम पूरा नहीं हुआ; हमें रोज़ शौचालय का इस्तेमाल और उसकी देखभाल करते रहना है।", "filePage": "", "link": "#viva", "caution": "Don't say 'there is no open defecation anywhere in India now'."},
  {"id": "ci-odf-plus", "topic": "clean-india", "q": "What is ODF Plus, and how is it different from ODF?", "alts": ["what is odf plus", "odf vs odf plus", "difference between odf and odf+", "odf plus village meaning", "odf plus kya hai", "what is odf+", "odf plus gaon", "odf pluss"], "keywords": ["ODF Plus", "solid waste", "liquid waste", "visibly clean", "difference"], "answer": "ODF means everyone uses toilets. ODF Plus goes one step further. The village stays ODF, manages its solid waste (garbage) and liquid waste (dirty water), and stays visibly clean. So ODF is about toilets, and ODF Plus is about toilets plus a clean village.", "fun": "A village declares itself ODF Plus in its Gram Sabha, the meeting of the village's adult voters.", "check": {"q": "Which two kinds of waste must an ODF Plus village manage?", "a": "Solid waste and liquid waste"}, "hi": "ODF प्लस गाँव खुले में शौच से मुक्त रहता है और साथ ही अपने कचरे और गंदे पानी का सही प्रबंधन भी करता है।", "filePage": "p14", "link": "#viva"},
  {"id": "ci-odf-plus-stages", "topic": "clean-india", "q": "What are the three stages of an ODF Plus village?", "alts": ["three stages of odf plus", "aspiring rising model", "what is odf plus model village", "which is the highest stage of odf plus", "odf plus ke teen charan", "levels of odf plus", "what is odf plus aspiring", "odf plus rising meaning"], "keywords": ["Aspiring", "Rising", "Model", "stages", "highest"], "answer": "There are three levels. Remember A-R-M! 1) Aspiring: stays ODF and has arrangements for solid OR liquid waste. 2) Rising: stays ODF and manages BOTH solid and liquid waste. 3) Model, the highest: manages both, stays visibly clean and displays sanitation awareness messages.", "fun": "The awareness messages in Model villages are called IEC, which stands for Information, Education and Communication.", "check": {"q": "Which is the highest stage of ODF Plus?", "a": "ODF Plus Model"}, "hi": "ODF प्लस के तीन चरण हैं: एस्पायरिंग, राइज़िंग और मॉडल; 'मॉडल' सबसे ऊँचा चरण है।", "filePage": "p14", "link": "#viva"},
  {"id": "ci-odf-plus-count", "topic": "clean-india", "q": "How many villages in India are ODF Plus?", "alts": ["number of odf plus villages", "5.69 lakh villages", "how many odf plus model villages", "kitne gaon odf plus hain", "odf plus villages count 2026", "5.7 lakh villages", "odf plus village numbers"], "keywords": ["5.69 lakh", "5.25 lakh", "villages", "Model stage", "2026"], "answer": "By September 2026, about 5.69 lakh villages in India were ODF Plus. About 5.25 lakh of them had reached the highest 'Model' stage. In my speech, I can round it to 'about 5.7 lakh villages'.", "fun": "5.69 lakh is 5,69,000 villages. If you visited one village every day, it would take you more than 1,500 years to see them all!", "check": {"q": "About how many ODF Plus villages are in the 'Model' stage?", "a": "About 5.25 lakh"}, "hi": "सितंबर 2026 तक लगभग 5.69 लाख गाँव ODF प्लस थे, जिनमें से लगभग 5.25 लाख सबसे ऊँचे 'मॉडल' चरण में थे।", "filePage": "", "link": "#stage"},
  {"id": "ci-phase2-areas", "topic": "clean-india", "q": "What are the four key areas of SBM-Grameen Phase II?", "alts": ["sbm g phase 2 focus areas", "four areas of odf plus", "what does phase 2 of swachh bharat grameen do", "phase 2 ke chaar kshetra", "what is faecal sludge management", "4 key areas sbm-g phase two", "what does sbm-g phase ii focus on", "fecal sludge meaning"], "keywords": ["Phase II", "biodegradable waste", "plastic waste", "greywater", "faecal sludge"], "answer": "Phase II (ODF Plus) builds village systems for four areas: 1) biodegradable waste, which can become compost or biogas; 2) plastic waste; 3) greywater, the used water from kitchens and bathing; and 4) faecal sludge, which means safely emptying and treating the waste from toilet pits and septic tanks.", "fun": "GOBARdhan, which turns cattle dung, crop waste and kitchen waste into biogas and manure, started in 2018 under SBM-Grameen.", "check": {"q": "Name any two of the four areas.", "a": "Any two: biodegradable waste, plastic waste, greywater, faecal sludge"}, "hi": "दूसरे चरण के चार क्षेत्र हैं: जैविक कचरा, प्लास्टिक कचरा, ग्रे-वॉटर (रसोई और नहाने का गंदा पानी) और मल-कीचड़ (फ़ीकल स्लज) प्रबंधन।", "filePage": "p20", "link": "#model/biogas"},
  {"id": "ci-greywater", "topic": "clean-india", "q": "What is greywater, and how do villages manage it?", "alts": ["what is grey water", "greywater meaning", "what is a soak pit", "liquid waste management in villages", "grey water kya hai", "gray water", "sokhta gadda kya hai", "how to manage dirty water in a village"], "keywords": ["greywater", "soak pit", "liquid waste", "kitchen water", "drains"], "answer": "Greywater is the used water from kitchens, bathing and washing clothes, but not from toilets. If it spreads on streets, it makes puddles where mosquitoes breed. Villages manage it with drains and soak pits. A soak pit is filled with stones and gravel and lets the water slowly soak into the ground.", "fun": "Water from toilets is called 'blackwater'. It carries human waste, so it needs more careful treatment than greywater.", "check": {"q": "Is water from washing dishes greywater or blackwater?", "a": "Greywater"}, "hi": "रसोई, नहाने और कपड़े धोने के बाद बचा पानी ग्रे-वॉटर कहलाता है; गाँवों में इसे नालियों और सोख्ता गड्ढों से संभाला जाता है।", "filePage": "p14", "link": ""},
  {"id": "ci-handwashing", "topic": "clean-india", "q": "Why is handwashing with soap important?", "alts": ["when should we wash our hands", "how to wash hands properly", "why wash hands after toilet", "haath dhona kyon zaroori hai", "how long should we wash hands", "why use soap", "hand washing", "handwashing and sanitation"], "keywords": ["handwashing", "soap", "germs", "before eating", "after toilet", "20 seconds"], "answer": "Our hands pick up germs from everything we touch. Washing with soap and water removes them, so the germs don't reach our mouth with our food. Always wash before eating and after using the toilet. Scrub the backs of your hands, between your fingers and under your nails for at least 20 seconds.", "fun": "Global Handwashing Day is on 15 October every year. And 20 seconds is about as long as humming 'Happy Birthday' twice!", "check": {"q": "What are the two most important times to wash your hands?", "a": "Before eating and after using the toilet"}, "hi": "खाने से पहले और शौचालय के बाद साबुन से कम से कम 20 सेकंड हाथ धोने से कीटाणु दूर होते हैं।", "filePage": "", "link": "#thoughts"},
  {"id": "ci-dignity", "topic": "clean-india", "q": "How do toilets give dignity and safety, especially to girls and women?", "alts": ["why are separate toilets important for girls", "toilets and women safety", "what is dignity in sanitation", "ladkiyon ke liye shauchalay kyon zaroori hai", "why separate toilets for boys and girls", "sanitation and dignity", "why are there male and female toilets in my model", "sammaan aur shauchalay"], "keywords": ["dignity", "safety", "privacy", "women", "girls", "separate toilets"], "answer": "Without a toilet at home, many women and girls had to go out in the open, often in the dark. That could be unsafe and embarrassing. A toilet at home gives privacy, safety and respect, and this is called dignity. That's why the toilets in my Smart City have separate male and female signs!", "fun": "In just one year (2014–15), about 1.9 lakh girls' toilets were built or made usable in government schools.", "check": {"q": "Give one reason why separate toilets matter for girls.", "a": "Safety / privacy / dignity"}, "hi": "घर में शौचालय होने से, ख़ासकर लड़कियों और महिलाओं को, सुरक्षा, निजता और सम्मान मिलता है।", "filePage": "", "link": "#model/citytoilets"},
  {"id": "ci-swachh-vidyalaya", "topic": "clean-india", "q": "What is Swachh Vidyalaya?", "alts": ["clean schools campaign", "swachh vidyalaya abhiyan", "school toilets swachh bharat", "does swachh vidyalaya use solar", "swach vidyalay kya hai", "swachh vidyalaya meaning", "clean school mission", "toilets in schools"], "keywords": ["Swachh Vidyalaya", "clean school", "school toilets", "drinking water", "girls and boys"], "answer": "Swachh Vidyalaya means 'Clean School'. It started in 2014 to give schools working toilets, separate for girls and boys, and clean drinking water. It is about toilets and water, not solar power. Many government schools do have rooftop solar panels, but that is a different idea.", "fun": "By 15 August 2015, the government counted about 4.17 lakh toilets built or repaired in about 2.61 lakh government schools in just one year.", "check": {"q": "Is Swachh Vidyalaya about solar panels or about toilets?", "a": "Toilets and drinking water"}, "hi": "स्वच्छ विद्यालय का मतलब है स्कूलों में लड़कियों और लड़कों के लिए अलग शौचालय और पीने का साफ़ पानी।", "filePage": "Solar page", "link": "", "caution": "My file's solar page says solar 'feeds into Swachh Vidyalaya'. That's not correct: Swachh Vidyalaya is about toilets and water."},
  {"id": "ci-safaimitra", "topic": "clean-india", "q": "Who are SafaiMitras?", "alts": ["safai mitra meaning", "who are sanitation workers", "safaimitra kaun hote hain", "who cleans our sewers", "safai karamchari", "what does safai mitra mean", "sanitation workers swachh bharat", "safaimitras"], "keywords": ["SafaiMitra", "sanitation workers", "friend of cleanliness", "sewers", "respect"], "answer": "'SafaiMitra' means 'friend of cleanliness'. SafaiMitras are sanitation workers who sweep streets, collect garbage and clean sewers and septic tanks. Our cities stay clean because of their hard work. We should respect them, and we can make their job easier and safer by segregating our waste.", "fun": "An Indian law from 2013 makes it a crime to send people into sewers or septic tanks without safety gear.", "check": {"q": "What does 'SafaiMitra' mean?", "a": "Friend of cleanliness"}, "hi": "सफ़ाईमित्र यानी 'सफ़ाई के दोस्त': वे कर्मचारी जो सड़कें, कचरा और सीवर साफ़ करके शहर को साफ़ रखते हैं।", "filePage": "", "link": "#viva"},
  {"id": "ci-safaimitra-surakshit-shehar", "topic": "clean-india", "q": "What is SafaiMitra Surakshit Shehar?", "alts": ["safaimitra surakshit shehar meaning", "has manual sewer cleaning been eliminated", "how many cities are safaimitra surakshit", "safe city for sanitation workers", "safai mitra surakshit sheher kya hai", "3150 cities safaimitra", "sewer cleaning with machines", "manhole to machine hole"], "keywords": ["SafaiMitra Surakshit Shehar", "500 cities", "machines", "sewer", "Chandigarh award"], "answer": "It means 'a city that is safe for SafaiMitras'. More than 500 cities have promised to clean sewers and septic tanks with machines instead of sending people inside, which is very dangerous. Chandigarh has won an award for keeping its SafaiMitras safe. But the work isn't finished, and sadly some workers still lose their lives in sewers.", "fun": "Chandigarh got the 'Best Safaimitra Surakshit Shehar' award in Swachh Survekshan 2023. President Droupadi Murmu presented it in January 2024.", "check": {"q": "Instead of people going into sewers, what should clean them?", "a": "Machines (mechanised cleaning)"}, "hi": "सफ़ाईमित्र सुरक्षित शहर का मतलब है सीवर की सफ़ाई इंसानों की जगह मशीनों से; 500 से ज़्यादा शहरों ने यह वादा किया है।", "filePage": "p9", "link": "#viva", "caution": "My file says 'over 3,150 cities' and 'eliminating' manual entry. Say 'more than 500 cities' and 'there is still work to do'."},
  {"id": "ci-legacy-dumpsites", "topic": "clean-india", "q": "What are legacy dumpsites, and how many has India cleared?", "alts": ["what is a legacy dumpsite", "old garbage mountains", "dumpsite remediation meaning", "how many dumpsites in india", "kachre ke pahad", "purane kachre ke dher", "dumpsite clearance swachh bharat", "legacy waste meaning"], "keywords": ["legacy dumpsites", "2,500", "1,000 cleared", "garbage mountains", "remediation"], "answer": "Legacy dumpsites are old dumps where city garbage was piled up for many years, sometimes into huge 'garbage mountains'. India found about 2,500 such dumpsites, and more than 1,000 have been fully cleared. The work is still going on in many cities.", "fun": "Old dumps are cleared by 'biomining'. Machines dig up the old garbage and sieve it into soil-like material, plastics and stones, so the land can be used again.", "check": {"q": "About how many old dumpsites were found in India?", "a": "About 2,500"}, "hi": "पुराने कचरे के ढेरों को लेगेसी डंपसाइट कहते हैं; भारत में लगभग 2,500 ऐसे ढेर मिले और 1,000 से ज़्यादा पूरी तरह साफ़ हो चुके हैं।", "filePage": "p9", "link": "#viva", "caution": "My file says 'across thousands of cities'. Say 'about 2,500 dumpsites, more than 1,000 cleared', and don't say Chandigarh's Dadu Majra dumpsite is finished."},
  {"id": "ci-why-clear-dumpsites", "topic": "clean-india", "q": "Why is clearing old dumpsites important?", "alts": ["why remove garbage mountains", "problems of dumpsites", "what is leachate", "why are open dumps bad", "dumpsite saaf karna kyon zaroori hai", "harm from old dumps", "benefits of dumpsite remediation"], "keywords": ["methane", "leachate", "fire", "smell", "land", "dumpsite"], "answer": "Old dumps smell bad, attract flies and stray animals, and can catch fire and fill the air with smoke. Rotting waste makes methane, a strong greenhouse gas. A dirty liquid called leachate can seep into the soil and groundwater. Clearing the dumps makes the area healthier and frees the land for parks and other uses.", "fun": "In November 2025, India launched a one-year push called 'Lakshya Zero Dumpsites' to speed up clearing the old dumpsites that were still left.", "check": {"q": "Which greenhouse gas comes from rotting waste in dumps?", "a": "Methane"}, "hi": "पुराने कचरे के ढेर बदबू, बीमारी, आग और मीथेन गैस फैलाते हैं; इन्हें हटाने से ज़मीन फिर काम आती है।", "filePage": "p9", "link": "#viva"},
  {"id": "ci-gandhi", "topic": "clean-india", "q": "What did Mahatma Gandhi say and do about cleanliness?", "alts": ["gandhi and cleanliness", "gandhi ji swachhata", "gandhi quote on cleanliness", "what is the connection between gandhi and swachh bharat", "gandhiji ne safai ke baare mein kya kaha", "why is gandhi linked with clean india", "gandhi lavatory drawing room quote", "gandi ji and safai"], "keywords": ["Gandhi", "lavatory", "drawing-room", "ashram", "cleanliness"], "answer": "Gandhi Ji believed cleanliness was everyone's duty and that no cleaning job was too low. He wrote, 'A lavatory must be as clean as a drawing-room', the room where guests sit. In his ashrams everyone shared the cleaning, even of toilets, and Gandhi Ji did it himself too.", "fun": "Gandhi Ji wrote the 'drawing-room' line in Gujarati, in his paper Navajivan, on 24 May 1925.", "check": {"q": "Gandhi Ji said a lavatory should be as clean as which room?", "a": "A drawing-room"}, "hi": "गांधी जी कहते थे कि शौचालय भी बैठक जितना साफ़ होना चाहिए, और वे ख़ुद भी सफ़ाई करते थे।", "filePage": "", "link": "#thoughts"},
  {"id": "ci-why-cleanliness", "topic": "clean-india", "q": "Why does cleanliness matter?", "alts": ["why is cleanliness important", "importance of cleanliness", "swachhata kyon zaroori hai", "benefits of a clean india", "why should we keep india clean", "why is swachhata important", "importance of clenliness", "safai ka mahatva"], "keywords": ["importance", "health", "environment", "dignity", "development"], "answer": "Cleanliness keeps us healthy, because germs, flies and mosquitoes spread less. It protects our water, soil and air, and it gives people safety and dignity. A clean country also looks beautiful and welcomes visitors. Dr. A.P.J. Abdul Kalam said environmental cleanliness is one of the signs of a nation's development.", "fun": "Dr. Kalam said this in a speech called 'Clean Environment is a Societal Mission', in New Delhi on 20 January 2006.", "check": {"q": "Give two reasons why cleanliness is important.", "a": "Any two: health, clean water/air/soil, dignity, development"}, "hi": "स्वच्छता से सेहत अच्छी रहती है, पानी-हवा साफ़ रहते हैं, सम्मान मिलता है और देश आगे बढ़ता है।", "filePage": "", "link": "#thoughts"},
  {"id": "ci-everyones-job", "topic": "clean-india", "q": "Is the Clean India Mission only the government's job?", "alts": ["what can i do for swachh bharat", "role of citizens in clean india", "is cleanliness only government responsibility", "how can students help swachh bharat", "hum swachh bharat ke liye kya kar sakte hain", "citizens duty clean india", "is cleanliness a one day job", "swachh bharat mein meri bhoomika"], "keywords": ["citizen", "responsibility", "everyday habit", "students", "not only government"], "answer": "No! My project file says the Clean India Mission is not only a government programme but a responsibility of every citizen. Cleanliness can't be just a 2 October photo either. It must be an everyday habit. I can stop littering, segregate waste at home and school, say no to single-use plastic and spread awareness.", "fun": "The last line of the Swachhta Pledge says that every step I take towards cleanliness will help make my whole country clean.", "check": {"q": "Finish my file's line: 'A Clean India is not just a dream; it is…'", "a": "'…a responsibility we share.'"}, "hi": "स्वच्छ भारत सिर्फ़ सरकार का काम नहीं, हर नागरिक की ज़िम्मेदारी है; मैं भी रोज़ अपना हिस्सा निभाऊँगी।", "filePage": "p23", "link": "#thoughts"},
  {"id": "wm-what-is", "topic": "waste", "q": "What is waste management?", "alts": ["what is waste managment", "waste management meaning", "define waste management", "kachra prabandhan kya hai", "waste management kya hota hai", "explain waste management in simple words", "what is waste management in swachh bharat", "what do you mean by managing waste"], "keywords": ["waste management", "definition", "meaning", "kachra prabandhan", "handling waste"], "answer": "Waste management means handling waste in a safe, smart way — from the moment we throw something away to its final use or safe disposal. Under the Swachh Bharat Mission it has grown from basic cleanliness into scientific processing: separating waste at source and turning it into manure, biogas, energy and recycled things, instead of dumping it.", "fun": "The Swachh Bharat Mission was launched on 2 October 2014, Gandhi Ji's birth anniversary.", "check": {"q": "Does waste management start at the landfill or at home?", "a": "At home — at the source, by separating waste."}, "hi": "कचरा प्रबंधन का मतलब है कचरे को सही और सुरक्षित तरीके से संभालना — उसे स्रोत पर अलग करना और ढेर लगाने के बजाय खाद, बायोगैस, ऊर्जा या रीसायकल की चीज़ों में बदलना।", "filePage": "p20", "link": "#model/bins"},
  {"id": "wm-steps", "topic": "waste", "q": "What are the steps of waste management?", "alts": ["steps of waste management", "waste management process", "how is waste managed step by step", "what happens to garbage after we throw it", "stages of waste management", "waste management ke steps", "kachra kahan jata hai", "waste managment steps"], "keywords": ["steps", "process", "collect", "transport", "dispose", "stages"], "answer": "Five easy steps! 1) Separate waste at source — at home, school or shop. 2) Collect it from homes or bins. 3) Transport it, keeping the types apart. 4) Recycle or treat it — wet waste becomes compost or biogas, dry waste is sorted and recycled. 5) Safely dispose of only what is left, in a proper landfill.", "fun": "Landfill is the very last step: under India's 2026 waste rules, only waste that cannot be recycled or used for energy should go there.", "check": {"q": "Which step comes first?", "a": "Separating (segregating) waste at source."}, "hi": "कचरा प्रबंधन के पाँच कदम हैं — स्रोत पर अलग करना, इकट्ठा करना, ले जाना, रीसायकल या उपचार करना, और बचे हुए का सुरक्षित निपटान।", "filePage": "", "link": "#model/bins"},
  {"id": "wm-segregation-source", "topic": "waste", "q": "What is waste segregation at source?", "alts": ["what is segregation", "segregation at source meaning", "what is waste segregation", "source segregation", "segrigation of waste", "kachra alag karna kya hai", "what does at source mean", "how do we separate waste at home"], "keywords": ["segregation", "at source", "separate", "sorting", "home", "alag"], "answer": "Segregation at source means separating waste into different bins right where it is made — at home, in school or in a shop — before it gets mixed. 'Source' simply means the place where waste is created. Your project file calls segregation the vital process that makes recycling efficient and protects the environment.", "fun": "India's Solid Waste Management Rules 2026 apply in villages as well as cities — segregation is for everyone!", "check": {"q": "What does 'source' mean in segregation at source?", "a": "The place where waste is made, like our home or school."}, "hi": "स्रोत पर कचरा अलग करने का मतलब है — कचरा जहाँ बनता है, जैसे घर, स्कूल या दुकान, वहीं उसे अलग-अलग डिब्बों में डालना।", "filePage": "p20", "link": "#model/bins"},
  {"id": "wm-why-segregate", "topic": "waste", "q": "Why is it important to segregate waste? What happens if we mix it?", "alts": ["why segregate waste", "why should we separate waste", "what if wet and dry waste are mixed", "problem with mixed waste", "importance of segregation", "why segregation is importent", "kachra alag kyon karein", "why can't the municipality separate it later", "mixed kachre se kya nuksan"], "keywords": ["why", "mixed waste", "importance", "recycling", "landfill", "resource"], "answer": "When waste is mixed, paper and plastic get dirty and wet, so they are hard to recycle, and wet waste can't become clean compost. Much mixed waste ends up in landfills and dumps, causing smell, methane and dirty liquid. Sorting it later is hard and unsafe for workers. Remember: separated waste is a resource; mixed waste is garbage!", "fun": "Under India's 2026 waste rules, sending unsegregated (mixed) waste to a landfill costs higher fees than separated waste.", "check": {"q": "Complete it: Separated waste is a ___; mixed waste is ___.", "a": "Resource; garbage."}, "hi": "मिला हुआ कचरा न ठीक से रीसायकल होता है, न उससे अच्छी खाद बनती है; अलग किया हुआ कचरा संसाधन है, मिला-जुला कचरा बस ढेर।", "filePage": "", "link": "#model/bins"},
  {"id": "wm-swm-rules-2026", "topic": "waste", "q": "What are the four types of waste under India's Solid Waste Management Rules 2026?", "alts": ["swm rules 2026", "four stream segregation", "new waste rules 2026", "4 types of waste segregation", "what is four-way segregation", "when did the new waste rules start", "naye kachra niyam kya hain", "solid waste managment rules", "four streams of waste"], "keywords": ["SWM Rules 2026", "four streams", "wet", "dry", "sanitary", "special care", "1 April 2026"], "answer": "From 1 April 2026, India's Solid Waste Management Rules, 2026 make four-stream segregation compulsory: 1) Wet waste — food and peels. 2) Dry waste — paper, plastic, metal, glass. 3) Sanitary waste — used diapers and pads, wrapped up. 4) Special care waste — medicines, bulbs, batteries, paint containers. These rules replaced the older 2016 rules.", "fun": "Places making 100 kg or more of waste a day — like big housing societies — are 'bulk waste generators' and have extra duties under the 2026 rules.", "check": {"q": "Name the four streams.", "a": "Wet, dry, sanitary and special care."}, "hi": "1 अप्रैल 2026 से कचरे को चार हिस्सों में बाँटना ज़रूरी है — गीला, सूखा, सैनिटरी और विशेष देखभाल वाला कचरा।", "filePage": "p13", "link": "#model/bins", "caution": "Your file (after p20) says 'wet, dry and hazardous' — under the 2026 rules say four types: wet, dry, sanitary and special care."},
  {"id": "wm-public-bin-colours", "topic": "waste", "q": "What bin colours do the 2026 rules give for public places?", "alts": ["bin colours in swm rules 2026", "which colour bin for wet waste", "public dustbin colours", "what colour is the dry waste bin", "dustbin colors india rules", "does the law fix a black bin colour", "kaunsa dabba kis rang ka", "green and blue bin rule"], "keywords": ["bin colours", "public places", "green", "blue", "red", "rules 2026"], "answer": "For bins in public places, the SWM Rules 2026 say GREEN for wet waste and BLUE for dry waste, and RED bins can be kept in public toilets for sanitary waste. The rules don't fix a colour for special care waste or for bins at home — instead, cities must set up special collection centres for special care waste.", "fun": "Three of the five bin colours in your model — green, blue and red — match the public-bin colours in India's 2026 rules!", "check": {"q": "Which colour is for wet waste in public places?", "a": "Green."}, "hi": "नए नियमों में सार्वजनिक जगहों पर हरा डिब्बा गीले कचरे, नीला सूखे कचरे और सार्वजनिक शौचालयों में लाल डिब्बा सैनिटरी कचरे के लिए है।", "filePage": "", "link": "#model/bins", "caution": "Don't say the national rules set black or yellow bin colours — they don't."},
  {"id": "wm-chandigarh-bins", "topic": "waste", "q": "What is Chandigarh's four-bin system?", "alts": ["chandigarh bins", "chandigarh 4 bin system", "chandigarh dustbin colours", "is segregation compulsory in chandigarh", "fine for not separating waste in chandigarh", "challan for mixed waste", "chandigarh mein kitne dabbe hain", "chandigarh four bin sistem"], "keywords": ["Chandigarh", "four bins", "challan", "fine", "compulsory", "Municipal Corporation"], "answer": "Chandigarh Municipal Corporation uses four bins at home: GREEN for wet waste, BLUE for dry waste, BLACK for domestic hazardous waste (like batteries and bulbs) and RED for sanitary waste. From April 2026 this system is compulsory, and people who don't separate their waste can get a fine (challan). Do confirm the details with Rajnish Ma'am.", "fun": "Chandigarh first added black and red bins next to its green and blue ones back in 2022.", "check": {"q": "In Chandigarh, which bin gets a dead battery?", "a": "The black bin (domestic hazardous waste)."}, "hi": "चंडीगढ़ में चार डिब्बे हैं — हरा गीले, नीला सूखे, काला घरेलू खतरनाक और लाल सैनिटरी कचरे के लिए; अप्रैल 2026 से यह ज़रूरी है और न मानने पर चालान हो सकता है।", "filePage": "", "link": "#model/bins"},
  {"id": "wm-five-bins", "topic": "waste", "q": "What are the five dustbins in my model?", "alts": ["five dustbins", "explain your dustbins", "why 5 bins in your model", "dustbin colours in your model", "tell me about your dust bins", "what do your bins show", "5 dabbe kis liye hain", "five dustbin colour meaning"], "keywords": ["five dustbins", "model", "green", "blue", "black", "red", "yellow"], "answer": "Your model has five bins for segregation at source: GREEN = wet waste, BLUE = dry waste, BLACK = domestic hazardous waste, RED = sanitary waste (black and red follow Chandigarh's system), and YELLOW = most likely biomedical waste. Confirm black, red and yellow with Rajnish Ma'am. Big idea: separated waste becomes a resource!", "fun": "Hospitals use a different colour code under the Bio-Medical Waste Rules 2016: yellow, red, white and blue.", "check": {"q": "Which bin in your model is for fruit peels?", "a": "Green (wet waste)."}, "hi": "मेरे मॉडल में पाँच डिब्बे हैं — हरा गीले, नीला सूखे, काला घरेलू खतरनाक, लाल सैनिटरी और पीला शायद बायोमेडिकल कचरे के लिए।", "filePage": "", "link": "#model/bins", "caution": "Say 'in Chandigarh's system' for black and red, and 'most likely' for yellow until Ma'am confirms."},
  {"id": "wm-green-bin", "topic": "waste", "q": "What goes in the green bin (wet waste)?", "alts": ["green bin", "what is wet waste", "wet waste examples", "where do fruit peels go", "green dustbin meaning", "what happens to wet waste", "hara dabba", "gila kachra kya hai", "wet wast"], "keywords": ["green bin", "wet waste", "peels", "leftover food", "compost", "biogas"], "answer": "The GREEN bin is for wet waste — fruit and vegetable peels, leftover food, tea leaves and flowers. Wet waste rots quickly because tiny microorganisms break it down. So it can become compost (manure for plants) or biogas (cooking gas) — just like the biogas plant in your model!", "fun": "Wet waste is full of water, so when it is mixed in, thermal waste-to-energy plants work much less efficiently — your file says this on p13.", "check": {"q": "Do used tea leaves go in the green or blue bin?", "a": "Green — they are wet waste."}, "hi": "हरे डिब्बे में गीला कचरा जाता है — छिलके, बचा खाना, चायपत्ती और फूल — जिससे खाद या बायोगैस बनती है।", "filePage": "", "link": "#model/bins"},
  {"id": "wm-blue-bin", "topic": "waste", "q": "What goes in the blue bin (dry waste)?", "alts": ["blue bin", "what is dry waste", "dry waste examples", "where does a plastic bottle go", "blue dustbin meaning", "what happens to dry waste", "neela dabba", "sukha kachra kya hai", "dry wast"], "keywords": ["blue bin", "dry waste", "paper", "plastic", "metal", "glass", "recycling"], "answer": "The BLUE bin is for dry waste — paper, cardboard, plastic, metal cans and glass bottles. Dry waste does not rot quickly. It goes to a sorting centre called a Material Recovery Facility, where it is separated and sent for recycling. Tip: keep it clean and dry so it can really be recycled!", "fun": "Recycling aluminium cans uses about 95% less energy than making new aluminium from raw ore.", "check": {"q": "Why should dry waste be kept clean and dry?", "a": "So it can be recycled easily."}, "hi": "नीले डिब्बे में सूखा कचरा जाता है — कागज़, गत्ता, प्लास्टिक, धातु के डिब्बे और काँच की बोतलें — जो छँटकर रीसायकल होता है।", "filePage": "", "link": "#model/bins"},
  {"id": "wm-black-bin", "topic": "waste", "q": "What goes in the black bin?", "alts": ["black bin", "black dustbin meaning", "what is domestic hazardous waste", "hazardous waste at home", "black bin for what", "which bin for broken glass", "kala dabba", "kale dabbe mein kya daalein", "hazardus waste"], "keywords": ["black bin", "domestic hazardous", "batteries", "bulbs", "broken glass", "paint"], "answer": "In Chandigarh's system, the BLACK bin is for domestic hazardous waste — dead batteries, bulbs and tube lights, broken glass and paint containers. These can leak harmful chemicals or cut people, so authorised agencies collect them separately. India's 2026 rules call this kind of waste 'special care waste'. Confirm with Rajnish Ma'am.", "fun": "Tube lights and CFL bulbs have a tiny amount of mercury sealed inside, so they should never be smashed or burnt.", "check": {"q": "Why can't a dead battery go in the green bin?", "a": "It can leak harmful chemicals — it is hazardous waste."}, "hi": "चंडीगढ़ की व्यवस्था में काला डिब्बा घरेलू खतरनाक कचरे के लिए है — पुरानी बैटरी, बल्ब, टूटा काँच और पेंट के डिब्बे।", "filePage": "", "link": "#model/bins", "caution": "Say 'in Chandigarh's system' — the national rules don't fix black as a colour."},
  {"id": "wm-red-bin", "topic": "waste", "q": "What goes in the red bin, and why is sanitary waste kept separate?", "alts": ["red bin", "red dustbin meaning", "what is sanitary waste", "where do diapers go", "where to throw used pads", "why wrap sanitary waste", "laal dabba", "used mask kahan daalein", "sanitry waste"], "keywords": ["red bin", "sanitary waste", "diapers", "pads", "masks", "wrapped"], "answer": "In Chandigarh's system, the RED bin is for sanitary waste — used sanitary pads and diapers, wrapped in paper. Chandigarh's 2026 draft bye-laws also put used masks, gloves and bandages from home here. This waste carries germs, so wrapping it and keeping it separate protects sanitation workers. Confirm with Rajnish Ma'am.", "fun": "In hospitals, a red bag means something totally different — contaminated plastic like tubes, IV sets and gloves (Bio-Medical Waste Rules 2016).", "check": {"q": "Why should sanitary waste be wrapped in paper?", "a": "To keep germs away from sanitation workers."}, "hi": "चंडीगढ़ में लाल डिब्बा सैनिटरी कचरे के लिए है — इस्तेमाल किए पैड और डायपर कागज़ में लपेटकर डालें, ताकि सफ़ाई कर्मचारी कीटाणुओं से बचें।", "filePage": "", "link": "#model/bins", "caution": "Don't mix the hospital meaning of red (contaminated plastic) with the home meaning (sanitary waste)."},
  {"id": "wm-yellow-bin", "topic": "waste", "q": "What is the yellow bin in my model for?", "alts": ["yellow bin", "yellow dustbin meaning", "what goes in yellow bin", "what is biomedical waste", "is yellow for hospital waste", "where do soiled bandages go", "peela dabba", "yellow bin kis liye hai", "biomedicle waste"], "keywords": ["yellow bin", "biomedical waste", "hospital", "bandages", "infection"], "answer": "The YELLOW bin most likely stands for biomedical waste — like soiled bandages, cotton and body waste from hospitals and clinics. This waste can spread infection, so it is sent to a special treatment facility. Yellow is not one of Chandigarh's four home bins, so please confirm its meaning with Rajnish Ma'am.", "fun": "In hospitals, yellow bags are for infectious waste like soiled dressings — and even expired medicines (Bio-Medical Waste Rules 2016).", "check": {"q": "Why must biomedical waste be kept separate?", "a": "It can spread infection."}, "hi": "पीला डिब्बा शायद बायोमेडिकल कचरे के लिए है, जैसे अस्पताल की गंदी पट्टियाँ, जो संक्रमण फैला सकती हैं — इसकी पुष्टि रजनीश मैम से करनी है।", "filePage": "", "link": "#model/bins", "caution": "Say 'most likely' — don't state it as certain until Ma'am confirms."},
  {"id": "wm-special-care", "topic": "waste", "q": "What is special care waste, and where should old medicines and fused bulbs go?", "alts": ["special care waste", "spacial care waste", "where to throw expired medicine", "where does a fused bulb go", "where do old batteries go", "household hazardous waste rules 2026", "old medicine strip kahan daalein", "dawai ka kachra kahan phenkein", "mercury thermometer kahan phenkein"], "keywords": ["special care waste", "medicines", "bulbs", "batteries", "collection centre", "hazardous"], "answer": "Special care waste is household waste that needs extra care because it can harm people or nature — expired medicines, bulbs, batteries, paint containers and old mercury thermometers. Under the 2026 rules it goes to authorised collectors or special collection centres. In Chandigarh, bulbs and batteries go in the black bin; reports differ on medicines (black or red) — ask Rajnish Ma'am.", "fun": "Old-style thermometers with a silvery line contain mercury, a poisonous metal — that's why they count as special care waste.", "check": {"q": "Is a fused bulb wet, dry, sanitary or special care waste?", "a": "Special care waste."}, "hi": "विशेष देखभाल वाला कचरा — पुरानी दवाइयाँ, बल्ब, बैटरी, पेंट के डिब्बे — अधिकृत संग्रह केंद्रों पर दिया जाता है।", "filePage": "", "link": "#model/bins", "caution": "Don't guess whether medicines go in black or red in Chandigarh — ask Ma'am."},
  {"id": "wm-biomedical-colours", "topic": "waste", "q": "What colours are used for biomedical waste in hospitals?", "alts": ["hospital waste colours", "biomedical waste colour coding", "bmw rules 2016", "bio medical waste rules", "hospital dustbin colours", "white bin for needles", "does red mean the same everywhere", "why is red different in hospitals", "aspatal ke kachre ke rang"], "keywords": ["biomedical", "hospital", "BMW Rules 2016", "yellow", "red", "white", "blue"], "answer": "Hospitals follow the Bio-Medical Waste Management Rules, 2016, with four colours: YELLOW for infectious and body waste (soiled dressings, expired medicines), RED for contaminated plastic (tubes, IV sets, gloves), WHITE translucent containers for needles and sharps, and BLUE for glassware and metal implants. So red means sanitary waste in Chandigarh homes, but contaminated plastic in hospitals!", "fun": "Used needles go into a white, see-through, puncture-proof container so they can't poke the people handling them.", "check": {"q": "Where does a used needle go in a hospital?", "a": "The white (translucent) sharps container."}, "hi": "अस्पतालों में चार रंग होते हैं — पीला संक्रामक कचरे के लिए, लाल दूषित प्लास्टिक के लिए, सफ़ेद पारदर्शी डिब्बा सुइयों के लिए और नीला काँच के सामान के लिए।", "filePage": "", "link": "#model/bins", "caution": "Don't say a colour means the same everywhere — always read the bin's label."},
  {"id": "wm-bio-vs-nonbio", "topic": "waste", "q": "What is the difference between biodegradable and non-biodegradable waste?", "alts": ["biodegradable vs non biodegradable", "what is biodegradable waste", "what is non-biodegradable waste", "biodegradable meaning", "examples of non biodegradable waste", "biodegradible", "which waste rots", "does plastic break down", "jaivik aur ajaivik kachra"], "keywords": ["biodegradable", "non-biodegradable", "microorganisms", "plastic", "peels", "decompose"], "answer": "Biodegradable waste is broken down naturally by microorganisms like bacteria and fungi — fruit peels, leftover food, leaves and paper. Non-biodegradable waste does not break down easily — plastic, glass and metal stay around for a very long time. That's why we should refuse, reduce, reuse and recycle non-biodegradable things.", "fun": "Plastic doesn't really vanish — it breaks into tiny bits. Pieces smaller than 5 mm (about a pencil eraser) are called microplastics.", "check": {"q": "Is a banana peel biodegradable?", "a": "Yes!"}, "hi": "बायोडिग्रेडेबल कचरे (जैसे छिलके, कागज़) को सूक्ष्मजीव तोड़ देते हैं; प्लास्टिक, काँच और धातु आसानी से नहीं टूटते।", "filePage": "p21", "link": "#model/bins", "caution": "Say non-biodegradable waste 'does not break down easily' — not 'never'."},
  {"id": "wm-paper-dry", "topic": "waste", "q": "Is paper wet or dry waste? Is it biodegradable?", "alts": ["is paper biodegradable", "is all dry waste non-biodegradable", "why does paper go in the dry bin", "paper is wet or dry", "is cardboard wet waste", "can dry waste be biodegradable", "paper kis dabbe mein jata hai", "papar biodegradable"], "keywords": ["paper", "dry waste", "biodegradable", "cardboard", "blue bin"], "answer": "Paper goes in the DRY (blue) bin — but paper IS biodegradable! So dry waste can have both biodegradable things (paper, cardboard) and non-biodegradable things (plastic, glass, metal). We keep paper in the dry bin because clean, dry paper can be recycled into new paper.", "fun": "Each time paper is recycled its fibres get shorter, so paper can be recycled only a limited number of times — often estimated at about 5 to 7.", "check": {"q": "True or false: all dry waste is non-biodegradable.", "a": "False — paper is dry but biodegradable."}, "hi": "कागज़ सूखे (नीले) डिब्बे में जाता है, पर वह बायोडिग्रेडेबल है — यानी हर सूखा कचरा नॉन-बायोडिग्रेडेबल नहीं होता।", "filePage": "", "link": "#model/bins", "caution": "Don't say 'all dry waste is non-biodegradable'."},
  {"id": "wm-compost", "topic": "waste", "q": "What is composting, and how is compost made?", "alts": ["what is compost", "how to make compost", "composting meaning", "composting process", "compost pit", "how does wet waste become manure", "compost kya hai", "khaad kaise banti hai", "compossting"], "keywords": ["compost", "composting", "manure", "aerobic", "microorganisms", "wet waste"], "answer": "Composting turns wet waste into compost — dark, nutrient-rich material that makes soil healthy. Put peels, vegetable scraps and dry leaves in a pit or bin, keep it moist and turn it now and then so air gets in. Bacteria and fungi break the waste down WITH oxygen (aerobic). In a few weeks to months, you get compost!", "fun": "A compost heap can get warm inside — even above 55°C — because busy microbes give off heat. That heat kills many germs.", "check": {"q": "Does composting need oxygen?", "a": "Yes — composting is aerobic."}, "hi": "कम्पोस्टिंग में छिलके और पत्ते हवा की मौजूदगी में सूक्ष्मजीवों से सड़कर पौष्टिक खाद बन जाते हैं।", "filePage": "p21", "link": "#model/bins", "caution": "Don't say the digger field in the model is a compost pit — ask Rajnish Ma'am what it shows."},
  {"id": "wm-vermicompost", "topic": "waste", "q": "What is vermicomposting?", "alts": ["vermicompost", "what is vermi compost", "composting with earthworms", "red worms compost", "earthworm manure", "difference between compost and vermicompost", "vermicomposting kaise karte hain", "kenchua khaad", "vermicomposing"], "keywords": ["vermicomposting", "earthworms", "red worms", "vermicompost", "manure"], "answer": "Vermicomposting is making compost with the help of earthworms, usually red worms. The worms eat kitchen and plant waste, and their droppings become vermicompost — a very rich manure. Never add plastic, glass or metal, and keep out salty food, pickles and milk, which can grow harmful germs. Keep the pit moist.", "fun": "Earthworms have no teeth! A part called the gizzard, which holds tiny grains of sand, grinds their food.", "check": {"q": "Which animal helps in vermicomposting?", "a": "Earthworms (red worms)."}, "hi": "वर्मीकम्पोस्टिंग में केंचुए रसोई और पौधों का कचरा खाकर बहुत अच्छी खाद बनाते हैं।", "filePage": "p21", "link": ""},
  {"id": "wm-landfill", "topic": "waste", "q": "What is a landfill?", "alts": ["landfill meaning", "what is a sanitary landfill", "difference between landfill and open dump", "what is a dumpsite", "where does leftover waste go", "garbage mountain", "landfill kya hai", "kachre ka pahad", "landfil"], "keywords": ["landfill", "sanitary landfill", "dumpsite", "disposal", "liner"], "answer": "A landfill is a place where waste is buried in the ground. An open dump is just a big heap of mixed garbage — it smells, can catch fire and pollutes. A sanitary landfill is built scientifically, with a lining at the bottom, pipes for dirty liquid and soil cover on top. Under the 2026 rules, only waste that can't be recycled or used for energy should go there.", "fun": "India has about 2,500 old dumpsites, and more than 1,000 have already been fully cleared.", "check": {"q": "Should wet waste go to a landfill?", "a": "No — it should be composted or made into biogas."}, "hi": "लैंडफ़िल वह जगह है जहाँ कचरा ज़मीन में दबाया जाता है; वहाँ सिर्फ़ वही कचरा जाना चाहिए जो न रीसायकल हो सके, न ऊर्जा बन सके।", "filePage": "p9", "link": "", "caution": "Don't say the digger field is a landfill (ask Rajnish Ma'am), and don't say Chandigarh's Dadu Majra dumpsite is finished."},
  {"id": "wm-methane", "topic": "waste", "q": "Why do landfills make methane, and how is garbage linked to global warming?", "alts": ["methane from landfill", "how is garbage linked to global warming", "greenhouse gas from rotting waste", "which gas comes from rotting waste", "why do dumps catch fire", "methane gas landfill", "methene", "methane kya hai", "kachre se global warming kaise"], "keywords": ["methane", "landfill", "greenhouse gas", "global warming", "rotting", "without air"], "answer": "When wet waste is buried in landfills, it rots without air. Microbes then make methane — a strong greenhouse gas that traps heat and adds to global warming. Methane also burns easily, which is one reason dumps catch fire. Composting or making biogas from wet waste helps: a biogas plant captures the methane and uses it as fuel!", "fun": "Over 20 years, methane traps about 80 times more heat than the same amount of carbon dioxide.", "check": {"q": "Name the greenhouse gas that comes from rotting waste.", "a": "Methane."}, "hi": "लैंडफ़िल में गीला कचरा बिना हवा के सड़कर मीथेन बनाता है — एक तेज़ ग्रीनहाउस गैस जो धरती को गर्म करती है।", "filePage": "", "link": "#model/india"},
  {"id": "wm-leachate", "topic": "waste", "q": "What is leachate?", "alts": ["leachate meaning", "what is leechate", "dirty liquid from garbage", "landfill liquid", "garbage juice", "how do landfills pollute groundwater", "leachate kya hai", "kachre se nikalne wala ganda paani"], "keywords": ["leachate", "landfill", "groundwater", "dirty liquid", "liner"], "answer": "Leachate is the dirty, smelly liquid that forms when rainwater and the juices of rotting waste trickle down through a garbage heap. It picks up harmful chemicals and germs and can soak into the soil and underground water. That's why open dumps are dangerous, and why proper landfills collect leachate and treat it.", "fun": "Modern landfills wear a bottom 'raincoat' — a thick clay layer plus a plastic sheet — with pipes that collect leachate for treatment.", "check": {"q": "Which water can leachate pollute?", "a": "Groundwater — the water under the ground."}, "hi": "लीचेट वह गंदा तरल है जो बारिश का पानी और सड़ता कचरा मिलकर बनाते हैं; यह ज़मीन के नीचे के पानी को गंदा कर सकता है।", "filePage": "", "link": ""},
  {"id": "wm-mrf", "topic": "waste", "q": "What is a Material Recovery Facility (MRF)?", "alts": ["what is mrf", "material recovery facility", "material recovery facilty", "where does dry waste go", "dry waste sorting centre", "what happens to blue bin waste", "sorting plant for recycling", "mrf kya hai"], "keywords": ["MRF", "Material Recovery Facility", "sorting", "dry waste", "recycling"], "answer": "A Material Recovery Facility (MRF) is a sorting centre for dry waste. Workers and machines on moving belts separate paper, cardboard, plastics, metals and glass, and each type is sent to recyclers. Under the 2026 rules, dry waste goes to MRFs. Clean, segregated dry waste makes their job much easier!", "fun": "At sorting centres, big magnets pull out steel cans — and fast-spinning magnets can even push aluminium cans off the belt!", "check": {"q": "Which bin's waste goes to an MRF?", "a": "The blue bin — dry waste."}, "hi": "MRF सूखे कचरे का छँटाई केंद्र है, जहाँ कागज़, प्लास्टिक, धातु और काँच अलग करके रीसायकल के लिए भेजे जाते हैं।", "filePage": "", "link": "#model/bins"},
  {"id": "wm-7rs", "topic": "waste", "q": "What are the 7Rs?", "alts": ["7 R", "seven Rs", "7 r's", "what are the 7rs of waste management", "name the 7Rs in order", "3R vs 7R", "list of 7rs", "7R kya hain", "saat R"], "keywords": ["7Rs", "Refuse", "Reduce", "Reuse", "Repair", "Repurpose", "Recycle", "Recover"], "answer": "We often hear about the 3Rs — Reduce, Reuse, Recycle — but the 7Rs go further: Refuse, Reduce, Reuse, Repair, Repurpose, Recycle and Recover. They go in order, from the best choice to the last. And they teach one big lesson: 'The best waste is the waste we never create.'", "fun": "Your model shows the last R, Recover, with its Plastic-to-Energy machine.", "check": {"q": "Which R comes first?", "a": "Refuse."}, "hi": "7R हैं — रिफ़्यूज़, रिड्यूस, रीयूज़, रिपेयर, रीपर्पज़, रीसायकल और रिकवर; सबसे अच्छा कचरा वह है जो हम कभी बनाते ही नहीं।", "filePage": "p23", "link": "#model/wte"},
  {"id": "wm-refuse", "topic": "waste", "q": "What does Refuse mean in the 7Rs? Give an example.", "alts": ["refuse meaning", "first R", "what is refuse", "example of refuse", "say no to plastic", "how to refuse plastic", "refuse kya hai 7r mein", "mana karna", "refuze"], "keywords": ["Refuse", "say no", "single-use plastic", "cloth bag", "first R"], "answer": "Refuse means saying 'No, thank you' to things we don't really need — especially single-use plastic. Example: refuse a plastic carry bag and carry your own cloth bag, or refuse a plastic straw. It is the FIRST R because if we never take it, it never becomes waste!", "fun": "India has banned 19 single-use plastic items since 1 July 2022 — the whole country practising 'Refuse'!", "check": {"q": "What can you carry so you can refuse a plastic bag?", "a": "A cloth or jute bag."}, "hi": "रिफ़्यूज़ यानी ग़ैर-ज़रूरी चीज़ों को 'ना' कहना — जैसे प्लास्टिक की थैली की जगह अपना कपड़े का थैला ले जाना।", "filePage": "p23", "link": ""},
  {"id": "wm-reduce", "topic": "waste", "q": "What does Reduce mean? Give an example.", "alts": ["reduce meaning", "second R", "example of reduce", "how to reduce waste", "ways to reduce waste at home", "reduce kya hai", "kam karna", "reduse"], "keywords": ["Reduce", "use less", "example", "paper", "second R"], "answer": "Reduce means using less, so less waste is made. Examples: write on both sides of the paper, take only as much food as you will eat, and choose things with less packaging. Using less also saves water, energy and money!", "fun": "Writing or printing on both sides of a page uses half the paper — that's Reduce in action!", "check": {"q": "How can you reduce food waste at lunch?", "a": "Take only as much as you can eat."}, "hi": "रिड्यूस यानी कम इस्तेमाल करना — जैसे कागज़ के दोनों तरफ़ लिखना और उतना ही खाना लेना जितना खा सकें।", "filePage": "p23", "link": ""},
  {"id": "wm-reuse", "topic": "waste", "q": "What does Reuse mean? Give an example.", "alts": ["reuse meaning", "third R", "example of reuse", "how can we reuse things", "reuse vs recycle", "reuse kya hai", "dobara istemal karna", "reus"], "keywords": ["Reuse", "use again", "same purpose", "refill", "bottle"], "answer": "Reuse means using something again for the SAME purpose instead of throwing it away. Examples: refill your steel water bottle, carry a steel tiffin instead of foil or plastic, and reuse gift bags and boxes. Reuse beats recycling, because the thing doesn't have to be broken down and made again.", "fun": "Mumbai's dabbawalas have delivered home-cooked lunches in reusable tiffin boxes since 1890 — more than 130 years of Reuse!", "check": {"q": "Refilling a water bottle — reuse or recycle?", "a": "Reuse."}, "hi": "रीयूज़ यानी किसी चीज़ को उसी काम के लिए दोबारा इस्तेमाल करना — जैसे स्टील की बोतल फिर से भरना।", "filePage": "p23", "link": ""},
  {"id": "wm-repair", "topic": "waste", "q": "What does Repair mean? Give an example.", "alts": ["repair meaning", "fourth R", "example of repair", "why repair things", "fix instead of throwing away", "repair kya hai 7r mein", "marammat karna", "repare"], "keywords": ["Repair", "fix", "mend", "example", "e-waste"], "answer": "Repair means fixing something broken so it can be used again, instead of buying a new one. Examples: stitch a torn school bag, mend a broken chair, or get a phone or fan repaired. It saves money and keeps things — and e-waste — out of the garbage. Repair before you replace!", "fun": "India launched a Right to Repair portal in 2022, where companies can share repair information so people can fix their products.", "check": {"q": "Your bag strap breaks. What does the Repair R say?", "a": "Stitch or fix it instead of throwing it away."}, "hi": "रिपेयर यानी टूटी चीज़ को ठीक करके फिर से इस्तेमाल करना — जैसे फटा बस्ता सिलवाना।", "filePage": "p23", "link": ""},
  {"id": "wm-repurpose", "topic": "waste", "q": "What does Repurpose mean, and how is it different from Reuse?", "alts": ["repurpose meaning", "fifth R", "difference between reuse and repurpose", "reuse vs repurpose", "example of repurpose", "best out of waste", "repurpose kya hai", "naya upyog", "repurpos"], "keywords": ["Repurpose", "new purpose", "reuse vs repurpose", "eco-brick", "flower pot"], "answer": "Repurpose means giving an old thing a NEW job. Reuse = same purpose (refilling a bottle with water). Repurpose = new purpose (turning an old bottle into a flower pot or pen stand, or an old T-shirt into a bag). An eco-brick is repurposing too: a bottle packed with clean, dry plastic becomes a building block!", "fun": "Eco-bricks can be used to build benches, walls and garden borders.", "check": {"q": "An old jar used as a pen stand — reuse or repurpose?", "a": "Repurpose (a new purpose)."}, "hi": "रीपर्पज़ यानी पुरानी चीज़ को नया काम देना — जैसे पुरानी बोतल को गमला बनाना; रीयूज़ में काम वही रहता है।", "filePage": "p23", "link": ""},
  {"id": "wm-recycle", "topic": "waste", "q": "What does Recycle mean? Give an example.", "alts": ["recycle meaning", "sixth R", "what is recycling", "example of recycling", "how does recycling work", "recycle kya hai", "recycling kaise hoti hai", "recycal"], "keywords": ["Recycle", "new products", "paper", "metal", "dry waste"], "answer": "Recycle means breaking down or melting used materials to make NEW products. Old newspapers become new paper, metal cans are melted into new cans, and some plastics are made into new things. Recycling works best when dry waste is clean and segregated. It comes after Refuse, Reduce, Reuse, Repair and Repurpose because recycling still needs energy.", "fun": "The recycling symbol — three chasing arrows — was designed by college student Gary Anderson in 1970 for a contest linked to the first Earth Day.", "check": {"q": "Why must dry waste be clean for recycling?", "a": "Dirty, wet waste is hard to recycle."}, "hi": "रीसायकल यानी पुरानी चीज़ों को तोड़कर या पिघलाकर नई चीज़ें बनाना — जैसे पुराने अख़बार से नया कागज़।", "filePage": "p23", "link": "#model/bins"},
  {"id": "wm-recover", "topic": "waste", "q": "What does Recover mean in the 7Rs?", "alts": ["recover meaning", "last R", "seventh R", "what is recover", "example of recover", "energy recovery from waste", "recover kya hai", "recovar"], "keywords": ["Recover", "energy", "waste-to-energy", "biogas", "last R", "non-recyclable"], "answer": "Recover is the LAST R: getting energy or useful material back from waste that cannot be reused or recycled. Examples: biogas from wet waste, or electricity from non-recyclable waste in special closed plants with pollution control — the idea your Plastic-to-Energy machine shows. We must never burn plastic in the open!", "fun": "India's waste-to-energy capacity grew from about 230 MW in 2014 to about 878 MW in 2026 — almost four times bigger.", "check": {"q": "Is Recover the first choice or the last choice?", "a": "The last choice."}, "hi": "रिकवर आख़िरी R है — जो कचरा रीसायकल न हो सके, उससे खास संयंत्रों में ऊर्जा लेना; प्लास्टिक को खुले में कभी न जलाएँ।", "filePage": "p23", "link": "#model/wte", "caution": "Never say 'just burn plastic for electricity' — only non-recyclable waste, in controlled plants with pollution control."},
  {"id": "wm-7rs-order", "topic": "waste", "q": "Why is Refuse first and Recover last? What does 'the best waste is the waste we never create' mean?", "alts": ["why is refuse first", "why is recover last", "which R is best", "which r is most important", "order of the 7Rs", "best waste is the waste we never create meaning", "sabse achha kachra kaunsa hai", "why is refuse the best r"], "keywords": ["order", "Refuse first", "Recover last", "best waste", "never create", "waste hierarchy"], "answer": "The 7Rs go from best to last. Refuse stops waste from ever being made — so nothing needs collecting, sorting or treating! Each later R saves less. Recover still uses up the material and needs special plants, so it comes last. That's why your file says: 'The best waste is the waste we never create.'", "fun": "India's 2026 waste rules follow a 'waste hierarchy' too: prevent and reduce first, then reuse, recycle, recover — and landfill disposal last.", "check": {"q": "Name one thing you can refuse.", "a": "A plastic bag, straw or plastic spoon."}, "hi": "रिफ़्यूज़ सबसे पहले है क्योंकि इससे कचरा बनता ही नहीं, और रिकवर सबसे आख़िर में; सबसे अच्छा कचरा वह है जो हम कभी बनाते ही नहीं।", "filePage": "p23", "link": "#thoughts"},
  {"id": "wm-smart-bins", "topic": "waste", "q": "What is a smart bin, and how does IoT help in waste management?", "alts": ["smart bin", "smart dustbin", "what is iot", "iot full form", "how do smart bins work", "sensor dustbin", "internet of things in waste", "smart dabba kaise kaam karta hai", "smrt bin"], "keywords": ["smart bin", "IoT", "Internet of Things", "sensor", "fill level", "alert"], "answer": "IoT means 'Internet of Things' — everyday things connected to the internet. A smart bin has a sensor that measures how full it is. When it is nearly full, it sends an alert, so the truck comes only where it's needed. That means fewer overflowing bins and better collection routes. Your file says smart bins help India get cleaner every day.", "fun": "Many smart bins use an ultrasonic sensor: it sends out a sound too high for us to hear and times the echo bouncing off the rubbish — like a bat!", "check": {"q": "What does IoT stand for?", "a": "Internet of Things."}, "hi": "स्मार्ट डस्टबिन में सेंसर होता है जो भरने पर इंटरनेट से सूचना भेजता है, ताकि गाड़ी समय पर आकर उसे खाली करे।", "filePage": "p23", "link": ""},
  {"id": "wm-ai-sorting", "topic": "waste", "q": "How can AI and robots help sort waste?", "alts": ["ai in waste management", "ai sorting", "robots sorting garbage", "how does ai help recycling", "machine sorting of waste", "technology in waste management", "robot kachra kaise chhante hain", "artificial intelligence se kachra", "AI robot dustbin"], "keywords": ["AI", "robots", "sorting", "cameras", "recycling", "technology"], "answer": "At big sorting centres, cameras with AI (artificial intelligence) look at waste moving on a belt and recognise each item — a bottle, a can, a carton. Then robot arms or quick puffs of air push it into the right pile. This makes recycling faster and safer for workers. But AI works best when we segregate at home first!", "fun": "Some sorting machines shine invisible near-infrared light on plastics — different plastics reflect it differently, so the machine can tell them apart.", "check": {"q": "Can robots replace segregating waste at home?", "a": "No — segregation at source is still most important."}, "hi": "AI कैमरे और रोबोट बेल्ट पर चलते कचरे को पहचानकर अलग करते हैं, जिससे रीसायक्लिंग तेज़ और सुरक्षित होती है।", "filePage": "p23", "link": ""},
  {"id": "wm-resource-recovery", "topic": "waste", "q": "What is resource recovery ('Waste to Wealth')?", "alts": ["resource recovery", "resourse recovery", "waste to wealth", "how can waste become useful", "turn waste into resource", "what useful things come from waste", "kachre se kanchan", "waste se kya bana sakte hain"], "keywords": ["resource recovery", "waste to wealth", "manure", "biogas", "recycling", "energy"], "answer": "Resource recovery means getting useful things back from waste instead of dumping it in landfills. Wet waste becomes manure (compost) and biogas, dry waste is recycled into new products, waste plastic can even go into roads, and only leftover non-recyclable waste is used for energy. Your file calls it a core pillar of waste management under Swachh Bharat.", "fun": "In August 2026, India approved a new GOBARdhan scheme worth ₹23,731 crore to turn waste like cattle dung into compressed biogas.", "check": {"q": "Name one resource we can get from wet waste.", "a": "Compost (manure) or biogas."}, "hi": "रिसोर्स रिकवरी यानी कचरे से उपयोगी चीज़ें वापस पाना — गीले कचरे से खाद और बायोगैस, सूखे कचरे से नई चीज़ें।", "filePage": "p20", "link": "#model/biogas"},
  {"id": "pr-single-use-plastic", "topic": "plastic-rivers", "q": "What are single-use plastics?", "alts": ["what is single use plastic", "what is SUP", "single use plastic examples", "what is plastic made from?", "singel use plastik kya hai", "give examples of single-use plastics", "use and throw plastic meaning", "is plastic made from petroleum?", "disposable plastic meaning"], "keywords": ["single-use plastic", "SUP", "used once", "petroleum", "disposable", "examples"], "answer": "Single-use plastics are plastic things we use just once, for a short time, and then throw away. They are made mainly from petroleum and other fossil fuels (petrochemicals). Examples: carry bags, straws, coffee stirrers, soda bottles, wrappers and packaging. We use them for minutes, but they stay in the environment for a very long time!", "fun": "The first fully synthetic plastic, Bakelite, was invented in 1907 by the chemist Leo Baekeland.", "check": {"q": "Name two single-use plastic items you see every day.", "a": "Any two: carry bags, straws, stirrers, wrappers, soda bottles, packaging."}, "hi": "सिंगल-यूज़ प्लास्टिक वह प्लास्टिक है जिसे एक बार थोड़ी देर इस्तेमाल करके फेंक दिया जाता है, जैसे थैली, स्ट्रॉ और रैपर; यह ज़्यादातर पेट्रोलियम से बनता है।", "filePage": "p22", "link": "#viva"},
  {"id": "pr-sup-ban-19-items", "topic": "plastic-rivers", "q": "Which single-use plastic items are banned in India?", "alts": ["what plastic is banned in india", "plastic ban 2022", "when was single use plastic banned in india", "19 items ban", "plastic ban kab laga", "is plastic straw banned in india", "list of banned plastic items", "single use plastic ban date"], "keywords": ["ban", "19 items", "1 July 2022", "straws", "cutlery", "earbuds", "thermocol"], "answer": "Since 1 July 2022, India has banned 19 single-use plastic items. They include plastic straws, stirrers, cups, plates, spoons and forks, earbuds with plastic sticks, balloon sticks, candy and ice-cream sticks, plastic flags and thermocol decorations. Making, selling or using them is not allowed. These items were picked because they are not very useful and easily become litter.", "fun": "Plastic flags are on the banned list too, so for Independence Day, choose paper or cloth flags!", "check": {"q": "Since which date have the 19 single-use plastic items been banned in India?", "a": "1 July 2022."}, "hi": "1 जुलाई 2022 से भारत में 19 सिंगल-यूज़ प्लास्टिक चीज़ों पर रोक है, जैसे स्ट्रॉ, प्लास्टिक के चम्मच-प्लेट, ईयरबड की डंडियाँ और थर्मोकोल की सजावट।", "filePage": "", "link": "#viva", "caution": "Don't say 'all plastic is banned'. Plastic bottles and many packets are still allowed."},
  {"id": "pr-carry-bag-ban", "topic": "plastic-rivers", "q": "Are plastic carry bags banned in India?", "alts": ["is polythene banned", "plastic bag ban", "120 micron rule", "polythene ki thaili band hai kya", "can shops give plastic bags", "thin plastic bag banned", "what is a micron in plastic bags", "plastic carry bag thickness rule", "is polythene banned in chandigarh"], "keywords": ["carry bag", "polythene", "120 microns", "31 December 2022", "thin bags", "Chandigarh"], "answer": "The thin ones are! Since 31 December 2022, plastic carry bags thinner than 120 microns are banned all over India (from 30 September 2021 the limit was 75 microns). Thin bags tear fast and become litter, while thicker ones can be reused. Chandigarh also has its own stricter local ban on plastic carry bags. The best choice is a cloth bag!", "fun": "A micron is one-thousandth of a millimetre, so a 120-micron bag is only 0.12 mm thick!", "check": {"q": "Plastic carry bags thinner than how many microns are banned all over India?", "a": "120 microns."}, "hi": "31 दिसंबर 2022 से पूरे भारत में 120 माइक्रोन से पतली प्लास्टिक की थैलियों पर रोक है, और चंडीगढ़ में इससे भी सख़्त स्थानीय रोक है; सबसे अच्छा विकल्प कपड़े का थैला है।", "filePage": "", "link": "#viva", "caution": "Don't say every plastic bag is banned all over India. The national rule is about bags thinner than 120 microns."},
  {"id": "pr-plastic-harm", "topic": "plastic-rivers", "q": "Why is single-use plastic harmful?", "alts": ["why is plastic bad", "plastic harmful kyon hai", "plastic pollution effects", "why should we not use plastic bags", "what happens to plastic we throw away", "is plastic biodegradable", "does plastic decompose", "plastic se kya nuksan hai"], "keywords": ["harmful", "non-biodegradable", "drains", "animals", "litter", "pollution"], "answer": "Plastic is non-biodegradable, which means it does not break down easily. Thrown-away plastic blocks drains so rainwater cannot flow, floats into rivers, and animals can swallow it or get tangled in it. Over time it breaks into tiny bits called microplastics. Burning it in the open releases poisonous gases. That's why refusing and reducing plastic is the best solution.", "fun": "In 1998 Sikkim became India's first state to ban plastic carry bags, after plastic was partly blamed for blocking drains during heavy rains and landslides.", "check": {"q": "Is plastic biodegradable or non-biodegradable?", "a": "Non-biodegradable. It does not break down easily."}, "hi": "प्लास्टिक आसानी से नहीं गलता; यह नालियाँ जाम करता है, नदियों तक पहुँचता है, जानवरों को नुकसान पहुँचाता है और टूटकर माइक्रोप्लास्टिक बन जाता है।", "filePage": "p22", "link": "#viva", "caution": "Say plastic 'does not break down easily', not that it 'never' breaks down."},
  {"id": "pr-microplastics", "topic": "plastic-rivers", "q": "What are microplastics?", "alts": ["what is microplastic", "micro plastic meaning", "microplastic kya hota hai", "how are microplastics formed", "tiny plastic pieces", "where are microplastics found", "microplastics in water", "mircoplastics"], "keywords": ["microplastics", "5 mm", "tiny pieces", "break apart", "water", "soil"], "answer": "Microplastics are tiny pieces of plastic smaller than 5 millimetres, about the size of a pencil eraser or smaller. Most form when bigger plastic like bags and bottles slowly breaks apart into smaller and smaller bits. Some are made tiny on purpose, like scrub beads in some face washes. They end up in rivers, soil and the sea, where water animals can swallow them.", "fun": "Scientists found microplastics in snow near the top of Mount Everest, at 8,440 metres. They probably came from climbers' clothes and gear!", "check": {"q": "Microplastics are smaller than how many millimetres?", "a": "5 millimetres."}, "hi": "माइक्रोप्लास्टिक 5 मिलीमीटर से छोटे प्लास्टिक के टुकड़े हैं, जो बड़े प्लास्टिक के टूटने से बनते हैं और पानी, मिट्टी व जीवों तक पहुँच जाते हैं।", "filePage": "", "link": "#viva"},
  {"id": "pr-refuse-cloth-bag", "topic": "plastic-rivers", "q": "How can I reduce single-use plastic in my daily life?", "alts": ["how to reduce plastic", "alternatives to plastic bags", "what can we use instead of plastic", "why use a cloth bag", "plastic kam kaise karein", "kapde ka thaila kyon", "what does refuse mean in 7Rs", "how can students avoid plastic"], "keywords": ["refuse", "reduce", "cloth bag", "steel bottle", "tiffin", "alternatives"], "answer": "Start with REFUSE, the first of the 7Rs: just say 'no' to plastic you don't need. Carry a cloth bag for shopping and your own steel bottle and tiffin box, and skip straws and plastic spoons. One cloth bag, used again and again, can replace many plastic bags. As your file says, 'The best waste is the waste we never create.'", "fun": "3 July is International Plastic Bag Free Day, a perfect day to show off your cloth bag!", "check": {"q": "Which R comes first in the 7Rs?", "a": "Refuse."}, "hi": "प्लास्टिक कम करने के लिए पहले 'ना' कहो: कपड़े का थैला, अपनी स्टील की बोतल और टिफ़िन साथ रखो, और स्ट्रॉ व प्लास्टिक के चम्मच मत लो।", "filePage": "p23", "link": "#thoughts"},
  {"id": "pr-eco-brick-what", "topic": "plastic-rivers", "q": "What is an eco-brick?", "alts": ["eco brick meaning", "ecobrick kya hai", "what is an ecobrick made of", "plastic bottle brick", "eko brick", "what can we build with eco-bricks", "uses of eco-bricks", "bottle filled with plastic"], "keywords": ["eco-brick", "plastic bottle", "packed", "non-recyclable", "build", "benches"], "answer": "An eco-brick is an empty plastic bottle packed very tightly with clean, dry, non-recyclable plastic waste, like wrappers and thin bags, until it becomes hard and solid. It can then be used as a building block for benches, garden borders and small walls. It keeps low-value plastic out of drains and rivers.", "fun": "A well-packed eco-brick is so solid that it can hold a person's weight without bending!", "check": {"q": "What do we fill inside an eco-brick?", "a": "Clean, dry, non-recyclable plastic waste, packed tightly."}, "hi": "इको-ब्रिक एक खाली प्लास्टिक बोतल है जिसमें साफ़ और सूखा प्लास्टिक कचरा कसकर भरा जाता है; इससे बेंच और छोटी दीवारें बनाई जा सकती हैं।", "filePage": "p22", "link": "#viva"},
  {"id": "pr-eco-brick-make", "topic": "plastic-rivers", "q": "How do you make an eco-brick?", "alts": ["steps to make an eco brick", "eco brick kaise banate hain", "how to fill an ecobrick", "what stick is used in an ecobrick", "how tight should an eco brick be", "make an ecobrick at home", "ecobrick banane ka tarika"], "keywords": ["make", "steps", "stick", "pack", "bottle", "weigh"], "answer": "1) Collect plastic wrappers and bags, then wash and dry them. 2) Cut them into small pieces (ask an adult to help with scissors). 3) Push them into a clean plastic bottle a little at a time and press down hard with a smooth stick. 4) Keep packing until the bottle is rock-hard, then close the cap. Leave out paper, food, glass and metal.", "fun": "Eco-brickers call their packing stick a 'magic wand'! A good 600 ml eco-brick should weigh more than 200 grams.", "check": {"q": "What do you use to press the plastic down inside the bottle?", "a": "A smooth stick."}, "hi": "साफ़-सूखे प्लास्टिक को छोटे टुकड़ों में काटो, बोतल में थोड़ा-थोड़ा डालकर डंडी से कसकर दबाओ, और बोतल पत्थर जैसी सख़्त हो जाए तो ढक्कन बंद करो।", "filePage": "p22", "link": ""},
  {"id": "pr-eco-brick-clean-dry", "topic": "plastic-rivers", "q": "Why must the plastic in an eco-brick be clean and dry?", "alts": ["why clean plastic for eco brick", "can i put dirty plastic in an ecobrick", "why dry plastic", "eco brick mein geela plastic kyon nahi", "what happens if the plastic is wet", "why wash wrappers before an eco brick", "ecobrick smell"], "keywords": ["clean", "dry", "microbes", "methane", "smell", "bloat"], "answer": "Food bits and water left on plastic let microbes grow inside the closed bottle. They can make methane gas and bad smells, and the bottle can bloat. Clean, dry plastic packs tightly and keeps the brick safe and strong. So always wash and dry wrappers before you pack them.", "fun": "Dirty plastic can make methane form inside a closed eco-brick. Methane is the same gas that makes up most of biogas!", "check": {"q": "Name one thing that can happen if you pack wet, dirty plastic.", "a": "Microbes grow, it smells, methane gas forms and the bottle can bloat."}, "hi": "गंदे या गीले प्लास्टिक में सूक्ष्मजीव पनपते हैं, मीथेन गैस और बदबू बनती है और बोतल फूल सकती है, इसलिए प्लास्टिक साफ़ और सूखा होना चाहिए।", "filePage": "p22", "link": "#viva"},
  {"id": "pr-eco-brick-mission", "topic": "plastic-rivers", "q": "Are eco-bricks an official part of the Clean India Mission?", "alts": ["is ecobrick part of swachh bharat", "eco brick clean india mission", "are eco bricks crucial to swachh bharat", "does the government make eco bricks", "why are eco bricks helpful", "eco brick ka swachh bharat se kya sambandh", "eco bricks zaroori hain kya"], "keywords": ["official", "Clean India Mission", "Swachh Bharat", "schools", "communities", "helpful"], "answer": "No, eco-bricks are not an official part of the mission. They are a simple, helpful idea that schools and communities can use to support it. They trap non-recyclable plastic where it is made, so it doesn't end up in drains or rivers. But refusing and reducing plastic is still better than packing it into bottles.", "fun": "", "check": {"q": "Fill in the blank: Eco-bricks are a simple way that ___ and communities can help the Clean India Mission.", "a": "Schools."}, "hi": "इको-ब्रिक स्वच्छ भारत मिशन का आधिकारिक हिस्सा नहीं हैं, पर स्कूल और समुदाय इनसे मिशन में मदद कर सकते हैं।", "filePage": "p22", "link": "#stage", "caution": "Your file (p22) says eco-bricks are 'crucial to the Clean India Mission'. Say 'a simple way schools and communities can help' instead."},
  {"id": "pr-plastic-man-who", "topic": "plastic-rivers", "q": "Who is the Plastic Man of India?", "alts": ["plastic man of india kaun hai", "who is rajagopalan vasudevan", "vasudevan sir", "plastic man", "who invented plastic roads", "rajgopalan vasudevan", "who made roads from plastic", "plastic road wale scientist"], "keywords": ["Plastic Man of India", "Rajagopalan Vasudevan", "Madurai", "Thiagarajar College", "chemistry professor"], "answer": "The Plastic Man of India is Professor Rajagopalan Vasudevan, a chemistry professor at Thiagarajar College of Engineering in Madurai, Tamil Nadu. He found a way to use waste plastic to build strong roads. His picture is in the centre of your model!", "fun": "Former President Dr A.P.J. Abdul Kalam visited his college and encouraged him to lay a plastic road on the campus.", "check": {"q": "In which city is his college?", "a": "Madurai, Tamil Nadu."}, "hi": "प्लास्टिक मैन ऑफ़ इंडिया प्रोफ़ेसर राजगोपालन वासुदेवन हैं; वे मदुरै के थियागराजर कॉलेज ऑफ़ इंजीनियरिंग में रसायन विज्ञान के प्रोफ़ेसर हैं और उन्होंने प्लास्टिक कचरे से सड़कें बनाने का तरीका खोजा।", "filePage": "after p21", "link": "#model/plasticman", "caution": "Don't say he 'invented plastic'. He found a new use for waste plastic."},
  {"id": "pr-plastic-road-how", "topic": "plastic-rivers", "q": "How is waste plastic used to make roads?", "alts": ["plastic road kaise banti hai", "how are plastic roads made", "plastic road process", "is the road made only of plastic", "what is bitumen", "plastic in road construction", "plastik road", "steps of making a plastic road"], "keywords": ["shredded", "hot stones", "bitumen", "coat", "road", "process"], "answer": "First, waste plastic like thin bags and cups is cleaned and shredded into small pieces. The pieces are sprinkled on hot stones, and the plastic melts and coats them. Then these coated stones are mixed with bitumen, the black tar-like material, and laid as a road. So the road is not made only of plastic!", "fun": "Government advice for city roads is to use waste plastic of up to about 8% of the bitumen's weight, so plastic is just a small part of the mix.", "check": {"q": "What is the black, tar-like material mixed with the plastic-coated stones?", "a": "Bitumen."}, "hi": "प्लास्टिक के छोटे टुकड़े गरम पत्थरों पर डाले जाते हैं, वे पिघलकर पत्थरों पर परत चढ़ा देते हैं, फिर इन पत्थरों को बिटुमेन (तारकोल) में मिलाकर सड़क बनाई जाती है।", "filePage": "after p21", "link": "#model/plasticman", "caution": "Don't say the road is made only of plastic. Plastic is a small part of the mix."},
  {"id": "pr-plastic-road-benefits", "topic": "plastic-rivers", "q": "What are the benefits of plastic roads?", "alts": ["why are plastic roads good", "advantages of plastic roads", "plastic road ke fayde", "are plastic roads strong", "do plastic roads have fewer potholes", "why use plastic in roads", "benifits of plastic road"], "keywords": ["benefits", "potholes", "water", "strong", "hard-to-recycle", "durable"], "answer": "Plastic roads use up plastic waste that is hard to recycle, so less of it ends up in drains and dumps. The plastic coating helps the stones resist water. Studies of village roads, checked by IIT Madras, found fewer cracks and potholes than on ordinary roads. It's a smart way to turn a problem into something useful!", "fun": "A 2016 news report said a plastic road laid in 2002 on Jambulingam Street, Chennai, had come through a major flood and several monsoons without the usual cracks and potholes!", "check": {"q": "Why do plastic roads get fewer potholes?", "a": "The plastic coating helps the road resist water."}, "hi": "प्लास्टिक सड़कें मुश्किल से रीसाइकिल होने वाले प्लास्टिक का उपयोग करती हैं, पानी से कम ख़राब होती हैं, और अध्ययनों में इनमें आम सड़कों से कम दरारें और गड्ढे मिले।", "filePage": "after p21", "link": "#model/plasticman", "caution": "Don't say plastic roads never get potholes. They just get fewer."},
  {"id": "pr-first-plastic-road", "topic": "plastic-rivers", "q": "When was the first plastic road built?", "alts": ["first plastic road in india", "when did plastic roads start", "pehli plastic road kab bani", "where was the first plastic road made", "jambulingam street", "plastic road 2002", "which year was the first plastic road made"], "keywords": ["first plastic road", "2002", "Madurai", "college campus", "Jambulingam Street", "Chennai"], "answer": "In 2002! Professor Vasudevan developed the method around 2001. In 2002 he first tested it on a short road on his college campus in Madurai. That same year, a plastic road was also laid on Jambulingam Street in Chennai, one of India's first. Since then, plastic roads have been built in many states.", "fun": "His first test road on the college campus was only about 60 feet long, and he says it was still intact years later!", "check": {"q": "In which year was the first plastic road laid?", "a": "2002."}, "hi": "पहली प्लास्टिक सड़क 2002 में बनी: पहले मदुरै में उनके कॉलेज परिसर में, और उसी साल चेन्नई की जम्बुलिंगम स्ट्रीट पर भी।", "filePage": "", "link": "#model/plasticman"},
  {"id": "pr-free-technology", "topic": "plastic-rivers", "q": "Did Professor Vasudevan sell his plastic road technology?", "alts": ["did he give his technology for free", "plastic road patent", "why did he not sell his invention", "free mein technology di", "who owns plastic road technology", "did vasudevan become rich from plastic roads", "gifted technology to the government"], "keywords": ["free", "patent", "Government of India", "gift", "technology", "shared"], "answer": "No! He shared his plastic road technology with the Government of India free of cost instead of selling it for money, so it could be used across the country. That's a great example of using science to help everyone, not just yourself.", "fun": "The plastic road method was patented in 2006, and the technology was still given to the government for free.", "check": {"q": "Did he sell his technology or give it free?", "a": "He gave it to the Government of India for free."}, "hi": "प्रोफ़ेसर वासुदेवन ने अपनी प्लास्टिक सड़क तकनीक बेची नहीं, बल्कि भारत सरकार को मुफ़्त में दे दी।", "filePage": "after p21", "link": "#model/plasticman"},
  {"id": "pr-padma-shri", "topic": "plastic-rivers", "q": "Which award did the Plastic Man of India receive?", "alts": ["padma shri 2018", "what award did vasudevan get", "plastic man award", "kaunsa puraskar mila", "when did he get the padma shri", "what is the padma shri", "padamshri plastic man"], "keywords": ["Padma Shri", "2018", "award", "civilian honour"], "answer": "He received the Padma Shri in 2018 for his work on using waste plastic in roads. The Padma Shri is one of India's highest civilian awards. It is the fourth-highest, after the Bharat Ratna, Padma Vibhushan and Padma Bhushan.", "fun": "The Padma awards are announced every year on 25 January, the eve of Republic Day.", "check": {"q": "In which year did Professor Vasudevan get the Padma Shri?", "a": "2018."}, "hi": "प्रोफ़ेसर राजगोपालन वासुदेवन को 2018 में पद्म श्री मिला, जो भारत का चौथा सबसे बड़ा नागरिक सम्मान है।", "filePage": "after p21", "link": "#model/plasticman", "caution": "The year is hard to read in your file ('201_'). The correct year is 2018."},
  {"id": "pr-plastic-roads-india", "topic": "plastic-rivers", "q": "Does the government use plastic roads in India?", "alts": ["how many plastic roads in india", "plastic road rule 2015", "is it compulsory to use plastic in roads", "plastic roads in villages", "43000 km plastic roads", "kya sarkar plastic road banati hai", "plastic roads near cities", "PMGSY plastic roads"], "keywords": ["2015", "big cities", "village roads", "43,000 km", "government", "rule"], "answer": "Yes! Since 2015, the government has asked road builders to use waste plastic when renewing highways near big cities (within 50 km of cities with more than 5 lakh people). Waste plastic is used in village roads too. Government data says more than 43,000 km of village roads were made using waste plastic by July 2025.", "fun": "43,000 km of road is longer than the distance around the whole Earth at the equator, which is about 40,000 km!", "check": {"q": "Since which year has the government asked road builders near big cities to use waste plastic?", "a": "2015."}, "hi": "हाँ, 2015 से बड़े शहरों के पास सड़कों में प्लास्टिक कचरा इस्तेमाल करने को कहा गया है, और जुलाई 2025 तक 43,000 किलोमीटर से ज़्यादा गाँव की सड़कें प्लास्टिक कचरे से बनीं।", "filePage": "after p21", "link": "#model/plasticman", "caution": "Your file calls plastic roads 'a cornerstone of Swachh Bharat'. That is an exaggeration, so use the 2015 rule instead."},
  {"id": "pr-still-reduce", "topic": "plastic-rivers", "q": "If plastic can be used in roads, why should we still reduce plastic?", "alts": ["do plastic roads solve the plastic problem", "why not use all plastic in roads", "can we use as much plastic as we want", "plastic road hai to plastic kam kyon karein", "is the plastic road the solution", "roads vs reducing plastic", "why refuse plastic if it can be recycled"], "keywords": ["reduce", "refuse", "not collected", "rivers", "microplastics", "7Rs"], "answer": "Roads use only a small part of our plastic waste, and a lot of plastic is never collected. It ends up in drains, rivers and the sea, where it breaks into microplastics. Making plastic also uses up petroleum. That's why Refuse and Reduce come first in the 7Rs. Plastic roads are just a way to use what is left over.", "fun": "Beating plastic pollution was the theme of World Environment Day in 2018 (hosted by India), 2023 and 2025!", "check": {"q": "Do plastic roads solve the whole plastic problem?", "a": "No. Refusing and reducing plastic is still most important."}, "hi": "सड़कों में बहुत थोड़ा प्लास्टिक लगता है और बहुत-सा प्लास्टिक नदियों में पहुँच जाता है, इसलिए प्लास्टिक को मना करना और कम करना सबसे ज़रूरी है।", "filePage": "p23", "link": "#viva", "caution": "Don't say plastic roads 'solve the whole plastic problem'."},
  {"id": "pr-keep-rivers-clean", "topic": "plastic-rivers", "q": "How can we keep our rivers clean?", "alts": ["how to keep rivers clean", "nadiyon ko saaf kaise rakhein", "river pollution solutions", "how can we stop river pollution", "ways to save rivers", "clean river tips", "river cleaning in clean india mission", "how to keep rivres clean"], "keywords": ["rivers", "clean", "stop dumping", "sewage treatment", "clean-up", "trees", "skimmers"], "answer": "Your file gives three big ideas: stop waste at the source, treat dirty water, and involve local communities. We should never throw garbage or puja offerings into rivers. We can reduce plastic, join clean-up drives and plant trees on riverbanks. The government builds sewage treatment plants, makes factories treat their wastewater, and uses trash skimmers to remove floating waste.", "fun": "The Ganga was declared India's National River on 4 November 2008.", "check": {"q": "Name one thing YOU can do to keep rivers clean.", "a": "Don't throw garbage or puja waste in, reduce plastic, join a clean-up, or plant trees."}, "hi": "नदियों को साफ़ रखने के लिए उनमें कूड़ा या पूजा सामग्री न डालें, प्लास्टिक कम करें, सफ़ाई अभियान में भाग लें और किनारों पर पेड़ लगाएँ; सरकार सीवेज ट्रीटमेंट प्लांट बनाती है।", "filePage": "p27–28", "link": "#viva"},
  {"id": "pr-no-dumping-rivers", "topic": "plastic-rivers", "q": "Why should we not throw garbage or puja offerings into rivers?", "alts": ["why not throw flowers in the river", "can we put puja samagri in the river", "nadi mein phool kyon nahi daalne chahiye", "is it ok to throw puja items in the ganga", "what to do with old puja flowers", "why is dumping garbage in rivers bad", "kya nadi mein kachra daal sakte hain", "why not throw garbage in water bodies"], "keywords": ["garbage", "puja offerings", "flowers", "rivers", "oxygen", "fish"], "answer": "Garbage and puja offerings like flowers, cloth and plastic wrappers pollute river water. As flowers and food rot, bacteria use up the oxygen in the water, which can harm fish. Plastic floats and chokes river life. We can still respect our offerings by putting them in dustbins or special puja-material collection bins, where flowers can become compost!", "fun": "", "check": {"q": "Where should old puja flowers go instead of the river?", "a": "Into a puja-material collection bin (or the green wet-waste bin) so they can become compost."}, "hi": "नदी में कूड़ा या पूजा सामग्री डालने से पानी गंदा होता है और मछलियों को नुकसान होता है; इन्हें पूजा सामग्री के अलग डिब्बे में डालें।", "filePage": "p27", "link": "#stage"},
  {"id": "pr-puja-collection-bin", "topic": "plastic-rivers", "q": "What is the puja-material collection box in your drawing?", "alts": ["puja bin kya hai", "what is a puja bank", "puja samagri box", "explain your puja box drawing", "four compartments puja box", "puja material collection bin", "kripya puja samagri yahan daalein", "what happens to flowers in the puja bin"], "keywords": ["puja", "collection box", "flowers", "cloth", "plastic", "compost", "drawing"], "answer": "It's a special box for puja materials, so they don't go into rivers. It says 'कृपया पूजा सामग्री यहाँ पर डालें' and has 4 compartments: flowers, cloth, plastic and other items. Sorting them helps. Flowers are wet waste and can become compost, plastic can go for recycling, and cloth can be reused.", "fun": "A Kanpur start-up called Phool collects flowers offered at temples and turns them into incense sticks, so they don't end up in the Ganga.", "check": {"q": "How many compartments does your puja box have?", "a": "Four: flowers, cloth, plastic and other items."}, "hi": "यह पूजा सामग्री का डिब्बा है जिसमें फूल, वस्त्र, प्लास्टिक और अन्य सामग्री के चार खाने हैं, ताकि ये चीज़ें नदी में न जाएँ और फूलों से खाद बन सके।", "filePage": "p27", "link": "#stage", "caution": "Your file calls them 'Puja Banks', but that is not a known term. Say 'special puja-material collection bins'."},
  {"id": "pr-plastic-in-rivers", "topic": "plastic-rivers", "q": "How does plastic harm rivers and water animals?", "alts": ["plastic in river effects", "how does plastic affect fish", "nadi mein plastic se kya hota hai", "why is plastic bad for rivers", "plastic choking aquatic life", "plastic water pollution", "what happens when plastic goes into a river", "aquatic animals and plastic"], "keywords": ["plastic", "rivers", "fish", "aquatic", "floating", "choke"], "answer": "Plastic floats on rivers, piles up along the banks and gets carried by the current, sometimes all the way to the sea. Fish, turtles and birds can swallow it or get tangled in it. Slowly it breaks into microplastics that stay in the water. That's why your file says reducing plastic stops it from 'choking aquatic ecosystems'.", "fun": "Scientists have found that rivers can hold on to plastic for years, even decades. Much of it gets stuck on riverbanks and riverbeds instead of reaching the sea.", "check": {"q": "What do big plastic pieces slowly break into?", "a": "Microplastics."}, "hi": "नदी में प्लास्टिक तैरकर दूर तक बहता है, मछलियाँ और पक्षी इसे निगल लेते हैं या इसमें फँस जाते हैं, और यह टूटकर माइक्रोप्लास्टिक बन जाता है।", "filePage": "p27", "link": ""},
  {"id": "pr-cleanup-drives", "topic": "plastic-rivers", "q": "What is a river clean-up drive, and how can students help?", "alts": ["river cleaning drive", "how can children help clean rivers", "nadi safai abhiyan", "clean up drive kya hai", "what can i do to clean a river", "joining a clean-up at the ghats", "shramdaan meaning", "volunteer river cleaning"], "keywords": ["clean-up drive", "volunteers", "shramdaan", "riverbanks", "ghats", "students"], "answer": "A clean-up drive is when volunteers come together to pick up litter from riverbanks, ghats and lakes. Giving your work for free like this is called shramdaan. You can join with your school or family. Wear gloves, stay with adults and keep away from deep water. Sort what you collect into wet and dry waste, and make posters to spread awareness!", "fun": "In 1988, people of Chandigarh volunteered in the 'Sukhna Shramdan' to remove silt from Sukhna Lake and save it. India Post later issued a stamp about it!", "check": {"q": "Name one safety rule for a student at a river clean-up.", "a": "Wear gloves, stay with adults, or keep away from deep water."}, "hi": "सफ़ाई अभियान में लोग मिलकर नदी के किनारों और घाटों से कूड़ा उठाते हैं; यह एक तरह का श्रमदान है, और बच्चे दस्ताने पहनकर व बड़ों के साथ रहकर मदद कर सकते हैं।", "filePage": "p27–28", "link": ""},
  {"id": "pr-riverbank-trees", "topic": "plastic-rivers", "q": "Why should we plant trees on riverbanks?", "alts": ["benefits of trees near rivers", "why trees on river banks", "nadi ke kinare ped kyon lagayein", "how do trees help rivers", "soil erosion and river trees", "riverbank plantation", "do trees stop soil erosion", "riparian trees"], "keywords": ["trees", "riverbanks", "roots", "soil erosion", "runoff", "filter"], "answer": "Tree roots hold riverbank soil tightly, so rain and floods don't wash it into the river. This stops soil erosion. Trees and plants also slow down dirty rainwater (runoff) and filter it before it reaches the river. They also give shade, food and homes to birds and animals. Your file says to grow local trees and plants there.", "fun": "Scientists call the land along a riverbank 'riparian', from the Latin word 'ripa', meaning bank.", "check": {"q": "Which part of a tree holds the riverbank soil in place?", "a": "Its roots."}, "hi": "नदी किनारे लगे पेड़ों की जड़ें मिट्टी को पकड़े रखती हैं जिससे मिट्टी का कटाव रुकता है, और पेड़ बारिश के गंदे पानी को नदी तक पहुँचने से पहले छानने में मदद करते हैं।", "filePage": "p27–28", "link": "#viva"},
  {"id": "pr-stp-vs-etp", "topic": "plastic-rivers", "q": "What is the difference between an STP and an ETP?", "alts": ["what is STP", "what is a sewage treatment plant", "STP ETP difference", "sewage vs effluent", "sewage treatment plant kya hai", "full form of STP", "where does dirty water from homes go", "difference between sewage and effluent", "STP aur ETP mein antar"], "keywords": ["STP", "ETP", "sewage", "effluent", "homes", "factories"], "answer": "An STP (Sewage Treatment Plant) cleans sewage, the dirty water from our homes, kitchens and toilets. An ETP (Effluent Treatment Plant) cleans effluent, the chemical wastewater from factories like the sugar and leather industry in your model. Both stop dirty water from flowing straight into rivers.", "fun": "In Chandigarh, treated water from sewage treatment plants is used to water hundreds of parks and green belts, which saves clean drinking water!", "check": {"q": "Which plant would a leather factory need, an STP or an ETP?", "a": "An ETP (Effluent Treatment Plant)."}, "hi": "STP घरों और शौचालयों के गंदे पानी (सीवेज) को साफ़ करता है और ETP फ़ैक्ट्रियों के रसायन वाले पानी को; दोनों गंदे पानी को सीधे नदी में जाने से रोकते हैं।", "filePage": "p27–28", "link": "#model/factory", "caution": "Treated water from an STP or ETP is not drinking water. Never say it is safe to drink."},
  {"id": "pr-factory-laws", "topic": "plastic-rivers", "q": "What laws stop factories from polluting rivers?", "alts": ["water act 1974", "what is the water act", "pollution control board kya karta hai", "who checks factories for pollution", "what is CPCB", "can factories throw dirty water into rivers", "law for industrial waste", "water pollution law india"], "keywords": ["Water Act 1974", "pollution control board", "CPCB", "factories", "permission", "effluent"], "answer": "Under India's Water (Prevention and Control of Pollution) Act, 1974, factories need permission before releasing wastewater. The Central and State Pollution Control Boards set limits, test the water and can even order a polluting factory to close. So factories must clean their effluent in an ETP first. In Chandigarh, the Chandigarh Pollution Control Committee does this job.", "fun": "Water got its own pollution law first. The Water Act came in 1974, seven years before the Air Act of 1981!", "check": {"q": "In which year was the Water Act passed?", "a": "1974."}, "hi": "जल (प्रदूषण निवारण और नियंत्रण) अधिनियम, 1974 के अनुसार फ़ैक्ट्रियों को गंदा पानी छोड़ने से पहले अनुमति लेनी होती है, और प्रदूषण नियंत्रण बोर्ड इसकी जाँच करते हैं।", "filePage": "p27–28", "link": "#model/factory"},
  {"id": "pr-namami-gange", "topic": "plastic-rivers", "q": "What is Namami Gange?", "alts": ["namami gange programme", "namami gange kya hai", "ganga cleaning mission", "clean ganga mission", "NMCG", "namami gange kab shuru hua", "how is the government cleaning the ganga", "namami gangey"], "keywords": ["Namami Gange", "Ganga", "2014", "NMCG", "sewage", "river cleaning"], "answer": "Namami Gange is the Government of India's flagship programme to clean and protect the river Ganga. It was approved in June 2014 with a budget of ₹20,000 crore and is run by the National Mission for Clean Ganga (NMCG). It builds sewage treatment plants, cleans the river surface, plants trees and spreads awareness.", "fun": "The Ganges river dolphin, India's National Aquatic Animal, lives in the Ganga. It is almost blind and finds its way using echoes of sound!", "check": {"q": "Which river is Namami Gange meant to clean?", "a": "The Ganga."}, "hi": "नमामि गंगे भारत सरकार का गंगा नदी को साफ़ और सुरक्षित रखने का प्रमुख कार्यक्रम है, जिसे जून 2014 में मंज़ूरी मिली।", "filePage": "", "link": ""},
  {"id": "pr-trash-skimmer", "topic": "plastic-rivers", "q": "What is a trash skimmer?", "alts": ["trash skimmer kya hai", "machine that cleans the river surface", "how is floating garbage removed from rivers", "river surface cleaning", "trash skimmer boat", "boom barrier in a river", "floating waste collection machine", "trash skimer"], "keywords": ["trash skimmer", "floating waste", "river surface", "Namami Gange", "boom barriers", "conveyor belt"], "answer": "A trash skimmer is a boat-like machine that moves on a river and scoops up floating waste, like plastic bags and bottles, using a conveyor belt. Under Namami Gange, trash skimmers have been used on the Ganga in cities like Varanasi, Kanpur, Prayagraj and Patna. Boom barriers, which are floating fences, help trap the waste.", "fun": "During the Magh Mela in Prayagraj, trash skimmers removed plastic bags, bottles and even coconuts floating in the river!", "check": {"q": "What kind of waste does a trash skimmer collect?", "a": "Floating waste on the river surface."}, "hi": "ट्रैश स्किमर एक नाव जैसी मशीन है जो नदी की सतह पर तैरता कचरा, जैसे प्लास्टिक की थैलियाँ और बोतलें, इकट्ठा करती है।", "filePage": "p27–28", "link": ""},
  {"id": "en-green-energy", "topic": "energy", "q": "What is green energy?", "alts": ["green energy kya hai", "what do you mean by green energy", "examples of green energy", "what is clean energy", "grean energy meaning", "hari urja kya hoti hai", "what is green enrgy", "name some green energy sources", "define green energy"], "keywords": ["green energy", "clean energy", "renewable sources", "solar wind hydro tidal", "fossil fuels"], "answer": "Green energy is energy from natural, renewable sources that cause very little pollution. Examples are solar, wind, hydropower (flowing water) and tidal energy. Using it means burning less coal and petroleum, so there are fewer greenhouse gases and the air is cleaner. It can power homes, schools, farms and industries.", "fun": "India's oldest hydroelectric power station, Sidrapong near Darjeeling, started making electricity in 1897, more than 125 years ago!", "check": {"q": "Name two sources of green energy.", "a": "Any two: solar, wind, hydropower (water), tidal."}, "hi": "हरित ऊर्जा प्राकृतिक और नवीकरणीय स्रोतों, जैसे सूरज, हवा और बहते पानी से मिलती है, और इससे बहुत कम प्रदूषण होता है।", "filePage": "p15", "link": "#stage", "caution": "Say 'very little pollution', not 'zero pollution'."},
  {"id": "en-renewable-meaning", "topic": "energy", "q": "What is the difference between renewable and non-renewable energy?", "alts": ["why is solar energy called renewable", "what is renewable energy", "renewable meaning", "non renewable energy examples", "renewable aur non-renewable mein kya fark hai", "renuable energy", "renewable vs non renewable", "why will coal run out", "difference between renewable and nonrenewable resources"], "keywords": ["renewable", "non-renewable", "fossil fuels", "coal petrol diesel", "run out"], "answer": "Renewable energy comes from sources that will not run out in human time, like sunlight and wind, because nature keeps refilling them. Non-renewable sources, like coal, petrol and diesel (fossil fuels), took millions of years to form and will run out one day. Burning fossil fuels also adds smoke and carbon dioxide to the air.", "fun": "Much of the world's coal formed from swamp plants about 300 million years ago, long before the first dinosaurs appeared!", "check": {"q": "Is coal renewable or non-renewable?", "a": "Non-renewable, because it takes millions of years to form."}, "hi": "धूप और हवा जैसी नवीकरणीय ऊर्जा प्रकृति से बार-बार मिलती रहती है, पर कोयला और पेट्रोल जैसे जीवाश्म ईंधन बनने में लाखों साल लगते हैं और ये एक दिन ख़त्म हो जाएँगे।", "filePage": "p15", "link": ""},
  {"id": "en-green-energy-clean-india", "topic": "energy", "q": "Why is green energy part of a Clean India project?", "alts": ["how is green energy linked to clean india", "connection between swachh bharat and green energy", "why did you show solar and wind in a waste project", "green energy goals of india", "what are green city initiatives", "swachh bharat mein green energy kyun", "why energy in a cleanliness project", "clean energy and clean india"], "keywords": ["clean india", "green energy goals", "clean air", "green city", "electric mobility"], "answer": "A clean India needs clean air too, not just clean streets. Burning coal, petrol and garbage pollutes the air and adds carbon emissions. My 'Green Energy Goals' page shows India's plan: more solar and wind power, electric vehicles, green hydrogen, and energy from waste that cannot be recycled.", "fun": "Modhera in Gujarat was declared India's first 24×7 solar-powered village in October 2022. It's a real-life smart village!", "check": {"q": "Name one green energy goal from your file.", "a": "500 GW of non-fossil power by 2030, green hydrogen, or more solar and electric transport."}, "hi": "स्वच्छ भारत को साफ़ हवा भी चाहिए, इसलिए सौर, पवन, बिजली वाले वाहन और ग्रीन हाइड्रोजन ज़रूरी हैं।", "filePage": "p10", "link": "#stage", "caution": "Waste-to-energy is only for waste that cannot be recycled, in controlled plants. Never say 'burn garbage for electricity'."},
  {"id": "en-solar-energy", "topic": "energy", "q": "What is solar energy?", "alts": ["solar energy kya hai", "what is solar power", "energy from the sun", "define solar energy", "soler energy", "suraj se urja", "saur urja kya hai", "how do we use sunlight for energy"], "keywords": ["solar energy", "sun", "sunlight", "renewable", "clean"], "answer": "Solar energy is the energy we get from the Sun's light and heat. It is renewable and clean, and no smoke comes out while it makes electricity. Solar panels turn sunlight into electricity, and solar water heaters and cookers use the Sun's heat. It is especially useful in places with plenty of sunshine.", "fun": "Sunlight takes about 8 minutes 20 seconds to travel from the Sun to Earth. The light on a solar panel left the Sun about 8 minutes earlier!", "check": {"q": "Does a solar panel make smoke while working?", "a": "No, it makes no smoke while making electricity."}, "hi": "सौर ऊर्जा सूरज की रोशनी और गर्मी से मिलने वाली साफ़ और नवीकरणीय ऊर्जा है।", "filePage": "p18", "link": "#model/solar", "caution": "Say 'no smoke while working', not 'no effect on the environment at all'."},
  {"id": "en-solar-pv-how", "topic": "energy", "q": "How does a solar panel make electricity?", "alts": ["how do solar panels work", "what is a photovoltaic cell", "what is pv cell", "photovoltaic meaning", "solar panel kaise kaam karta hai", "how does sunlight become electricity", "solar cell working", "fotovoltaic", "what is a solar panel made of"], "keywords": ["photovoltaic", "PV cell", "silicon", "electrons", "light to electricity", "inverter"], "answer": "A solar panel is made of many photovoltaic (PV) cells, usually of silicon ('photo' = light, 'voltaic' = electricity). When sunlight falls on a cell, it makes tiny charged particles called electrons move, and moving electrons are an electric current! So light energy becomes electrical energy. The panel gives direct current (DC), and an inverter changes it to AC for homes.", "fun": "The 'volt' in photovoltaic honours Italian scientist Alessandro Volta, who built the first electric battery, the voltaic pile, in 1800.", "check": {"q": "What material are most solar cells made of?", "a": "Silicon."}, "hi": "सोलर पैनल के सिलिकॉन सेल पर धूप पड़ने से इलेक्ट्रॉन चलने लगते हैं और बिजली बनती है।", "filePage": "p18", "link": "#model/solar"},
  {"id": "en-solar-uses-rooftop", "topic": "energy", "q": "Where can we use solar energy in daily life?", "alts": ["uses of solar energy", "what are rooftop solar panels", "where are solar panels used", "solar energy ke upyog", "what can solar power run", "solar water heater and solar cooker", "rooftop solar kya hai", "uses of soler energy"], "keywords": ["rooftop solar", "uses", "solar water heater", "solar cooker", "street lights"], "answer": "Rooftop solar panels on houses, schools and buildings can power lights, fans and more, using roof space that is already there. Solar street lights glow at night using power stored during the day. Solar water heaters and solar cookers use the Sun's heat.", "fun": "Cochin International Airport in Kerala became the world's first fully solar-powered airport in 2015!", "check": {"q": "Name one thing that uses the Sun's HEAT, not its light, to work.", "a": "A solar water heater or a solar cooker."}, "hi": "छत पर लगे सोलर पैनल से घरों और स्कूलों में लाइट-पंखे चलते हैं, और सोलर कुकर व वॉटर हीटर सूरज की गर्मी से चलते हैं।", "filePage": "p18", "link": "#model/solar"},
  {"id": "en-solar-night-clouds", "topic": "energy", "q": "Does solar power work at night or on cloudy days?", "alts": ["what happens to solar panels at night", "solar panel in rain", "why does your bulb not glow in a dark room", "can solar work without sun", "raat ko solar kaam karta hai kya", "solar on a cloudy day", "limitations of solar energy", "how do we get solar power at night"], "keywords": ["night", "cloudy", "battery", "grid", "limitation"], "answer": "At night a solar panel gives no power, and on cloudy days it gives much less. That's why homes store extra power in batteries or take electricity from the grid. In my model, the real solar panel needs sunlight or a strong light to make the bulb glow.", "fun": "Moonlight is just sunlight bouncing off the Moon, but a full Moon is about 400,000 times dimmer than the Sun. So solar panels make almost no power on a moonlit night!", "check": {"q": "What can store solar electricity for use at night?", "a": "A battery (or we can use power from the grid)."}, "hi": "रात में सोलर पैनल बिजली नहीं बनाता और बादलों में कम बनाता है, इसलिए बैटरी या ग्रिड की ज़रूरत होती है।", "filePage": "", "link": "#model/solar"},
  {"id": "en-solar-not-zero-impact", "topic": "energy", "q": "Is solar energy completely pollution-free?", "alts": ["does solar energy have any disadvantages", "is solar zero impact", "harmful effects of solar panels", "solar ke nuksan", "is solar 100% clean", "what happens to old solar panels", "disadvantages of solar energy", "solar panel pollution"], "keywords": ["disadvantages", "not zero impact", "recycling panels", "making panels", "cost", "space"], "answer": "Not completely. Solar panels make no smoke while working, so they cause much less pollution than coal. But making panels uses energy and materials, they need space and cost money at the start, and old panels must be recycled properly. So we say solar 'reduces' pollution. It is not 'zero impact'.", "fun": "Under India's E-Waste (Management) Rules, 2022, old solar panels count as e-waste and must be stored and handled properly.", "check": {"q": "Should we say solar has 'zero impact' or that it 'reduces pollution'?", "a": "Reduces pollution. It is not zero impact."}, "hi": "सौर ऊर्जा प्रदूषण बहुत कम करती है, पर पैनल बनाने और पुराने पैनलों के निपटान का भी असर होता है, इसलिए यह 'शून्य प्रभाव' नहीं है।", "filePage": "", "link": "#model/solar", "caution": "Never say solar energy has zero effect on the environment."},
  {"id": "en-solar-demo", "topic": "energy", "q": "What does the solar part of your model show?", "alts": ["tell me about your solar panels", "is your solar panel real", "how many solar panels are in your model", "show me the solar demo", "which solar panel is real", "aapke model mein solar panel kya dikhata hai", "solar buildings in the smart city", "does your solar panel really work"], "keywords": ["solar demo", "real solar panel", "bulb", "three buildings", "handmade panels", "smart city"], "answer": "My Smart City has three buildings with solar panels. Two panels are handmade from cardboard and paper, but the third is a REAL solar panel. When sunlight falls on it, it makes electricity and the bulb glows! It shows that rooftop solar can power buildings, so less coal has to be burnt for electricity.", "fun": "The first practical silicon solar cell was shown at Bell Labs, USA, in 1954, and it powered a toy Ferris wheel!", "check": {"q": "What does the real panel need to make the bulb glow?", "a": "Sunlight (or a strong light)."}, "hi": "मेरे मॉडल में तीन इमारतों पर सोलर पैनल हैं; दो हाथ से बने हैं और एक असली है, जो धूप में बल्ब जलाता है।", "filePage": "", "link": "#model/solar", "caution": "If the room is dark, calmly say it needs sunlight or strong light to work."},
  {"id": "en-solar-mobile-toilets", "topic": "energy", "q": "What are solar-powered mobile toilets?", "alts": ["solar mobile toilets", "solar toilets kya hain", "mobile toilet with solar panel", "are solar toilets part of swachh bharat", "solar operated mobile toilets", "are solar toilets self-reliant", "how do solar toilets work", "solar powerd toilet"], "keywords": ["solar mobile toilets", "Haryana", "lights and water pumps", "local projects", "ODF"], "answer": "They are movable toilets with solar panels on the roof. The panels power the lights and water pumps inside. Some places, like Haryana, use them as local projects. They are helpful, but not completely self-reliant, because they still need water and regular emptying.", "fun": "", "check": {"q": "What do the solar panels on these toilets power?", "a": "The lights and the water pumps."}, "hi": "सोलर मोबाइल शौचालय की छत पर लगे पैनल लाइट और पानी का पंप चलाते हैं, पर उन्हें फिर भी पानी और सफ़ाई की ज़रूरत होती है।", "filePage": "after p17", "link": "", "caution": "Don't call them 'completely self-reliant' or a mission-wide scheme. They are local projects (the file overstates this)."},
  {"id": "en-school-rooftop-solar", "topic": "energy", "q": "Is solar energy part of Swachh Vidyalaya?", "alts": ["school rooftop solar", "do government schools have solar panels", "what is swachh vidyalaya", "solar in schools", "what is net metering", "what is net-metered solar", "swach vidyalaya solar", "school mein solar panel"], "keywords": ["Swachh Vidyalaya", "school rooftop solar", "net metering", "toilets and drinking water", "government schools"], "answer": "No. Swachh Vidyalaya (Clean Schools) gave schools clean toilets and drinking water, and it has no solar part. Separately, many government schools have rooftop solar panels to make their own electricity. With 'net metering', extra solar power goes to the grid and is subtracted from the school's electricity bill.", "fun": "Swachh Vidyalaya began in 2014 with a goal of separate toilets for girls and boys in every government school.", "check": {"q": "What did Swachh Vidyalaya give schools?", "a": "Clean toilets and drinking water."}, "hi": "स्वच्छ विद्यालय ने स्कूलों को शौचालय और पीने का पानी दिया; स्कूलों की छत पर सोलर पैनल एक अलग पहल है।", "filePage": "after p17", "link": "", "caution": "My file says solar 'feeds into' Swachh Vidyalaya, but that is not correct. Keep them separate."},
  {"id": "en-wind-energy", "topic": "energy", "q": "What is wind energy?", "alts": ["wind energy kya hai", "pawan urja kya hai", "what is wind power", "energy from moving air", "where are wind farms built", "wind enrgy", "what is a wind farm", "hawa se bijli"], "keywords": ["wind energy", "moving air", "wind farm", "renewable", "no fuel"], "answer": "Wind energy is energy from moving air. Wind turbines change it into electricity. It is renewable and clean, because it needs no fuel and makes very little air pollution while running. Wind farms are built in open land, along coasts, and in places where strong winds blow regularly.", "fun": "Wind is made when the Sun heats Earth unevenly, so wind energy is really solar energy in disguise!", "check": {"q": "Does a wind turbine need fuel?", "a": "No, it only needs wind."}, "hi": "पवन ऊर्जा चलती हवा से मिलती है, और पवन टरबाइन इसे बिना धुएँ के बिजली में बदलती है।", "filePage": "p17", "link": "#model/windmill"},
  {"id": "en-wind-turbine-how", "topic": "energy", "q": "How does a wind turbine make electricity?", "alts": ["how does a windmill work", "windmill kaise bijli banata hai", "wind turbine working", "how does a windmill make electricity", "parts of a wind turbine", "energy change in a windmill", "how do windmills generate power", "wind turbin"], "keywords": ["blades", "shaft", "generator", "kinetic energy", "electrical energy"], "answer": "Wind pushes the big blades and makes them spin. The blades turn a shaft, and the shaft turns a generator inside the turbine. The generator makes electricity! The energy change is: kinetic energy of wind → mechanical energy of the spinning blades → electrical energy.", "fun": "A wind turbine works like a fan in reverse. A fan uses electricity to make wind, and a turbine uses wind to make electricity!", "check": {"q": "Which part of the turbine actually makes the electricity?", "a": "The generator."}, "hi": "हवा ब्लेड घुमाती है, ब्लेड शाफ़्ट के ज़रिए जनरेटर घुमाते हैं और जनरेटर बिजली बनाता है।", "filePage": "p17", "link": "#model/windmill"},
  {"id": "en-solar-vs-wind", "topic": "energy", "q": "Which is better, solar energy or wind energy?", "alts": ["compare solar and wind energy", "solar vs wind", "difference between solar and wind energy", "limitations of wind energy", "solar ya wind kaun sa better hai", "what if the wind stops blowing", "solar or wind which is best", "wind vs solar power"], "keywords": ["compare", "solar vs wind", "limitation", "batteries", "depends on place"], "answer": "Both are renewable and make no smoke while running. Solar needs sunlight, so it gives no power at night. Wind needs strong wind, which does not blow steadily everywhere. So the best plan is to use both together, with batteries. Sunny places suit solar, and windy coasts and open land suit wind.", "fun": "", "check": {"q": "Why is it smart to use solar and wind together?", "a": "When one is low (night, or no wind), the other may still work. Batteries help too."}, "hi": "सौर और पवन दोनों नवीकरणीय हैं; सूरज रात में नहीं चमकता और हवा हर समय नहीं चलती, इसलिए दोनों को साथ इस्तेमाल करना अच्छा है।", "filePage": "", "link": "#model/windmill"},
  {"id": "en-wind-india", "topic": "energy", "q": "How much wind power does India have, and what is the 2030 goal?", "alts": ["india's rank in wind energy", "how many gw of wind power in india", "wind energy milestones 2030", "bharat wind power mein kaunse number par hai", "what are india's wind targets", "is india 4th in wind power", "wind capasity of india", "india wind power target"], "keywords": ["4th in the world", "58 GW", "100 GW", "2030", "wind capacity"], "answer": "India is 4th in the world in installed wind power. It has about 58 GW (gigawatts) of wind power now and aims for about 100 GW by 2030. That means adding about 42 GW more in just a few years!", "fun": "Only three countries have more wind power installed than India: China, the USA and Germany.", "check": {"q": "What is India's wind power goal for 2030?", "a": "About 100 GW."}, "hi": "पवन ऊर्जा में भारत दुनिया में चौथे स्थान पर है; अभी लगभग 58 GW है और 2030 तक लगभग 100 GW का लक्ष्य है।", "filePage": "after p16", "link": "#model/windmill", "caution": "My file only says 'clear milestones'. Give the real numbers: about 58 GW now, about 100 GW by 2030."},
  {"id": "en-wind-mnre-niwe", "topic": "energy", "q": "Who looks after wind energy in India? Is there a National Wind Energy Mission?", "alts": ["what is the national wind energy mission", "who handles wind energy in india", "what is NIWE", "what is MNRE", "wind mission kya hai", "which ministry looks after renewable energy", "national institute of wind energy", "wind energy mision"], "keywords": ["MNRE", "NIWE", "Chennai", "National Wind Energy Mission", "never launched"], "answer": "Wind energy is looked after by the Ministry of New and Renewable Energy (MNRE), with the National Institute of Wind Energy (NIWE) in Chennai. A 'National Wind Energy Mission' was proposed but never launched. Wind power helps India's goals of cleaner air and net-zero emissions by 2070.", "fun": "NIWE in Chennai began in 1998 as the Centre for Wind Energy Technology (C-WET), and was later renamed.", "check": {"q": "Which ministry looks after wind and solar energy?", "a": "MNRE, the Ministry of New and Renewable Energy."}, "hi": "भारत में पवन ऊर्जा का काम नवीन और नवीकरणीय ऊर्जा मंत्रालय (MNRE) और चेन्नई का राष्ट्रीय पवन ऊर्जा संस्थान देखते हैं; राष्ट्रीय पवन ऊर्जा मिशन कभी शुरू नहीं हुआ।", "filePage": "after p16", "link": "", "caution": "My file says 'National Wind Energy Mission', but it was only proposed and never launched."},
  {"id": "en-windmill-model", "topic": "energy", "q": "What does the windmill in your model show?", "alts": ["does your windmill make electricity", "how many windmills are in your model", "tell me about your windmill", "does the windmill really turn", "aapka windmill kya dikhata hai", "windmill in the centre of the model", "is your windmill working", "windmil model"], "keywords": ["windmill", "one windmill", "model", "centre", "wind energy"], "answer": "My model has ONE windmill in the centre, and it shows wind energy. In a real wind turbine, wind turns the blades and a generator inside makes electricity, with no smoke. Only say the model windmill itself turns or makes electricity if it really does. Check with Rajnish Ma'am.", "fun": "Old windmills were used to grind grain into flour. That's why they are called 'mills'!", "check": {"q": "How many windmills are in your model?", "a": "One."}, "hi": "मेरे मॉडल के बीच में एक पवन चक्की है, जो पवन ऊर्जा को दिखाती है।", "filePage": "", "link": "#model/windmill", "caution": "There is exactly ONE windmill. Don't claim it makes electricity unless it really does."},
  {"id": "en-india-clean-energy-progress", "topic": "energy", "q": "What is India's 500 GW clean-energy goal, and how close are we?", "alts": ["500 gw target", "india renewable energy target 2030", "how is india doing on its clean energy goals", "india's rank in renewable energy", "did india cross 300 gw", "non fossil fuel capacity target", "500 gigawatt kya hai", "is india 3rd in renewable energy", "renewabel target"], "keywords": ["500 GW", "2030", "300 GW", "July 2026", "non-fossil", "3rd in the world"], "answer": "India's goal is 500 GW of non-fossil (clean) power capacity by 2030. In July 2026, India crossed 300 GW, so it is more than halfway there! India is also 3rd in the world in total renewable energy capacity. Non-fossil means power not made from coal, oil or gas, like solar, wind, hydro and nuclear.", "fun": "1 GW = 1 billion watts. That's enough to light 10 crore LED bulbs of 10 watts each, all at the same time!", "check": {"q": "How many GW of clean power did India cross in July 2026?", "a": "300 GW."}, "hi": "भारत का लक्ष्य 2030 तक 500 GW स्वच्छ बिजली क्षमता का है, और जुलाई 2026 में भारत ने 300 GW पार कर लिया।", "filePage": "p10", "link": "#stage"},
  {"id": "en-net-zero-2070", "topic": "energy", "q": "What is net zero, and what is India's 2070 target?", "alts": ["net zero 2070", "what does net zero mean", "net zero emissions", "net zero kya hai", "when will india reach net zero", "net-zero carbon", "what did india promise at cop26", "nett zero"], "keywords": ["net zero", "2070", "COP26", "Glasgow", "emissions balanced"], "answer": "Net zero means the greenhouse gases a country releases are balanced by the gases it removes, for example through forests. It does not mean zero pollution. India has promised to reach net-zero emissions by 2070, and announced this at COP26 in Glasgow in 2021.", "fun": "At COP26, India called its five climate promises 'Panchamrit' (the 'five nectars'), and net zero by 2070 was one of them.", "check": {"q": "In which year does India aim to reach net zero?", "a": "2070."}, "hi": "नेट ज़ीरो का मतलब है जितनी ग्रीनहाउस गैसें छोड़ें, उतनी ही हटाएँ; भारत 2070 तक नेट ज़ीरो बनना चाहता है।", "filePage": "after p16", "link": "#model/india", "caution": "Net zero does not mean 'no emissions at all'."},
  {"id": "en-green-hydrogen-mission", "topic": "energy", "q": "What is the National Green Hydrogen Mission?", "alts": ["green hydrogen mission", "what is NGHM", "national green hydrogen mission kya hai", "when was the green hydrogen mission launched", "how much money for the green hydrogen mission", "5 million tonnes hydrogen", "hydrogen mission india", "green hydrogan mission"], "keywords": ["National Green Hydrogen Mission", "January 2023", "₹19,744 crore", "5 million tonnes", "2030"], "answer": "It is India's plan to make and use green hydrogen and become a global hub for it. It was approved on 4 January 2023 with ₹19,744 crore. The goal is to make at least 5 million tonnes of green hydrogen a year by 2030. This helps India use less fossil fuel and cut carbon emissions.", "fun": "Hydrogen is the lightest element and the most common one in the whole universe. Even the Sun is mostly hydrogen!", "check": {"q": "How much green hydrogen does India want to make each year by 2030?", "a": "At least 5 million tonnes."}, "hi": "राष्ट्रीय ग्रीन हाइड्रोजन मिशन जनवरी 2023 में ₹19,744 करोड़ के साथ मंज़ूर हुआ; लक्ष्य 2030 तक हर साल 50 लाख टन ग्रीन हाइड्रोजन बनाना है।", "filePage": "p16", "link": "#model/train", "caution": "Give the 2030 goal as '5 million tonnes a year', not just 'a hub by 2030'."},
  {"id": "en-green-vs-grey-hydrogen", "topic": "energy", "q": "What is the difference between green hydrogen and grey hydrogen?", "alts": ["what is green hydrogen", "what is grey hydrogen", "is a hydrogen train always green", "green hydrogen kya hai", "how is green hydrogen made", "grey vs green hydrogen", "why is it called green hydrogen", "gray hydrogen"], "keywords": ["green hydrogen", "grey hydrogen", "natural gas", "renewable electricity", "CO₂"], "answer": "Green hydrogen is made by splitting water with electricity from renewable sources like solar or wind, so very little CO₂ is released. Grey hydrogen is made from natural gas, which releases CO₂. So a hydrogen train is only truly 'green' if its hydrogen is made in a clean way.", "fun": "Hydrogen gas has no colour at all! 'Green', 'grey' and 'blue' only describe how it was made. Blue hydrogen comes from natural gas, with its CO₂ captured.", "check": {"q": "Which hydrogen is made using solar or wind electricity?", "a": "Green hydrogen."}, "hi": "ग्रीन हाइड्रोजन सौर या पवन बिजली से पानी को तोड़कर बनती है, जबकि ग्रे हाइड्रोजन प्राकृतिक गैस से बनती है और CO₂ छोड़ती है।", "filePage": "", "link": "#model/train"},
  {"id": "en-electrolysis", "topic": "energy", "q": "What is electrolysis?", "alts": ["electrolysis kya hai", "how is hydrogen made from water", "splitting water", "how do we get hydrogen", "what is an electrolyser", "electrolisis", "water se hydrogen kaise banti hai", "electrolysis of water"], "keywords": ["electrolysis", "electrolyser", "split water", "hydrogen and oxygen", "electricity"], "answer": "Electrolysis means using electricity to split water (H₂O) into hydrogen gas and oxygen gas. The machine that does this is called an electrolyser. If the electricity comes from solar or wind, the hydrogen is called green hydrogen. The hydrogen for India's first hydrogen train is made this way at Jind.", "fun": "Electrolysis gives twice as much hydrogen as oxygen by volume, because water (H₂O) has two hydrogen atoms for every one oxygen atom.", "check": {"q": "Which two gases do we get when we split water?", "a": "Hydrogen and oxygen."}, "hi": "इलेक्ट्रोलिसिस (विद्युत अपघटन) में बिजली से पानी को हाइड्रोजन और ऑक्सीजन गैस में तोड़ा जाता है।", "filePage": "", "link": "#model/train"},
  {"id": "en-hydrogen-train-launch", "topic": "energy", "q": "When and where was India's first hydrogen train flagged off?", "alts": ["india's first hydrogen train", "hydrogen train kab chali", "who flagged off the hydrogen train", "jind hydrogen train", "when did the hydrogen train start", "hydrogen train in haryana", "first hydrogen train india date", "hydrogen trane"], "keywords": ["hydrogen train", "17 July 2026", "Jind", "Prime Minister", "flagged off", "Haryana"], "answer": "Prime Minister Narendra Modi flagged off India's first hydrogen fuel-cell passenger train on 17 July 2026, at Jind railway station in Haryana. It runs on the Jind–Sonipat route of the Northern Railway. It was designed and built in India, which makes it a big milestone for clean energy on Indian Railways!", "fun": "The train was built at the Integral Coach Factory (ICF) in Chennai, to Indian Railways' RDSO design specifications.", "check": {"q": "From which station was the train flagged off?", "a": "Jind, in Haryana."}, "hi": "भारत की पहली हाइड्रोजन ट्रेन को प्रधानमंत्री नरेंद्र मोदी ने 17 जुलाई 2026 को हरियाणा के जींद स्टेशन से हरी झंडी दिखाई।", "filePage": "p16", "link": "#model/train"},
  {"id": "en-hydrogen-train-route", "topic": "energy", "q": "What is the route of the hydrogen train?", "alts": ["jind to sonipat distance", "how long is the hydrogen train route", "how many stations does the hydrogen train stop at", "how much time does the hydrogen train take", "jind gohana sonipat", "hydrogen train route kya hai", "89 km route", "how fast is the hydrogen train"], "keywords": ["89 km", "Jind–Gohana–Sonipat", "12 intermediate stations", "2 hours", "Northern Railway"], "answer": "The train runs on the 89 km Jind–Gohana–Sonipat stretch of the Northern Railway in Haryana. There are 12 intermediate stations on the way, and the journey takes about 2 hours.", "fun": "Its operating speed is about 75 km/h, but it is designed to go up to 110 km/h!", "check": {"q": "How long is the Jind–Sonipat route?", "a": "About 89 km."}, "hi": "हाइड्रोजन ट्रेन जींद–गोहाना–सोनीपत के 89 किलोमीटर रास्ते पर चलती है; बीच में 12 स्टेशन हैं और लगभग 2 घंटे लगते हैं।", "filePage": "p16", "link": "#model/train"},
  {"id": "en-hydrogen-train-size", "topic": "energy", "q": "How many coaches and passengers does the hydrogen train have?", "alts": ["how many people can the hydrogen train carry", "hydrogen train coaches", "hydrogen train capacity", "kitne log baith sakte hain hydrogen train mein", "how big is the hydrogen train", "what is a hydrogen driving power car", "passengers in the hydrogen train", "hydrogen train dibbe"], "keywords": ["10 coaches", "2,600 passengers", "Hydrogen Driving Power Cars", "made in India"], "answer": "The train has 10 coaches. Two are Hydrogen Driving Power Cars that power the train, and eight are trailer coaches for passengers. It can carry about 2,600 passengers, and it was designed and built in India.", "fun": "", "check": {"q": "About how many passengers can the hydrogen train carry?", "a": "About 2,600."}, "hi": "हाइड्रोजन ट्रेन में 10 डिब्बे हैं और इसमें लगभग 2,600 यात्री सफ़र कर सकते हैं।", "filePage": "", "link": "#model/train"},
  {"id": "en-fuel-cell", "topic": "energy", "q": "How does a hydrogen fuel cell work, and what comes out of the train?", "alts": ["what comes out of a hydrogen train", "does the hydrogen train make smoke", "is hydrogen burnt like diesel", "fuel cell kaise kaam karta hai", "how does the hydrogen train run", "what is a fuel cell", "does the hydrogen train only give water", "fual cell", "water vapour from the train"], "keywords": ["fuel cell", "hydrogen + oxygen", "electricity", "water vapour", "not burning"], "answer": "In a fuel cell, hydrogen from the train's tanks reacts with oxygen from the air. This is not burning. It is a chemical reaction that makes electricity directly, plus water and heat. The electricity runs the train's motors. So the main by-product is water vapour instead of diesel smoke.", "fun": "The Apollo spacecraft that flew to the Moon also used fuel cells, and the astronauts drank the water they made!", "check": {"q": "Is hydrogen burnt like diesel in the train?", "a": "No. It reacts with oxygen in a fuel cell to make electricity."}, "hi": "फ्यूल सेल में टैंक की हाइड्रोजन और हवा की ऑक्सीजन मिलकर बिजली बनाती हैं, और डीज़ल के धुएँ की जगह मुख्य रूप से जलवाष्प निकलती है।", "filePage": "", "link": "#model/train", "caution": "Say 'the main by-product is water vapour', not 'it causes no pollution at all'."},
  {"id": "en-hydrogen-train-germany", "topic": "energy", "q": "Is India the first country to run a hydrogen train?", "alts": ["which countries have hydrogen trains", "first hydrogen train in the world", "hydrogen train in germany", "elite club of hydrogen trains", "kya bharat pehla desh hai hydrogen train wala", "world's first hydrogen train", "other countries with hydrogen trains", "germeny hydrogen train"], "keywords": ["Germany", "first in the world", "small group of countries", "elite club", "2018"], "answer": "No. India joined a small group of countries, like Germany, that run hydrogen passenger trains. India's train is special because it was designed and built here. My file says 'elite global club', but that is not an official group.", "fun": "Germany's hydrogen train, the Coradia iLint, started carrying passengers in Lower Saxony in September 2018.", "check": {"q": "Name one other country that runs hydrogen passenger trains.", "a": "Germany."}, "hi": "भारत पहला देश नहीं है; जर्मनी जैसे कुछ देशों में पहले से हाइड्रोजन यात्री ट्रेनें चलती हैं।", "filePage": "p16", "link": "#model/train", "caution": "Don't say 'elite club' as if it were an official group."},
  {"id": "en-jind-hydrogen-plant", "topic": "energy", "q": "Where does the hydrogen train get its hydrogen?", "alts": ["hydrogen refuelling station at jind", "where is hydrogen stored for the train", "jind hydrogen plant", "how is hydrogen for the train made", "train ke liye hydrogen kahan se aati hai", "hydrogen storage at jind", "is the jind train's hydrogen green", "hydrogen filling station"], "keywords": ["Jind", "refuelling facility", "3,000 kg", "PESO", "electrolysis"], "answer": "Jind has India's largest railway hydrogen storage and refuelling facility. It can store about 3,000 kg of hydrogen and is approved by PESO, the safety organisation. The hydrogen there is made by electrolysis, where electricity splits water. It is truly 'green' when that electricity comes from renewable sources.", "fun": "The Jind electrolyser is about 1 MW and can make about 430 kg of hydrogen a day, according to its supplier.", "check": {"q": "How is the hydrogen at Jind made?", "a": "By electrolysis of water."}, "hi": "जींद में भारत की सबसे बड़ी रेलवे हाइड्रोजन भंडारण और रीफ़्यूलिंग सुविधा है, जहाँ इलेक्ट्रोलिसिस से पानी तोड़कर हाइड्रोजन बनाई जाती है।", "filePage": "", "link": "#model/train"},
  {"id": "en-ev-what", "topic": "energy", "q": "What is an EV and how does it work?", "alts": ["what is an electric vehicle", "ev kya hai", "how does an electric car work", "ev full form", "why are evs good for the air", "electric car kaise chalti hai", "what happens when you press the ev button", "elecric vehicle", "what is ev charging"], "keywords": ["EV", "electric vehicle", "battery", "electric motor", "no tailpipe smoke", "charging"], "answer": "EV means Electric Vehicle. It runs on a battery and an electric motor, not on petrol or diesel. The charger fills the battery with electricity, and the battery powers the motor that turns the wheels. Nothing is burnt, so there is no tailpipe smoke. In my model, pressing the EV-station button makes a green light glow to show charging.", "fun": "Electric cars are older than you might think. New York City had a fleet of electric taxis way back in 1897!", "check": {"q": "What does EV stand for?", "a": "Electric Vehicle."}, "hi": "EV यानी इलेक्ट्रिक वाहन, जो बैटरी और मोटर से चलता है और चलते समय धुआँ नहीं छोड़ता।", "filePage": "", "link": "#model/ev", "caution": "Say 'no tailpipe smoke', not 'no pollution at all'."},
  {"id": "en-ev-coal-electricity", "topic": "energy", "q": "If the electricity comes from coal, is an EV still clean?", "alts": ["are evs really pollution free", "do electric cars cause pollution", "is an ev zero pollution", "where does ev electricity come from", "is an ev 100 percent green", "ev se pradushan hota hai kya", "ev charging from coal", "are electric vehicles zero emission"], "keywords": ["coal power plant", "depends on electricity", "solar charging", "battery recycling", "not zero impact"], "answer": "Partly. An EV has no exhaust, so the air on city roads stays cleaner. But if its electricity comes from a coal power plant, some pollution just moves from the road to the power plant. EVs are much cleaner when charged with solar or wind power, like the solar panels in my Smart City. Making and recycling batteries matters too.", "fun": "As India adds more solar and wind power to its grid, the same EV becomes cleaner over time, without any change to the car!", "check": {"q": "What kind of electricity makes an EV cleanest?", "a": "Renewable electricity, like solar or wind."}, "hi": "EV सड़क पर धुआँ नहीं छोड़ता, पर उसका पूरा फ़ायदा इस पर निर्भर है कि बिजली कैसे बनी; सौर और पवन बिजली सबसे अच्छी है।", "filePage": "", "link": "#model/ev", "caution": "Never say EVs or electric buses are 'zero impact'."},
  {"id": "en-electric-bus", "topic": "energy", "q": "Why are electric buses good for a city?", "alts": ["benefits of electric buses", "why is there an electric bus in your model", "why is a bus better than many cars", "electric bus kyun", "public transport and pollution", "what is an e-bus", "how many electric buses are in your model", "electrik bus"], "keywords": ["electric bus", "public transport", "fewer cars", "noise pollution", "bus stand"], "answer": "One bus carries many people, so fewer cars are needed on the road. An electric bus also has no tailpipe smoke, and its motor is quiet, so there is less air AND noise pollution. My model has two electric buses at a bus stand. Their full benefit depends on how the electricity is made.", "fun": "In August 2023, India approved the PM-eBus Sewa scheme to add 10,000 electric buses to city bus services.", "check": {"q": "Why is one bus better than many cars?", "a": "It carries many people, so there are fewer vehicles, less traffic and less smoke."}, "hi": "एक इलेक्ट्रिक बस कई लोगों को ले जाती है, धुआँ नहीं छोड़ती और शोर भी कम करती है।", "filePage": "", "link": "#model/bus", "caution": "Say 'less smoke', not 'zero pollution'."},
  {"id": "en-regenerative-braking", "topic": "energy", "q": "What is regenerative braking?", "alts": ["what is regen braking", "how do electric buses save energy when braking", "regenerative braking kya hai", "can a motor work as a generator", "does braking energy go back to the battery", "regenrative braking", "what happens when an ev slows down", "how does an ev recharge itself while driving"], "keywords": ["regenerative braking", "motor as generator", "battery", "saving energy", "slowing down"], "answer": "When an electric vehicle slows down, its motor works like a generator. It turns some of the moving energy back into electricity and stores it in the battery. Energy that would be wasted as heat in the brakes is partly saved! Many electric cars and buses use it.", "fun": "Some Indian Railways electric locomotives also use regenerative braking, sending electricity back into the overhead wires.", "check": {"q": "During regenerative braking, the motor works like a ___?", "a": "Generator."}, "hi": "रीजनरेटिव ब्रेकिंग में गाड़ी धीमी होते समय मोटर जनरेटर की तरह काम करके कुछ बिजली वापस बैटरी में भरती है।", "filePage": "", "link": "#model/bus"},
  {"id": "en-carbon-emission", "topic": "energy", "q": "What is carbon emission?", "alts": ["carbon emission kya hai", "what does carbon emission mean", "why is carbon emission written on your model", "where does carbon dioxide come from", "co2 emission", "carbon emmision", "what is written below the india map", "how do we reduce carbon emissions"], "keywords": ["carbon emission", "carbon dioxide", "CO₂", "burning fuels", "India map"], "answer": "Carbon emission means releasing carbon dioxide (CO₂) into the air. It mostly comes from burning coal, petrol, diesel, wood and garbage, because the carbon in them joins with oxygen to make CO₂. Too much CO₂ warms our Earth. In my model, 'Carbon Emission' is written below the India map, and solar, wind, EVs, the hydrogen train and biogas show ways to reduce it.", "fun": "Burning 1 litre of petrol makes about 2.3 kg of CO₂. That's heavier than the petrol itself, because the carbon grabs oxygen from the air!", "check": {"q": "Name one fuel that causes carbon emission when burnt.", "a": "Coal, petrol, diesel or wood (or garbage)."}, "hi": "कार्बन उत्सर्जन का मतलब है हवा में कार्बन डाइऑक्साइड छोड़ना, जो कोयला, पेट्रोल, डीज़ल और कचरा जलाने से होता है।", "filePage": "", "link": "#model/india", "caution": "Don't explain the ladder below 'Carbon Emission'. Its meaning is unknown, so ask Rajnish Ma'am."},
  {"id": "en-greenhouse-effect", "topic": "energy", "q": "What is the greenhouse effect?", "alts": ["greenhouse effect kya hai", "what are greenhouse gases", "how does co2 trap heat", "green house effect", "examples of greenhouse gases", "why is it called the greenhouse effect", "names of greenhouse gases", "is methane a greenhouse gas"], "keywords": ["greenhouse effect", "greenhouse gases", "trap heat", "methane", "blanket"], "answer": "Some gases in the air, like carbon dioxide, methane and nitrous oxide, let sunlight in but trap some of the heat, like a blanket around Earth. This is the greenhouse effect. A little of it keeps Earth warm enough to live on. But extra greenhouse gases from burning fuels and rotting garbage trap too much heat.", "fun": "Without any greenhouse effect, Earth's average temperature would be about −18°C instead of about 15°C. That's much too cold for us!", "check": {"q": "Name a greenhouse gas that comes from rotting garbage.", "a": "Methane."}, "hi": "ग्रीनहाउस गैसें कंबल की तरह धरती की गर्मी रोकती हैं; ये गैसें ज़्यादा होने पर धरती ज़्यादा गर्म होने लगती है।", "filePage": "", "link": "#model/india"},
  {"id": "en-global-warming", "topic": "energy", "q": "What is global warming?", "alts": ["global warming kya hai", "why is the earth getting hotter", "causes of global warming", "climate change meaning", "globle warming", "how is garbage linked to global warming", "effects of global warming", "is global warming only caused by humans"], "keywords": ["global warming", "average temperature", "human activities", "fossil fuels", "methane from landfills"], "answer": "Global warming is the long-term rise in Earth's average temperature. It is mainly caused by extra greenhouse gases from human activities, like burning fossil fuels. Garbage adds to it too, because wet waste rotting in landfills makes methane. Green energy, trees, composting and biogas all help slow it down.", "fun": "IPCC scientists found that Earth was about 1.1°C warmer in 2011–2020 than in 1850–1900.", "check": {"q": "Today, is global warming 'only' or 'mainly' caused by humans?", "a": "Mainly by human activities."}, "hi": "ग्लोबल वार्मिंग का मतलब है धरती के औसत तापमान का धीरे-धीरे बढ़ना, जो मुख्य रूप से इंसानी गतिविधियों से हो रहा है।", "filePage": "", "link": "#model/india", "caution": "Say 'mainly' caused by human activities, not 'only'."},
  {"id": "en-afforestation-reforestation", "topic": "energy", "q": "What is afforestation, and how is it different from reforestation?", "alts": ["afforestation kya hai", "reforestation meaning", "difference between afforestation and reforestation", "vanikaran kya hai", "what is afforstation", "planting new forests", "what is a tree plantation drive", "why should we plant trees"], "keywords": ["afforestation", "reforestation", "new forest", "planting trees", "soil erosion"], "answer": "Afforestation means planting trees to make a NEW forest on land that did not have a forest before. Reforestation means planting trees again where a forest was cut down. Both help, because trees take in CO₂, stop soil erosion, help rainfall and give homes to wildlife.", "fun": "Jadav Payeng, the 'Forest Man of India', started planting a forest on a bare sandbar of the Brahmaputra in Assam in 1979. That's afforestation!", "check": {"q": "What do we call planting trees where a forest was cut down?", "a": "Reforestation."}, "hi": "वनीकरण में ऐसी जगह नया जंगल लगाया जाता है जहाँ पहले जंगल नहीं था, और पुनर्वनीकरण में कटे हुए जंगल की जगह फिर से पेड़ लगाए जाते हैं।", "filePage": "p19", "link": ""},
  {"id": "en-trees-co2", "topic": "energy", "q": "How do trees and plants help reduce carbon dioxide?", "alts": ["how do trees reduce pollution", "trees and co2", "why did you put flower pots in your model", "photosynthesis and carbon dioxide", "ped carbon dioxide kaise kam karte hain", "how do plants clean the air", "what do the flower pots show", "do trees absorb co2"], "keywords": ["photosynthesis", "trees", "carbon dioxide", "oxygen", "flower pots"], "answer": "During photosynthesis, plants use sunlight, water and carbon dioxide to make their food, and they give out oxygen. Trees also store carbon in their wood, leaves and roots, so less CO₂ stays in the air. That's why green spaces matter, and the two flower pots in my model's central park show this idea.", "fun": "About half of a tree's dry weight is carbon that it took out of the air as CO₂!", "check": {"q": "Which gas do plants give out during photosynthesis?", "a": "Oxygen."}, "hi": "पेड़-पौधे प्रकाश संश्लेषण में कार्बन डाइऑक्साइड लेकर ऑक्सीजन छोड़ते हैं और कार्बन को अपनी लकड़ी में जमा करते हैं।", "filePage": "p19", "link": "#model/pots", "caution": "The model has only TWO flower pots. Don't describe trees or gardens that aren't there."},
  {"id": "bw-what-is-biogas", "topic": "biogas-water", "q": "What is biogas and what is it made from?", "alts": ["what is biogas", "biogas kya hai", "what is biogas made from", "which waste makes biogas", "can kitchen waste make biogas", "biogass meaning", "what do we put in a biogas plant", "biogas kis se banti hai"], "keywords": ["biogas", "cow dung", "kitchen waste", "gobar", "crop leftovers"], "answer": "Biogas is a fuel gas made from wet, organic waste: cow dung, kitchen scraps like peels and leftover food, and crop leftovers. Tiny microbes break this waste down inside a closed tank with no oxygen, and the gas they give off is biogas. So waste that would just rot becomes useful energy!", "fun": "A cow's stomach works like a mini biogas plant! Microbes there break down grass without oxygen and make methane, which cows mostly burp out.", "check": {"q": "Name two kinds of waste that can go into a biogas plant.", "a": "Cow dung and kitchen waste (crop leftovers too)."}, "hi": "बायोगैस गोबर, रसोई के कचरे और फसल के बचे हिस्सों से बनती है, जब सूक्ष्मजीव बिना ऑक्सीजन के उन्हें तोड़ते हैं।", "filePage": "p21", "link": "#model/biogas", "caution": "Your file (p12) says 'agricultural runoff' goes in; runoff is water flowing off fields, so say 'crop leftovers' instead."},
  {"id": "bw-anaerobic-digestion", "topic": "biogas-water", "q": "What is anaerobic digestion?", "alts": ["what is anaerobic digestion", "anerobic digestion meaning", "what does anaerobic mean", "biomethanation kya hai", "how is biogas made", "biogas kaise banti hai", "what happens inside the digester", "aerobic vs anaerobic", "what is biomethanation"], "keywords": ["anaerobic digestion", "without oxygen", "microbes", "digester", "biomethanation"], "answer": "Anaerobic digestion means tiny microbes (bacteria) break down wet organic waste WITHOUT oxygen, inside a closed tank called a digester. They give out biogas, which collects at the top, and leave behind a liquid called slurry. Its other name is biomethanation. ('Aerobic' is the opposite: with oxygen, like composting in an open pit.)", "fun": "'Anaerobic' comes from Greek: 'an' = without, 'aer' = air, 'bios' = life. So it means 'living without air'! Louis Pasteur made up the word, in French, in 1863.", "check": {"q": "Is a biogas digester open to the air or closed?", "a": "Closed: no oxygen allowed!"}, "hi": "अवायवीय पाचन में सूक्ष्मजीव बंद टैंक में बिना ऑक्सीजन के गीले कचरे को तोड़कर बायोगैस और घोल (स्लरी) बनाते हैं।", "filePage": "p12", "link": "#model/biogas"},
  {"id": "bw-biogas-gases", "topic": "biogas-water", "q": "What gases are in biogas?", "alts": ["what is biogas mainly made of", "biogas composition", "how much methane is in biogas", "which gas is in biogas", "biogas mein kaun si gas hoti hai", "methane percentage in biogas", "is biogas pure methane", "metane in biogas"], "keywords": ["methane", "carbon dioxide", "50-70%", "composition", "CH4"], "answer": "Biogas is mostly methane (CH₄), about 50 to 70%. Most of the rest is carbon dioxide (CO₂), with tiny amounts of other gases. The methane is the part that burns and gives heat; the carbon dioxide does not burn.", "fun": "Methane has no smell! When biogas smells like rotten eggs, that comes from a tiny amount of another gas called hydrogen sulphide.", "check": {"q": "Which gas in biogas actually burns: methane or carbon dioxide?", "a": "Methane."}, "hi": "बायोगैस में लगभग 50–70% मीथेन होती है और बाकी ज़्यादातर कार्बन डाइऑक्साइड; जलने वाली गैस मीथेन है।", "filePage": "p21", "link": "#model/biogas"},
  {"id": "bw-biogas-uses", "topic": "biogas-water", "q": "What is biogas used for?", "alts": ["uses of biogas", "biogas ka upyog", "what can we do with biogas", "can biogas make electricity", "is biogas used for cooking", "why do we make biogas", "biogas uses in village", "biogass uses"], "keywords": ["uses", "cooking", "heating", "electricity", "fuel"], "answer": "Biogas is mainly used as cooking fuel in stoves. It is also used for heating, and for making electricity with a gas engine and generator. When it is cleaned and compressed (CBG), it can even run vehicles. Turn waste into energy, not pollution!", "fun": "Biogas burns with a blue flame and almost no smoke or soot. That's much cleaner than cooking on firewood or dung cakes.", "check": {"q": "Name two uses of biogas.", "a": "Cooking and making electricity (heating too)."}, "hi": "बायोगैस से खाना पकाया जाता है, गर्मी मिलती है और बिजली भी बनाई जा सकती है।", "filePage": "p21", "link": "#model/biogas"},
  {"id": "bw-slurry", "topic": "biogas-water", "q": "What is slurry in a biogas plant?", "alts": ["what is slurry", "biogas slurry use", "what is left after making biogas", "biogas plant ka bacha hua ghol", "is slurry manure", "slury meaning", "what happens to the waste after biogas", "biogas residue"], "keywords": ["slurry", "manure", "fertilizer", "leftover", "digestate"], "answer": "Slurry is the wet, muddy liquid left in the tank after the microbes have made biogas. It still has plant nutrients, so farmers use it as manure (fertilizer) for their fields. A biogas plant gives two gifts: gas for the stove and manure for the soil!", "fun": "", "check": {"q": "What are the two useful things a biogas plant gives?", "a": "Biogas (fuel) and slurry (manure)."}, "hi": "बायोगैस बनने के बाद बचा घोल (स्लरी) खेतों के लिए अच्छी खाद है।", "filePage": "", "link": "#model/biogas"},
  {"id": "bw-avni-biogas-plant", "topic": "biogas-water", "q": "How does the biogas plant in your model work?", "alts": ["explain your biogas plant", "biogas plant in your model", "what is the pipe in the village", "why is there a stove in your model", "tumhara biogas plant kaise kaam karta hai", "what does the pipe to the stove show", "smart village biogas", "explain the biogas model"], "keywords": ["model", "biogas plant", "pipe", "stove", "smart village"], "answer": "In my Smart Village, cow dung and kitchen waste go into the biogas plant. Inside, without oxygen, microbes break them down and make biogas, which is mainly methane. The gas travels through the pipe to the stove for cooking, and the leftover slurry can be used as manure. Turn waste into energy, not pollution!", "fun": "", "check": {"q": "In your model, where does the gas go after it is made?", "a": "Through the pipe to the stove, for cooking."}, "hi": "मेरे मॉडल में बायोगैस प्लांट में बनी गैस पाइप से चूल्हे तक जाती है, जिससे खाना बनता है।", "filePage": "", "link": "#model/biogas", "caution": "Don't say the village toilet is connected to the biogas plant unless Rajnish Ma'am confirms it."},
  {"id": "bw-biogas-benefits", "topic": "biogas-water", "q": "Why is biogas good for a village?", "alts": ["advantages of biogas", "benefits of biogas", "biogas ke fayde", "what if there is no biogas in a village", "why should villages use biogas", "how does biogas help women", "biogas vs firewood", "why biogas is better than wood"], "keywords": ["benefits", "firewood", "smoke", "trees", "village", "advantages"], "answer": "With biogas, fewer trees are cut for firewood and there is much less smoke in the kitchen. That smoke harms the lungs of the women and children who are near the stove. Biogas also uses waste that would otherwise rot and smell, and it gives manure too. Without it, villages burn more firewood and fossil fuels.", "fun": "WHO says about 2.1 billion people (around a quarter of the world) still cook on open fires or smoky stoves using wood, dung, crop waste, kerosene or coal.", "check": {"q": "Who is most harmed by smoky kitchens?", "a": "Women and children."}, "hi": "बायोगैस से पेड़ कम कटते हैं, रसोई में धुआँ कम होता है और कचरा भी काम आ जाता है।", "filePage": "", "link": "#model/biogas"},
  {"id": "bw-biogas-not-zero", "topic": "biogas-water", "q": "Is biogas completely pollution-free?", "alts": ["is biogas clean", "does biogas cause pollution", "biogas pollution free hai kya", "is biogas zero pollution", "does burning biogas give carbon dioxide", "is biogas eco friendly", "how does biogas help climate", "biogas and greenhouse gas"], "keywords": ["pollution-free", "carbon dioxide", "methane", "greenhouse gas", "cleaner"], "answer": "Not completely! Burning biogas still gives out carbon dioxide. But it is much cleaner than firewood or cow-dung cakes, with almost no smoke. It also helps the climate: methane escaping from rotting waste is a strong greenhouse gas, and a biogas plant captures that methane and uses it.", "fun": "Over 20 years, methane traps about 80 times more heat than the same amount of carbon dioxide. So catching it really matters!", "check": {"q": "Which is correct: 'biogas is completely pollution-free' or 'biogas is cleaner than firewood'?", "a": "Biogas is cleaner than firewood."}, "hi": "बायोगैस पूरी तरह प्रदूषण-मुक्त नहीं है, पर लकड़ी और उपलों से कहीं ज़्यादा साफ़ है और मीथेन को हवा में जाने से रोकती है।", "filePage": "", "link": "#model/biogas", "caution": "Never call biogas 'zero pollution'; say 'cleaner than firewood or dung cakes'."},
  {"id": "bw-gobardhan", "topic": "biogas-water", "q": "What is the GOBARdhan scheme?", "alts": ["what is gobardhan", "gobar dhan yojana", "gobardhan scheme kya hai", "gobar-dhan full form", "when did gobardhan start", "government scheme for biogas", "gobardan scheme", "galvanizing organic bio-agro resources"], "keywords": ["GOBARdhan", "scheme", "2018", "SBM-G", "cattle dung", "waste to wealth"], "answer": "GOBARdhan is a government scheme that helps turn cattle dung, crop waste and kitchen waste into biogas, compressed biogas and organic manure. It started in 2018 under Swachh Bharat Mission (Grameen), the village part of the Clean India Mission. The big idea: waste is wealth ('dhan')!", "fun": "GOBARdhan stands for 'Galvanizing Organic Bio-Agro Resources Dhan', and 'gobar' is the Hindi word for cow dung!", "check": {"q": "Under which mission did GOBARdhan start in 2018?", "a": "Swachh Bharat Mission (Grameen)."}, "hi": "गोबरधन योजना 2018 में स्वच्छ भारत मिशन (ग्रामीण) के तहत शुरू हुई; यह गोबर और जैविक कचरे से बायोगैस और खाद बनाने में मदद करती है।", "filePage": "p13", "link": "#model/biogas"},
  {"id": "bw-gobardhan-500-plants", "topic": "biogas-water", "q": "How many waste-to-wealth plants were announced under GOBARdhan?", "alts": ["500 gobardhan plants", "gobardhan budget 2023", "how many biogas plants under gobardhan", "200 cbg plants 300 community plants", "gobardhan 500 plant kab", "budget 2023 waste to wealth", "how many new plants gobardhan", "500 waste to wealth plants"], "keywords": ["500 plants", "Budget 2023", "200 CBG", "300 community", "waste to wealth"], "answer": "In the 2023 Budget, the government announced 500 new 'Waste to Wealth' plants under GOBARdhan. Of these, 200 are compressed biogas (CBG) plants and 300 are community or cluster plants. So most of the 500 are community plants.", "fun": "The 2023 Budget said these 500 plants would bring a total investment of about ₹10,000 crore.", "check": {"q": "Of the 500 plants, how many are CBG plants?", "a": "200 (the other 300 are community plants)."}, "hi": "2023 के बजट में गोबरधन के तहत 500 नए 'कचरे से धन' संयंत्र घोषित हुए: 200 सीबीजी और 300 सामुदायिक।", "filePage": "p13", "link": "#model/biogas", "caution": "Your file (p13) says the 500 plants focus 'primarily' on compressed biogas; only 200 are CBG. Also add the year 2023."},
  {"id": "bw-gobardhan-2026", "topic": "biogas-water", "q": "What is the new GOBARdhan scheme of 2026?", "alts": ["gobardhan 2026", "23731 crore scheme", "new gobardhan scheme august 2026", "cabinet approved gobardhan", "national scheme for compressed biogas", "gobardhan ka naya plan", "who runs gobardhan now", "latest biogas scheme india"], "keywords": ["2026", "₹23,731 crore", "national scheme", "compressed biogas", "Ministry of Petroleum"], "answer": "In August 2026, the Union Cabinet approved a new national GOBARdhan scheme of ₹23,731 crore to grow compressed biogas (CBG) across India. It runs for ten years, from 2026-27 to 2035-36, under the Ministry of Petroleum and Natural Gas. It aims to raise India's CBG production nearly ten times.", "fun": "City gas companies must mix CBG into the gas they supply: 3% in 2026-27, rising to 5% from 2028-29.", "check": {"q": "How much money is the 2026 GOBARdhan scheme worth?", "a": "₹23,731 crore."}, "hi": "अगस्त 2026 में ₹23,731 करोड़ की नई राष्ट्रीय गोबरधन योजना मंज़ूर हुई, जो देश में संपीड़ित बायोगैस (सीबीजी) का उत्पादन बढ़ाएगी।", "filePage": "", "link": "#model/biogas", "caution": "Your file (p13) mentions the MNRE Waste to Energy Programme, which ended in 2025-26. Say the new ₹23,731 crore GOBARdhan scheme (August 2026) instead."},
  {"id": "bw-cbg", "topic": "biogas-water", "q": "What is CBG (compressed biogas)?", "alts": ["what is cbg", "compressed bio gas meaning", "bio-cng kya hai", "can biogas run cars", "cbg vs cng", "what is bio cng", "compresed biogas", "how is biogas used in vehicles"], "keywords": ["CBG", "compressed biogas", "Bio-CNG", "purified", "vehicles", "methane"], "answer": "CBG means Compressed Bio-Gas. Biogas is cleaned to remove most of its carbon dioxide and other gases until it is at least 90% methane. Then it is squeezed into strong cylinders. It works like CNG, so it can run vehicles or be used in factories.", "fun": "Indore's GOBAR-Dhan plant (opened in 2022) turns the city's wet waste into Bio-CNG, and part of that gas fuels Indore's city buses!", "check": {"q": "Which gas is mostly removed from biogas to make CBG?", "a": "Carbon dioxide."}, "hi": "सीबीजी यानी संपीड़ित बायोगैस: बायोगैस से ज़्यादातर कार्बन डाइऑक्साइड हटाकर (कम से कम 90% मीथेन) उसे सिलेंडरों में भरा जाता है, और यह सीएनजी की तरह गाड़ियाँ चला सकती है।", "filePage": "p12", "link": "#model/biogas"},
  {"id": "bw-what-is-wte", "topic": "biogas-water", "q": "What is waste-to-energy (WTE)?", "alts": ["what is wte", "waste to energy meaning", "kachre se bijli", "how can garbage make electricity", "what is waste-to-energy in clean india", "energy from waste", "waste too energy", "what is energy recovery"], "keywords": ["waste-to-energy", "WTE", "non-recyclable", "electricity", "thermal", "biological"], "answer": "Waste-to-energy means getting electricity, heat or fuel from waste instead of dumping it in landfills. Biological WTE uses microbes to turn wet waste into biogas. Thermal WTE uses heat in closed, controlled plants (like incineration), only for leftover waste that cannot be recycled. But reducing, segregating and recycling always come first!", "fun": "Waste-to-energy is the 'Recover' R, the very last of the 7Rs in your project file!", "check": {"q": "Should recyclable plastic go to a waste-to-energy plant?", "a": "No, recycle it. Thermal WTE is only for non-recyclable waste."}, "hi": "कचरे से ऊर्जा का मतलब है कचरे से बिजली, गर्मी या ईंधन बनाना, जैसे गीले कचरे से बायोगैस; पर पहले कचरा कम करना, अलग करना और रीसायकल करना ज़रूरी है।", "filePage": "p11", "link": "#model/wte", "caution": "Your file (p11) calls WTE a 'foundational pillar' of the mission; say it is 'one important way to use leftover waste'."},
  {"id": "bw-incineration", "topic": "biogas-water", "q": "How does incineration make electricity from waste?", "alts": ["what is incineration", "how does a waste to energy plant work", "incinerator kya hota hai", "at what temperature is waste burnt", "how is electricity made from garbage", "insineration", "heat steam turbine generator", "kachre ko jala kar bijli kaise banti hai"], "keywords": ["incineration", "850°C", "steam", "turbine", "generator", "furnace"], "answer": "In incineration, non-recyclable waste is burnt in a closed furnace at very high temperatures, usually above 850°C. The heat boils water into steam, the steam spins a turbine, and the turbine turns a generator that makes electricity. The smoke must be cleaned before it leaves the chimney.", "fun": "Incineration shrinks the volume of waste by about 90%, leaving mostly ash behind.", "check": {"q": "Put these in order: generator, steam, heat, turbine.", "a": "Heat → steam → turbine → generator."}, "hi": "भस्मीकरण में न रीसायकल होने वाला कचरा बंद भट्ठी में आमतौर पर 850°C से ज़्यादा तापमान पर जलाया जाता है; गर्मी से भाप बनती है, भाप टरबाइन घुमाती है और जनरेटर बिजली बनाता है।", "filePage": "p12", "link": "#model/wte", "caution": "Your file (p12) says 850°C–1400°C; say 'very high temperatures, usually above 850°C'. 1400°C is not normal for city-waste incinerators."},
  {"id": "bw-pollution-control", "topic": "biogas-water", "q": "What happens to the smoke in a waste-to-energy plant?", "alts": ["pollution control in wte plant", "does a waste to energy plant pollute", "how is smoke cleaned", "what are scrubbers", "wte plant ka dhuan", "is waste to energy safe", "what is a scrubber", "do incinerators cause pollution"], "keywords": ["pollution control", "smoke", "filters", "scrubbers", "chimney", "ash"], "answer": "A proper waste-to-energy plant cleans its smoke with filters and scrubbers before it leaves the chimney. The waste must also burn hot enough, for long enough, to destroy harmful chemicals, and the leftover ash must be handled safely. Without this pollution control, burning waste would poison the air.", "fun": "In Copenhagen, Denmark, a waste-to-energy plant called CopenHill has a ski slope on its roof!", "check": {"q": "Name one thing that cleans the smoke in a WTE plant.", "a": "Filters or scrubbers."}, "hi": "कचरे से ऊर्जा बनाने वाले संयंत्र में धुएँ को फ़िल्टर और स्क्रबर से साफ़ करके ही चिमनी से छोड़ा जाता है।", "filePage": "", "link": "#model/wte"},
  {"id": "bw-wte-capacity", "topic": "biogas-water", "q": "How much waste-to-energy capacity does India have?", "alts": ["india wte capacity", "how many MW waste to energy india", "230 MW to 878 MW", "waste to energy growth in india", "bharat mein kachre se kitni bijli", "wte capacity 2026", "how much has waste to energy grown", "877 MW"], "keywords": ["capacity", "230 MW", "878 MW", "2014", "2026", "MNRE"], "answer": "India's waste-to-energy capacity grew from about 230 MW in 2014 to about 878 MW in 2026. That's almost four times bigger! It is still small compared with solar or wind, because WTE is only for leftover waste.", "fun": "One megawatt (MW) is a million watts: enough to light about 1 lakh 10-watt LED bulbs at the same time!", "check": {"q": "About how many times did India's WTE capacity grow from 2014 to 2026?", "a": "Almost four times (230 MW → 878 MW)."}, "hi": "भारत में कचरे से ऊर्जा की क्षमता 2014 में लगभग 230 मेगावाट थी, जो 2026 में लगभग 878 मेगावाट हो गई, यानी लगभग चार गुना।", "filePage": "p12", "link": "#model/wte", "caution": "Your file (p12) says '877 MWeq' with no year; say 'about 878 MW in 2026' (MNRE, 31 Aug 2026)."},
  {"id": "bw-rdf", "topic": "biogas-water", "q": "What is RDF (Refuse-Derived Fuel)?", "alts": ["what is rdf", "refuse derived fuel meaning", "rdf kya hai", "how is waste used in cement factories", "can garbage be used as fuel", "refuse derived fule", "rdf from plastic waste", "dry waste fuel"], "keywords": ["RDF", "refuse-derived fuel", "cement", "dry waste", "non-recyclable"], "answer": "RDF means Refuse-Derived Fuel. Dry waste that cannot be recycled, like dirty mixed plastic and packaging, is sorted, dried and shredded so it can be used as fuel, for example in cement factories. There it replaces part of the coal, inside proper plants with pollution control.", "fun": "Cement kilns are super hot: the material inside goes above 1,400°C. That's why they can use RDF as part of their fuel.", "check": {"q": "Should clean, recyclable plastic be made into RDF?", "a": "No, recycle it. RDF is for non-recyclable dry waste."}, "hi": "आरडीएफ यानी कचरे से बना ईंधन: न रीसायकल होने वाले सूखे कचरे को सुखाकर और काटकर सीमेंट कारखानों में ईंधन की तरह इस्तेमाल किया जाता है।", "filePage": "", "link": "#model/wte"},
  {"id": "bw-pyrolysis", "topic": "biogas-water", "q": "What is pyrolysis?", "alts": ["pyrolysis meaning", "pyrolysis kya hai", "plastic to oil", "can plastic be turned into fuel", "heating plastic without oxygen", "pyrolisis", "how is plastic made into oil", "plastic se tel"], "keywords": ["pyrolysis", "without oxygen", "plastic", "oil", "gas"], "answer": "Pyrolysis means heating waste, like plastic, to a high temperature WITHOUT oxygen. With no oxygen it cannot catch fire. Instead, the long plastic molecules break into smaller ones, giving oil, gas and a little char. The oil can be cleaned and used as fuel, but only in proper, safe plants.", "fun": "'Pyrolysis' comes from Greek: 'pyro' means fire and 'lysis' means loosening. So it means breaking things apart with heat!", "check": {"q": "What is missing in pyrolysis that is present in normal burning?", "a": "Oxygen."}, "hi": "पायरोलिसिस में प्लास्टिक को बिना ऑक्सीजन के बहुत गर्म किया जाता है, जिससे वह जलता नहीं बल्कि तेल और गैस में बदल जाता है।", "filePage": "", "link": "#model/wte"},
  {"id": "bw-wet-waste-burns-badly", "topic": "biogas-water", "q": "Why must waste be segregated before it goes to a waste-to-energy plant?", "alts": ["why wet waste does not burn well", "segregation for wte", "why mixed waste is bad for waste to energy", "geela kachra kyon nahi jalta", "why not send wet waste to an incinerator", "unsegregated waste wte problem", "moisture in waste", "why segregate before burning"], "keywords": ["segregation", "wet waste", "moisture", "burns badly", "efficiency"], "answer": "Wet waste like peels and leftover food is full of water, so it burns badly. A lot of heat is wasted just drying it, and less electricity is made. Wet waste is better used for compost or biogas, and recyclable dry waste should be recycled. Only leftover, non-recyclable dry waste should go for energy.", "fun": "India's first waste-to-energy plant, at Timarpur in Delhi (1987), failed. Experts say a big reason was that the city's waste was too wet and poor to burn well.", "check": {"q": "Where should wet waste go instead of a WTE plant?", "a": "To compost or biogas."}, "hi": "गीले कचरे में बहुत पानी होता है, इसलिए वह ठीक से नहीं जलता; उसे खाद या बायोगैस के लिए भेजना चाहिए।", "filePage": "p13", "link": "#model/wte"},
  {"id": "bw-recycle-vs-energy", "topic": "biogas-water", "q": "Is it better to recycle plastic or make energy from it?", "alts": ["recycling vs waste to energy", "should we burn plastic or recycle", "which is better recycle or recover", "recycle karna behtar ya jalana", "why not burn all plastic for energy", "recover vs recycle", "is waste to energy better than recycling", "last R of 7Rs"], "keywords": ["recycle", "recover", "7Rs", "better", "non-recyclable"], "answer": "Recycling is better for plastic that can be recycled, because the material gets used again and more resources are saved. Making energy from waste is 'Recover', the LAST of the 7Rs, and it is only for waste that cannot be recycled. Best of all are Refuse and Reduce: the best waste is the waste we never create!", "fun": "", "check": {"q": "Which of the 7Rs is waste-to-energy?", "a": "Recover, the last one."}, "hi": "जो प्लास्टिक रीसायकल हो सकता है उसे रीसायकल करना बेहतर है; कचरे से ऊर्जा (रिकवर) आख़िरी उपाय है।", "filePage": "p23", "link": "#model/wte"},
  {"id": "bw-avni-wte-machine", "topic": "biogas-water", "q": "How does your plastic-to-energy machine work?", "alts": ["explain your plastic to energy machine", "why does the bulb glow", "what is the red machine in your model", "plastic machine kaise kaam karti hai", "how does your machine make electricity", "waste to energy model explain", "plastic-to-energy demo", "plastik to energy machine"], "keywords": ["plastic-to-energy", "machine", "bulb", "model", "demo", "two units"], "answer": "My machine shows the IDEA of waste-to-energy. In real plants, non-recyclable waste is treated at very high temperature in a closed furnace. The heat makes steam, the steam spins a turbine, the turbine turns a generator, and my glowing bulb shows the electricity. Real plants need pollution control, and we must never burn plastic in the open.", "fun": "", "check": {"q": "What does the glowing bulb show?", "a": "The electricity that can be made from non-recyclable waste."}, "hi": "मेरी मशीन कचरे से ऊर्जा का विचार दिखाती है; जलता बल्ब बताता है कि न रीसायकल होने वाले कचरे से बिजली बन सकती है।", "filePage": "", "link": "#model/wte", "caution": "The machine and the bulb unit are two separate parts; confirm with Rajnish Ma'am what each one represents. Never say 'we simply burn plastic and get electricity'."},
  {"id": "bw-never-open-burning", "topic": "biogas-water", "q": "Can we just burn plastic in the open to get rid of it or to make energy?", "alts": ["can we burn plastic", "why not burn plastic", "plastic jalana sahi hai kya", "is burning garbage bad", "can we burn plastic for electricity", "open burning of waste", "why is burning plastic harmful", "kachra jalana"], "keywords": ["open burning", "plastic", "toxic gases", "dioxins", "never burn"], "answer": "No, never! Burning plastic or garbage in the open releases poisonous gases like dioxins and furans, plus thick black smoke that harms our lungs and the air. Energy can be recovered only from non-recyclable waste, in special closed plants with pollution control. Open burning is never the answer.", "fun": "In 2016, India's National Green Tribunal banned open burning of waste, with fines of ₹5,000 for simple burning and ₹25,000 for bulk burning.", "check": {"q": "Name one poisonous gas released by burning plastic in the open.", "a": "Dioxins (or furans)."}, "hi": "प्लास्टिक या कचरा खुले में कभी नहीं जलाना चाहिए, क्योंकि इससे डाइऑक्सिन जैसी ज़हरीली गैसें और काला धुआँ निकलता है।", "filePage": "", "link": "#model/wte", "caution": "Never say 'just burn plastic for electricity'."},
  {"id": "bw-dioxins-furans", "topic": "biogas-water", "q": "What are dioxins and furans?", "alts": ["what are dioxins", "dioxin kya hai", "furans meaning", "why are dioxins dangerous", "poisonous gases from burning plastic", "dioxines", "what chemicals come from burning plastic", "are dioxins harmful"], "keywords": ["dioxins", "furans", "toxic", "burning", "health"], "answer": "Dioxins and furans are very poisonous chemicals that form when waste, especially plastic, burns without proper control, like in open burning. They last a long time and build up in food, especially in the fat of meat, milk and fish. They can harm the body's defence (immune) system and growth, and can cause cancer.", "fun": "Dioxins stay in the body for a very long time. WHO estimates it takes about 7 to 11 years for just half of them to leave!", "check": {"q": "What is the simplest way to stop dioxins forming from our garbage?", "a": "Never burn waste in the open."}, "hi": "डाइऑक्सिन और फ़्यूरान बहुत ज़हरीले रसायन हैं, जो खुले में प्लास्टिक जलाने से बनते हैं और लंबे समय तक शरीर व पर्यावरण में रहते हैं।", "filePage": "", "link": "#model/wte"},
  {"id": "bw-filter-layers", "topic": "biogas-water", "q": "What are the layers of your water filter, from top to bottom?", "alts": ["filter layers order", "explain your water filter", "multi-layer gravity filter", "filter mein kaun kaun si layer hai", "what is at the top of your filter", "order of layers in filter", "gravity filter layers", "filtter layers"], "keywords": ["layers", "top to bottom", "stones", "gravel", "sand", "charcoal", "cotton"], "answer": "My multi-layer gravity filter goes from coarse to fine. From top to bottom: stones and gravel → sand → charcoal → cotton. Dirty water is poured in at the top, gravity pulls it down through each layer, and clearer water drips out at the bottom.", "fun": "Big water-treatment plants also filter water through thick beds of sand resting on gravel. Your filter is a mini version!", "check": {"q": "Which layer is at the very bottom?", "a": "Cotton."}, "hi": "मेरे फ़िल्टर में ऊपर से नीचे परतें हैं: पत्थर और बजरी → रेत → कोयला (चारकोल) → रुई।", "filePage": "p24–26", "link": "#model/filter", "caution": "Confirm with Rajnish Ma'am whether your MODEL filter really has the sand layer. If it doesn't, skip 'sand' when you point at it."},
  {"id": "bw-coarse-to-fine", "topic": "biogas-water", "q": "Why does the filter go from coarse stones at the top to fine cotton at the bottom?", "alts": ["why coarse to fine", "why are stones on top", "why not put cotton on top", "patthar upar kyon hain", "why does the order of layers matter", "coarse to fine meaning", "what if we change the order of layers", "why big stones first"], "keywords": ["coarse", "fine", "order", "clog", "big particles first"], "answer": "Water should flow from the coarsest layer to the finest. The stones catch the big dirt first, so the fine layers below don't get blocked (clogged) quickly. Then each layer catches smaller and smaller particles, like a team where every player has a special job!", "fun": "", "check": {"q": "What would happen if cotton were at the top?", "a": "It would clog quickly with big dirt, and water would flow very slowly."}, "hi": "पानी मोटी परत से बारीक परत की ओर बहना चाहिए, ताकि बड़ी गंदगी पहले रुक जाए और नीचे की बारीक परतें जल्दी बंद न हों।", "filePage": "p24–26", "link": "#model/filter"},
  {"id": "bw-stones-sand", "topic": "biogas-water", "q": "What do the stones, gravel and sand do in the filter?", "alts": ["role of stones in filter", "why gravel in filter", "what does sand do in a filter", "patthar aur ret ka kaam", "physical filtration meaning", "what is filtration", "why sand layer", "stone layer use"], "keywords": ["stones", "gravel", "sand", "physical filtration", "particles"], "answer": "Stones and gravel are the first line of defence: they trap big things like leaves, twigs, bits of plastic and heavy mud. Sand has smaller gaps, so it catches smaller dirt particles. This is physical filtration, which means separating solid bits from a liquid by passing it through something with tiny gaps.", "fun": "In big 'slow sand filters', a slimy layer of helpful microbes grows on top of the sand. Its German name, 'Schmutzdecke', means 'dirt cover'!", "check": {"q": "Which catches bigger particles: stones or sand?", "a": "Stones."}, "hi": "पत्थर और बजरी पत्तियाँ, टहनियाँ और कीचड़ जैसी बड़ी गंदगी रोकते हैं, और रेत छोटे कणों को रोकती है।", "filePage": "p24–26", "link": "#model/filter"},
  {"id": "bw-charcoal-adsorption", "topic": "biogas-water", "q": "What does charcoal do in the filter?", "alts": ["role of charcoal", "what is adsorption", "koyle ka kaam filter mein", "why charcoal in water filter", "activated carbon use", "adsorption vs absorption", "charcol filter", "does charcoal remove chemicals"], "keywords": ["charcoal", "activated carbon", "adsorption", "smell", "colour", "chemicals"], "answer": "Charcoal is full of tiny holes, which give it a huge surface. Many chemicals, chlorine, colour and bad smells stick to this surface. That's called adsorption (sticking ON a surface), not absorption (soaking IN like a sponge). But charcoal does not kill germs, and home-made charcoal removes very little heavy metal.", "fun": "Just 1 gram of activated charcoal can have a surface area of 500 square metres or more. That's about two tennis courts!", "check": {"q": "Does charcoal kill germs?", "a": "No. It holds some chemicals, colour and smell, but it doesn't kill germs."}, "hi": "कोयले (चारकोल) के छोटे-छोटे छेदों की सतह पर रसायन, रंग और बदबू चिपक जाते हैं; इसे अधिशोषण कहते हैं, पर यह कीटाणु नहीं मारता।", "filePage": "p25", "link": "#model/filter", "caution": "Your file (p25) says charcoal traps heavy metals; say 'many chemicals, chlorine, colour and smells, but not germs and not all metals'."},
  {"id": "bw-cotton-bottom", "topic": "biogas-water", "q": "Why is cotton at the bottom of the filter?", "alts": ["role of cotton in filter", "why cotton layer", "rui ka kaam", "why is cotton last", "what does the cloth do in the filter", "cotton at bottom reason", "filter cloth use", "kapas kyon lagaya"], "keywords": ["cotton", "bottom", "fine filtration", "charcoal dust", "barrier"], "answer": "Cotton is the last and finest barrier. It traps the tiniest particles that slipped through the upper layers, and it stops black charcoal dust from coming out with the water. It also holds all the layers above it in place.", "fun": "In Bangladeshi villages, filtering water through old sari cloth folded at least four times cut cholera cases by about half. Still, it didn't make water fully safe!", "check": {"q": "What black dust does the cotton stop?", "a": "Charcoal dust."}, "hi": "रुई सबसे आख़िरी और सबसे बारीक परत है, जो छोटे कणों और कोयले की धूल को पानी के साथ बाहर आने से रोकती है।", "filePage": "p24–26", "link": "#model/filter"},
  {"id": "bw-filtered-water-safe", "topic": "biogas-water", "q": "Can we drink the water from your filter?", "alts": ["is filtered water safe to drink", "can i drink this water", "kya yeh paani pee sakte hain", "is clear water safe", "clean looking water safe hai", "is your filter water drinkable", "does the filter kill germs", "clear water vs safe water"], "keywords": ["drink", "safe", "germs", "clear water", "dissolved chemicals"], "answer": "No! The water looks clearer, but clear water is not always safe water. It may still have germs (bacteria and viruses) too tiny to see, and chemicals dissolved in it that a filter cannot catch. My filter shows only the first, simple cleaning step, so the water must be treated and tested before anyone drinks it.", "fun": "Bacteria are so tiny that about 40 of them lined up end to end would just cross the width of one human hair!", "check": {"q": "Name one thing that may still be in clear-looking water.", "a": "Germs (or dissolved chemicals)."}, "hi": "फ़िल्टर का पानी साफ़ दिखता है, पर पीने के लिए सुरक्षित नहीं है, क्योंकि उसमें कीटाणु और घुले रसायन हो सकते हैं।", "filePage": "p24", "link": "#model/filter", "caution": "NEVER say filtered water is safe to drink."},
  {"id": "bw-make-water-safe", "topic": "biogas-water", "q": "How can we make water safe to drink?", "alts": ["how to purify water", "paani saaf kaise karein", "how to kill germs in water", "does boiling make water safe", "what does RO do", "what is chlorination", "UV water purifier", "filtration vs purification"], "keywords": ["boiling", "chlorine", "UV", "RO", "testing", "purification"], "answer": "Germs can be killed by boiling, adding chlorine or using UV light, but these don't remove dissolved chemicals. RO (reverse osmosis) purifiers can remove many dissolved chemicals. The water should also be tested to be sure. Filtration only removes floating bits; purification makes water safe.", "fun": "WHO says simply bringing water to a rolling boil is enough to kill harmful bacteria, viruses and protozoa.", "check": {"q": "Does boiling remove dissolved chemicals?", "a": "No. It kills germs, but RO is needed for many dissolved chemicals."}, "hi": "उबालने, क्लोरीन या यूवी से कीटाणु मरते हैं, आरओ कई घुले रसायन हटाता है, और पानी की जाँच भी ज़रूरी है।", "filePage": "", "link": "#model/filter"},
  {"id": "bw-factory-wastewater", "topic": "biogas-water", "q": "Why is there a Sugar & Leather Industry in your model?", "alts": ["what is the factory in your model", "sugar and leather industry dirty water", "why is factory water harmful", "factory ka ganda paani", "what is effluent", "industrial wastewater", "what happens if factory water goes into rivers", "sugar leather factory model"], "keywords": ["factory", "sugar", "leather", "effluent", "wastewater", "rivers"], "answer": "Factories like sugar mills and leather tanneries release dirty wastewater, called effluent, full of chemicals and waste. If it goes straight into rivers, it can kill fish and pollute drinking water. In my model, the factory's dirty water is pumped to the water-treatment setup, because factories must treat their water before reusing or releasing it.", "fun": "Kanpur, on the Ganga, is one of India's biggest leather-tanning centres. That's why cleaning tannery water there matters so much for the river.", "check": {"q": "What is the word for liquid waste flowing out of a factory?", "a": "Effluent."}, "hi": "चीनी मिलें और चमड़ा कारखाने गंदा पानी (एफ़्लुएंट) छोड़ते हैं, जिसे नदी में जाने से पहले साफ़ करना ज़रूरी है।", "filePage": "p27–28", "link": "#model/factory"},
  {"id": "bw-etp-steps", "topic": "biogas-water", "q": "What is an ETP and how does it clean factory water?", "alts": ["what is etp", "effluent treatment plant steps", "etp kya hai", "how is factory water treated", "steps of effluent treatment", "efluent treatment plant", "how do industries clean wastewater", "what is cetp"], "keywords": ["ETP", "effluent treatment plant", "physical", "chemical", "biological", "steps"], "answer": "An ETP (Effluent Treatment Plant) cleans factory wastewater in steps. Physical: screens remove big solids, mud settles and oil is skimmed off; chemical: chemicals balance the water and remove harmful things like chromium; biological: helpful bacteria 'eat' the dissolved dirt. Finally the water is filtered and disinfected, then reused or released safely.", "fun": "Small factories can share one Common Effluent Treatment Plant (CETP). Some factories even aim for 'Zero Liquid Discharge', reusing all their water!", "check": {"q": "In which ETP step do bacteria help?", "a": "The biological step."}, "hi": "ईटीपी (एफ़्लुएंट ट्रीटमेंट प्लांट) कारखाने के गंदे पानी को भौतिक, रासायनिक और जैविक चरणों में साफ़ करता है।", "filePage": "", "link": "#model/factory"},
  {"id": "bw-chromium-tannery", "topic": "biogas-water", "q": "Why is leather-industry wastewater especially harmful?", "alts": ["chromium in tannery water", "why is tannery water dangerous", "chamde ke karkhane ka paani", "what is chromium", "leather factory pollution", "kromium", "tanning chemicals", "chrome tanning"], "keywords": ["chromium", "tannery", "leather", "toxic", "tanning"], "answer": "To turn animal skins into leather (tanning), many tanneries use chromium salts. So their wastewater can contain chromium, which is toxic to people and to life in rivers, along with lots of salt and other chemicals. It needs special chemical treatment in the ETP, and the chromium can even be recovered.", "fun": "Most of the world's leather is 'chrome-tanned'. That's why chromium shows up so often in tannery wastewater.", "check": {"q": "Which metal is the big worry in tannery wastewater?", "a": "Chromium."}, "hi": "चमड़ा बनाने में क्रोमियम लवण इस्तेमाल होते हैं, इसलिए टेनरी के गंदे पानी में ज़हरीला क्रोमियम हो सकता है।", "filePage": "", "link": "#model/factory"},
  {"id": "bw-sugar-bod", "topic": "biogas-water", "q": "What is the problem with sugar-mill wastewater?", "alts": ["sugar mill wastewater", "what is BOD", "why does sugar water kill fish", "cheeni mill ka ganda paani", "biochemical oxygen demand", "organic load meaning", "sugar factory pollution", "how sugar water harms rivers"], "keywords": ["sugar mill", "BOD", "organic matter", "oxygen", "fish"], "answer": "Sugar-mill wastewater is full of organic matter like sugar. In a river, bacteria break it down and use up the oxygen dissolved in the water, so fish can't breathe and may die. Scientists measure this as BOD (Biochemical Oxygen Demand): high BOD means the water will use up lots of oxygen.", "fun": "Sugar mills burn bagasse (the dry, crushed cane left after the juice is squeezed out) to make steam and electricity for the mill!", "check": {"q": "Is high BOD good or bad for a river?", "a": "Bad: it means less oxygen for fish."}, "hi": "चीनी मिल के पानी में बहुत जैविक पदार्थ होता है; बैक्टीरिया उसे तोड़ते समय नदी की ऑक्सीजन खत्म कर देते हैं और मछलियाँ मर सकती हैं।", "filePage": "", "link": "#model/factory"},
  {"id": "bw-stp-vs-etp", "topic": "biogas-water", "q": "What is the difference between an STP and an ETP?", "alts": ["stp vs etp", "sewage treatment plant meaning", "what is stp", "stp aur etp mein antar", "difference between sewage and effluent", "which plant does a leather factory need", "sewage vs effluent", "what is a sewage treatment plant"], "keywords": ["STP", "ETP", "sewage", "effluent", "homes", "factories"], "answer": "An STP (Sewage Treatment Plant) cleans sewage, the dirty water from our homes, kitchens and toilets. An ETP (Effluent Treatment Plant) cleans effluent, the chemical wastewater from factories like sugar mills and tanneries. Both stop dirty water from flowing straight into rivers.", "fun": "Chandigarh reuses treated water from its sewage plants to water hundreds of parks and green belts, saving drinking water!", "check": {"q": "Which one would a leather factory need: STP or ETP?", "a": "ETP."}, "hi": "एसटीपी घरों का गंदा पानी (सीवेज) साफ़ करता है और ईटीपी कारखानों का रासायनिक गंदा पानी।", "filePage": "p27–28", "link": "#model/factory"},
  {"id": "bw-filter-vs-etp", "topic": "biogas-water", "q": "Is your water filter a real ETP?", "alts": ["is your filter an etp", "is your model a water treatment plant", "can your filter clean factory water", "kya tumhara filter etp hai", "filter vs etp", "is the filter enough for factory water", "difference between your filter and etp", "can charcoal clean factory water"], "keywords": ["filter", "ETP", "demonstration", "first step", "factory water"], "answer": "No. My filter shows only the first, simple step of cleaning water: physical filtration, with a little help from charcoal. A real ETP is a big plant with physical, chemical and biological steps, plus testing. A simple filter on its own is not enough to make factory chemical water safe for rivers.", "fun": "", "check": {"q": "What does a real ETP have that your filter doesn't?", "a": "Chemical and biological (bacteria) treatment steps, plus testing."}, "hi": "मेरा फ़िल्टर पानी साफ़ करने का केवल पहला सरल चरण दिखाता है; असली ईटीपी में भौतिक, रासायनिक और जैविक चरण होते हैं।", "filePage": "p24", "link": "#model/filter", "caution": "Don't mix up your simple filter demo with a full ETP."},
  {"id": "md-layout", "topic": "model-talk", "q": "What is in your model? Can you explain its layout?", "alts": ["explain your model", "what does your model show", "model layout", "what are the parts of your model", "tell me about your model", "give a tour of your model", "model ke bare mein batao", "what is on the green base", "how is your model arranged", "what is your projet model about"], "keywords": ["layout", "model", "whole model", "parts of model", "green wooden base", "zones", "arranged"], "answer": "Your whole model sits on ONE green wooden base. Left: the Smart City — solar buildings, two toilets, an EV station and an electric bus stand. Centre: the India map with 'Carbon Emission', a ladder, one windmill, two flower pots and the Plastic Man photo. Right: the Smart Village — hut, digger field, toilet and biogas plant. Front: the hydrogen train, five dustbins, the factory, the water filter and the plastic-to-energy machine.", "fun": "", "check": {"q": "Which side of your model is the Smart Village on?", "a": "The right side."}, "hi": "आपका पूरा मॉडल एक हरे लकड़ी के बेस पर है — बाईं ओर स्मार्ट सिटी, बीच में भारत का नक्शा, दाईं ओर स्मार्ट विलेज और आगे की ओर डेमो।", "filePage": "", "link": "", "caution": "Don't add parts that aren't there — no rainwater harvesting, only ONE windmill and TWO flower pots."},
  {"id": "md-tour-order", "topic": "model-talk", "q": "In what order should I explain my model?", "alts": ["which part should I explain first", "presentation order", "how to present my model", "model presentation path", "where do I start explaining", "order of explaining parts", "model kaise present karun", "best route around my model", "how should i walk the judge through my model", "order of my modle tour"], "keywords": ["order", "presentation path", "route", "start", "sequence", "walk the judge"], "answer": "Follow one clear path: Smart City → transport → centre (India map) → dustbins → Smart Village → water (factory and filter) → energy (plastic-to-energy) → conclusion. For each part, say what it is, why it is there, how it works and how it links to Clean India. Point with an open hand, then look back at the judge.", "fun": "", "check": {"q": "Which part comes right after the Smart Village in your tour?", "a": "Water — the factory and the filter."}, "hi": "एक साफ़ क्रम में समझाइए: स्मार्ट सिटी → परिवहन → बीच का भाग → कूड़ेदान → स्मार्ट विलेज → पानी → ऊर्जा → निष्कर्ष।", "filePage": "", "link": ""},
  {"id": "md-smart-city", "topic": "model-talk", "q": "What is a Smart City in your model?", "alts": ["what is a smart city", "smart city meaning", "what is on the left side of your model", "why did you make a smart city", "smart city kya hai", "explain your smart city", "what makes a city smart", "smart citty", "what is in the smart city part"], "keywords": ["smart city", "left side", "city", "clean energy", "public transport"], "answer": "A Smart City uses good planning and clean ideas to keep people healthy and the air and water clean. In your model it is on the left: three buildings with solar panels (two handmade, one real), two toilets, an EV charging station and an electric bus stand with two buses. Together they show clean energy, sanitation and cleaner transport.", "fun": "India's Smart Cities Mission was launched on 25 June 2015 to improve 100 cities — and Chandigarh, your city, joined it in 2016!", "check": {"q": "Name two things in your Smart City that help keep the air clean.", "a": "Any two: solar panels, the EV station, the electric buses."}, "hi": "स्मार्ट सिटी अच्छी योजना और स्वच्छ ऊर्जा से लोगों को स्वस्थ और हवा-पानी को साफ़ रखती है; आपके मॉडल में सोलर इमारतें, दो शौचालय, ईवी स्टेशन और इलेक्ट्रिक बस स्टैंड हैं।", "filePage": "", "link": "#model/solar"},
  {"id": "md-smart-village", "topic": "model-talk", "q": "What is a Smart Village in your model, and what is the hut?", "alts": ["what is a smart village", "smart village meaning", "what is on the right side of your model", "what does the hut show", "smart gaon kya hai", "why did you make a village", "explain your smart village", "smart vilage", "what is the handmade hut"], "keywords": ["smart village", "hut", "right side", "village", "local resources"], "answer": "A Smart Village is clean and healthy, and uses what it already has — like cow dung and kitchen or crop waste — to make energy and manure. In your model it is on the right: a handmade hut (a village home), a digger field, one toilet and a biogas plant. It shows that Clean India is for villages too, not only cities.", "fun": "By September 2026, about 5.69 lakh Indian villages were ODF Plus — they stay open-defecation free and also manage their waste. About 5.25 lakh reached the top 'Model' stage!", "check": {"q": "Name the four things in your Smart Village.", "a": "Hut, digger field, toilet and biogas plant."}, "hi": "स्मार्ट विलेज साफ़ और स्वस्थ होता है और गोबर व कचरे जैसी अपनी चीज़ों से ऊर्जा और खाद बनाता है; आपके मॉडल में झोपड़ी, डिगर वाला खेत, एक शौचालय और बायोगैस प्लांट हैं।", "filePage": "", "link": "#model/hut", "caution": "Don't add solar lights, crops or rainwater harvesting to the village — they are not in the model."},
  {"id": "md-solar", "topic": "model-talk", "q": "What are the solar panels in your model and how do they work?", "alts": ["solar panel in your model", "why did you put solar panels", "how does your solar panel light the bulb", "what are the three buildings", "solar panel kaise kaam karta hai", "is your solar panel real", "solar pannel", "why are two solar panels handmade", "how does the bulb glow on the building"], "keywords": ["solar panel", "three buildings", "real panel", "bulb", "sunlight", "handmade"], "answer": "Your Smart City has three buildings: two have handmade solar panels, and the third has a REAL solar panel that lights a bulb in sunlight. Sunlight makes tiny electrons in the solar cells move, and moving electrons are an electric current — light energy becomes electrical energy. You included it because solar is renewable and means less coal burnt, so less smoke.", "fun": "'Photovoltaic' joins 'photo' (light) with 'volt', named after Alessandro Volta, the Italian scientist who built the voltaic pile, an early battery, around 1800.", "check": {"q": "Why might your bulb not glow in a dark room?", "a": "A solar panel needs sunlight or strong light to make electricity."}, "hi": "तीन इमारतों में से दो पर हाथ से बने सोलर पैनल हैं और एक पर असली पैनल है जो धूप में बल्ब जलाता है — सूरज की रोशनी बिजली में बदल जाती है।", "filePage": "p18", "link": "#model/solar", "caution": "Say solar 'reduces' pollution — not 'zero impact'; making panels uses energy and old panels must be recycled."},
  {"id": "md-city-toilets", "topic": "model-talk", "q": "Why are there two toilets in your Smart City?", "alts": ["what are the toilets in your model", "why did you include toilets", "why do we need toilets", "city toilets meaning", "toilet kyon zaroori hai", "why male and female toilets", "what do the toilets show", "toilets in smart city", "why toilet in a cleanliness model", "tiolets in city"], "keywords": ["city toilets", "two toilets", "need toilet", "sanitation", "male female", "germs"], "answer": "The two toilets (one with a male sign, one with a female sign) show sanitation — the first big goal of the Clean India Mission. Human waste has germs; if it is left in the open, flies and rainwater carry them to our food and water. Separate toilets also give safety and dignity, especially to girls and women.", "fun": "In cities, the mission built about 63.8 lakh home toilets (108% of the target) and about 6.36 lakh community and public toilet seats (125%)!", "check": {"q": "Name one disease that spreads because of poor sanitation.", "a": "Diarrhoea, cholera or typhoid."}, "hi": "दो शौचालय स्वच्छता दिखाते हैं — इनसे कीटाणु हमारे पानी और खाने तक नहीं पहुँचते, और लड़कियों व महिलाओं को सुरक्षा और सम्मान मिलता है।", "filePage": "p9", "link": "#model/citytoilets", "caution": "Don't say 'there is no open defecation anywhere now' — say the mission greatly improved toilet access."},
  {"id": "md-ev", "topic": "model-talk", "q": "What is the EV charging station in your model and how does it work?", "alts": ["ev station in your model", "what happens when you press the button", "why does the green light glow", "electric car charging station", "ev charging kaise hota hai", "what is an ev", "why did you include an electric car", "ev chargng station", "what does the green light mean"], "keywords": ["ev", "charging station", "button", "green light", "electric car", "battery"], "answer": "EV means Electric Vehicle — it runs on a battery and an electric motor, not petrol or diesel. In your model, pressing the button makes a green light glow to show the car is charging. The charger fills the battery with electricity, and the battery later runs the motor. It is there because EVs give no exhaust smoke, so city air stays cleaner.", "fun": "Battery electric cars don't have an exhaust pipe at all — they burn no fuel, so there is nothing to puff out!", "check": {"q": "Where does an EV get its energy when it moves?", "a": "From its battery, which powers an electric motor."}, "hi": "ईवी बैटरी और इलेक्ट्रिक मोटर से चलती है; बटन दबाने पर हरी लाइट जलती है जो चार्जिंग दिखाती है, और इससे धुआँ नहीं निकलता।", "filePage": "", "link": "#model/ev", "caution": "Don't say EVs cause 'no pollution at all' — the benefit depends on how the electricity is made."},
  {"id": "md-bus", "topic": "model-talk", "q": "Why is there an electric bus stand in your model?", "alts": ["electric bus in your model", "what is the bus stand", "why two buses", "why public transport in your model", "electric bus kyon", "how many buses in your model", "e-bus stand", "electirc bus", "why is a bus better than a car"], "keywords": ["electric bus", "bus stand", "two buses", "public transport", "fewer cars"], "answer": "Your Smart City has a bus stand with two electric buses. One bus carries many people, so fewer cars are on the road, and an electric bus has no tailpipe smoke. Fewer vehicles plus no exhaust means cleaner air, less noise and less fuel burnt. Just like the EV, a big battery runs its electric motor.", "fun": "Many electric buses use 'regenerative braking': when they slow down, the motor works like a generator and puts some energy back into the battery!", "check": {"q": "Give one reason one bus is better than many cars.", "a": "It carries many people, so there are fewer vehicles, less traffic and less pollution."}, "hi": "बस स्टैंड पर दो इलेक्ट्रिक बसें हैं — एक बस में बहुत लोग जाते हैं, इसलिए सड़क पर कम गाड़ियाँ और कम धुआँ होता है।", "filePage": "", "link": "#model/bus", "caution": "The benefit still depends partly on how the electricity is produced."},
  {"id": "md-train", "topic": "model-talk", "q": "What is the hydrogen train in your model?", "alts": ["hydrogen train in your model", "jind sonipat train", "why did you put a train", "how does your hydrogen train work", "hydrogen train kya hai", "what comes out of the hydrogen train", "hydrogen trian", "which route is your train", "railway track in your model"], "keywords": ["hydrogen train", "jind", "sonipat", "fuel cell", "railway track", "water vapour"], "answer": "In front of your model is a hydrogen train on a track labelled Jind ↔ Sonipat. India's first hydrogen train was flagged off at Jind, Haryana, on 17 July 2026, on the 89 km Jind–Gohana–Sonipat route. In its fuel cells, hydrogen and oxygen react to make electricity, so the main onboard by-product is water vapour, not diesel smoke.", "fun": "The real train has 10 coaches for about 2,600 passengers, and Jind has India's largest railway hydrogen storage — about 3,000 kg!", "check": {"q": "Is hydrogen burnt like diesel in the train?", "a": "No — it reacts with oxygen in a fuel cell to make electricity and water."}, "hi": "आपके मॉडल में जींद–सोनीपत हाइड्रोजन ट्रेन है; इसके फ्यूल सेल में हाइड्रोजन और ऑक्सीजन से बिजली बनती है और मुख्य रूप से जलवाष्प निकलती है।", "filePage": "p16", "link": "#model/train", "caution": "It is truly 'green' only if the hydrogen is made with renewable electricity — don't say 'no pollution at all'."},
  {"id": "md-india-map", "topic": "model-talk", "q": "What does the India map with 'Carbon Emission' show?", "alts": ["india map in your model", "why is carbon emission written", "what is in the centre of your model", "carbon emission meaning in your model", "india ka naksha kyon", "why is india in the middle", "carbon emmision", "what is the tricolour map", "centre of the model"], "keywords": ["india map", "carbon emission", "centre", "tricolour", "global warming", "co2"], "answer": "In the centre is an India-shaped tricolour design with the words 'Carbon Emission' below it. Carbon emission means releasing carbon dioxide into the air, mostly by burning coal, petrol, diesel and garbage; too much traps heat and causes global warming. Many parts around the map — solar, wind, EVs, the hydrogen train, biogas — show ways to reduce it.", "fun": "India has set a target of net-zero emissions by 2070, announced at the COP26 climate meeting in Glasgow in 2021.", "check": {"q": "Name one fuel that releases carbon dioxide when burnt.", "a": "Coal, petrol or diesel."}, "hi": "बीच में भारत का तिरंगा नक्शा और 'कार्बन उत्सर्जन' लिखा है — कोयला, पेट्रोल और कचरा जलाने से CO₂ बढ़ती है, और मॉडल के कई भाग इसे कम करने के तरीके दिखाते हैं।", "filePage": "", "link": "#model/india", "caution": "Global warming is 'mainly' caused by human activities — avoid saying 'only'."},
  {"id": "md-ladder", "topic": "model-talk", "q": "What does the ladder in your model mean?", "alts": ["what is the ladder", "why is there a ladder", "ladder below carbon emission", "ladder meaning", "seedhi kyon hai", "what does the ladder represent", "ladar in model", "what is the ladder in the centre", "explain the ladder"], "keywords": ["ladder", "seedhi", "below carbon emission", "centre"], "answer": "The ladder stands in the centre, below the words 'Carbon Emission' (not on the road). What it represents is not confirmed yet — please ask Rajnish Ma'am before you explain it. Until then, talk about carbon emission using the India map instead. Once Ma'am tells you, you'll have a brand-new answer ready!", "fun": "", "check": {"q": "Who should you ask about what the ladder means?", "a": "Rajnish Ma'am."}, "hi": "सीढ़ी बीच में 'कार्बन उत्सर्जन' के नीचे है; इसका मतलब अभी पक्का नहीं है — समझाने से पहले रजनीश मैम से पूछिए।", "filePage": "", "link": "#model/ladder", "caution": "Don't invent a meaning for the ladder."},
  {"id": "md-windmill", "topic": "model-talk", "q": "What does the windmill in your model show?", "alts": ["windmill in your model", "why did you include a windmill", "how does a windmill make electricity", "wind turbine in your model", "pawan chakki kya hai", "how many windmills are there", "windmil", "wind energy in your model", "what is the windmill for"], "keywords": ["windmill", "wind turbine", "wind energy", "one windmill", "blades", "generator", "make electricity"], "answer": "Your model has ONE windmill, in the centre, to show wind energy. In a real wind turbine, wind turns the blades, the blades turn a shaft, and the shaft turns a generator that makes electricity — the energy of moving air becomes electrical energy. Wind is renewable and makes no smoke while it runs, but it works best where winds are strong.", "fun": "India ranks 4th in the world for installed wind power, and aims for about 100 GW of wind power by 2030.", "check": {"q": "Which part inside a wind turbine actually makes the electricity?", "a": "The generator."}, "hi": "मॉडल में एक पवनचक्की पवन ऊर्जा दिखाती है — हवा पंखों को घुमाती है और अंदर का जनरेटर बिजली बनाता है।", "filePage": "p17", "link": "#model/windmill", "caution": "There is only ONE windmill. Don't claim your model windmill makes electricity unless it really does."},
  {"id": "md-windmill-working", "topic": "model-talk", "q": "Is your model's windmill working?", "alts": ["does your windmill turn", "does your model windmill produce power", "is the windmill real", "windmill chalti hai kya", "is the windmill just for show", "does your windmill light anything", "is the windmill working or a display", "can your windmill spin", "windmill workin"], "keywords": ["windmill working", "windmill turn", "spin", "display only", "only for show"], "answer": "That is not confirmed yet — check with Rajnish Ma'am whether your windmill really turns or makes electricity, or is only a display. If it is a display, say honestly: 'This windmill shows the idea of wind energy; a real turbine turns a generator to make electricity.' Your four working demos are the solar panel, EV button, filter and plastic-to-energy bulb.", "fun": "Real wind farms are built where winds are strong and regular, like coasts and wide open land.", "check": {"q": "If the windmill is only a display, what should you tell a judge?", "a": "It shows the idea of wind energy; in a real turbine a generator makes electricity."}, "hi": "पवनचक्की सच में घूमती या बिजली बनाती है या सिर्फ़ दिखाने के लिए है — यह रजनीश मैम से पूछकर पक्का कीजिए।", "filePage": "", "link": "#model/windmill", "caution": "Never claim the windmill makes electricity unless you have seen it do so."},
  {"id": "md-pots", "topic": "model-talk", "q": "Why are there two flower pots in your model?", "alts": ["flower pots in your model", "what do the plants show", "why plants in the centre", "how many flower pots", "gamla kyon rakha", "park in your model", "flowerpots meaning", "why green plants in your model", "flower pot ka matlab"], "keywords": ["flower pots", "two pots", "plants", "park", "photosynthesis"], "answer": "The TWO flower pots in the central park show that green spaces make a city healthier and more beautiful. During photosynthesis, plants use sunlight, water and carbon dioxide to make food and give out oxygen. So plants help take in some of the CO₂ your India map talks about.", "fun": "Flower pots can be made from old tins or bottles — that's the 'Repurpose' R, giving waste a brand-new job!", "check": {"q": "Which gas do plants take in during photosynthesis?", "a": "Carbon dioxide."}, "hi": "दो गमले दिखाते हैं कि हरियाली शहर को स्वस्थ बनाती है — पौधे कार्बन डाइऑक्साइड लेकर ऑक्सीजन देते हैं।", "filePage": "", "link": "#model/pots", "caution": "There are only TWO pots — don't describe gardens or trees that are not in the model."},
  {"id": "md-plastic-man", "topic": "model-talk", "q": "Who is in the Plastic Man photo in your model?", "alts": ["plastic man of india", "whose photo is in your model", "why did you put the plastic man", "who is rajagopalan vasudevan", "plastic man kaun hai", "plastic road man", "plastik man", "photo in the centre", "why is his picture in your model"], "keywords": ["plastic man", "vasudevan", "photo", "plastic roads", "padma shri"], "answer": "It is Professor Rajagopalan Vasudevan, a chemistry professor from Madurai, Tamil Nadu, known as the 'Plastic Man of India'. He found a way to use shredded waste plastic in strong roads, received the Padma Shri in 2018, and gave his technology to the Government of India for free. His photo shows that waste plastic can be put to good use.", "fun": "One of the first plastic roads was laid in 2002 on Jambulingam Street in Chennai!", "check": {"q": "Which award did the Plastic Man receive in 2018?", "a": "The Padma Shri."}, "hi": "यह प्रोफ़ेसर राजगोपालन वासुदेवन हैं, 'भारत के प्लास्टिक मैन', जिन्होंने बेकार प्लास्टिक से सड़कें बनाने का तरीका खोजा और 2018 में पद्मश्री पाया।", "filePage": "", "link": "#model/plasticman", "caution": "Plastic roads don't solve the whole plastic problem — refusing and reducing plastic still come first."},
  {"id": "md-digger", "topic": "model-talk", "q": "What does the digger field in your model mean?", "alts": ["what is the digger field", "why is there a jcb", "digger in your village", "field with digger meaning", "jcb wala khet kya hai", "what does the toy digger show", "diger field", "what is the fenced field", "why a digger in the smart village"], "keywords": ["digger", "jcb", "field", "fence", "digger field"], "answer": "The digger field is in your Smart Village: a field area with a toy digger (JCB) and a fence. What it represents is not confirmed yet — please ask Rajnish Ma'am before you explain it. Until then, don't guess; talk about the hut, the toilet and the biogas plant instead.", "fun": "", "check": {"q": "What can you see in the digger field?", "a": "A toy digger (JCB) and a fence."}, "hi": "स्मार्ट विलेज के खेत में एक खिलौना जेसीबी और बाड़ है; इसका मतलब अभी पक्का नहीं है — रजनीश मैम से पूछिए।", "filePage": "", "link": "#model/digger", "caution": "Don't invent crops, compost pits or landfills for this part."},
  {"id": "md-village-toilet", "topic": "model-talk", "q": "Why is there a toilet in your Smart Village?", "alts": ["village toilet", "why toilet in the village", "what is the village toilet", "rural sanitation in your model", "gaon mein shauchalay kyon", "is the toilet connected to the biogas plant", "villge toilet", "toilet in smart village", "why do villages need toilets"], "keywords": ["village toilet", "rural", "sanitation", "swachh bharat grameen", "pond", "well"], "answer": "Just like the city, your village has one toilet, because a clean village is a healthy village. Toilets in every village were a main goal of Swachh Bharat Mission (Grameen). A toilet keeps human waste in a closed pit or tank, so germs don't reach ponds, wells and fields. Check with Ma'am before saying it is connected to the biogas plant.", "fun": "Twin-pit toilets use one pit at a time; when it fills, the other is used, and the waste in the first slowly turns into safe manure!", "check": {"q": "Which part of the Swachh Bharat Mission is for villages?", "a": "Swachh Bharat Mission (Grameen)."}, "hi": "शहर की तरह गाँव में भी एक शौचालय है, ताकि कीटाणु तालाबों, कुओं और खेतों तक न पहुँचें — साफ़ गाँव ही स्वस्थ गाँव है।", "filePage": "", "link": "#model/villagetoilet", "caution": "Don't say the toilet is connected to the biogas plant unless it really is in your model."},
  {"id": "md-biogas", "topic": "model-talk", "q": "How does the biogas plant in your model work?", "alts": ["biogas plant in your model", "why did you include biogas", "what is the pipe to the stove", "model mein biogas kaise banti hai", "explain your biogas plant", "biogass plant", "what goes into your biogas plant", "village biogas in your model", "what does the stove show"], "keywords": ["biogas plant", "pipe", "stove", "cow dung", "without oxygen", "methane"], "answer": "Cow dung and kitchen waste go into a closed tank called a digester. Without oxygen, tiny microbes break them down and make biogas — mainly methane — which travels through the pipe to the stove for cooking. The leftover slurry is good manure. You included it to show a village turning waste into energy, not pollution.", "fun": "Biogas is about 50–70% methane, and a biogas plant captures methane that would otherwise escape from rotting waste into the air.", "check": {"q": "What is the process of making biogas without oxygen called?", "a": "Anaerobic digestion."}, "hi": "बायोगैस प्लांट में गोबर और रसोई का कचरा बिना ऑक्सीजन के सूक्ष्मजीवों से टूटकर बायोगैस (ज़्यादातर मीथेन) बनाता है, जो पाइप से चूल्हे तक जाती है।", "filePage": "p21", "link": "#model/biogas", "caution": "Burning biogas also makes CO₂ — say it is cleaner than firewood or dung cakes, not 'pollution-free'."},
  {"id": "md-bins", "topic": "model-talk", "q": "What do the five dustbins in your model stand for?", "alts": ["five dustbins", "bin colours in your model", "what is the black bin", "red bin meaning", "what is the yellow bin for", "kaunsa dabba kis liye", "why five bins", "dustbin colors", "green and blue bin", "segregation bins in your model"], "keywords": ["five dustbins", "bin colours", "green blue", "black red yellow", "segregation"], "answer": "Green = wet waste (peels, leftover food) for compost or biogas. Blue = dry waste (paper, plastic, metal, glass) for recycling. In Chandigarh's system, black = domestic hazardous waste (batteries, bulbs) and red = sanitary waste; yellow is most likely biomedical waste — confirm black, red and yellow with Rajnish Ma'am. Big idea: mixed waste becomes garbage; separated waste becomes a resource.", "fun": "Chandigarh made its four-bin system for homes compulsory from April 2026, with fines for people who don't separate their waste!", "check": {"q": "Which bin colour is for wet waste?", "a": "Green."}, "hi": "हरा = गीला कचरा, नीला = सूखा कचरा; चंडीगढ़ में काला = घरेलू खतरनाक और लाल = सैनिटरी कचरा, पीला शायद बायोमेडिकल — मैम से पक्का करें।", "filePage": "p20", "link": "#model/bins", "caution": "Say 'in Chandigarh's system' — colours differ elsewhere (in hospitals, red means contaminated plastic)."},
  {"id": "md-factory", "topic": "model-talk", "q": "What is the Sugar & Leather factory in your model?", "alts": ["factory in your model", "why sugar and leather industry", "what is the pump for", "dirty water factory", "factory ka ganda paani", "industry in your model", "sugar leather factry", "why a factory with chimneys", "what does the pump do"], "keywords": ["factory", "sugar", "leather", "pump", "dirty water", "industry"], "answer": "It is a factory labelled 'Sugar & Leather Industry (Dirty Water)', with chimneys, joined by pipes to a pump and your water-cleaning setup. Sugar mills and leather tanneries release wastewater full of chemicals. If it reaches rivers, it can kill fish and pollute drinking water, so factories must first treat it in an Effluent Treatment Plant (ETP).", "fun": "Leather tanneries often use chromium salts to tan leather, so their wastewater may contain chromium, which is toxic and needs special treatment.", "check": {"q": "What does ETP stand for?", "a": "Effluent Treatment Plant."}, "hi": "चीनी और चमड़ा उद्योग का कारखाना गंदा पानी छोड़ता है; नदी में जाने से पहले इसे एफ़्लुएंट ट्रीटमेंट प्लांट (ETP) में साफ़ करना ज़रूरी है।", "filePage": "p28", "link": "#model/factory"},
  {"id": "md-filter", "topic": "model-talk", "q": "How does the water filter in your model work?", "alts": ["water filter in your model", "what are the layers in your filter", "why charcoal stones and cotton", "how does your filter clean water", "filter kaise kaam karta hai", "multi layer filter", "water filtter", "why is cotton at the bottom", "what does the charcoal do", "explain your filtration demo"], "keywords": ["water filter", "layers", "charcoal", "stones", "cotton", "filtration"], "answer": "Dirty water pumped from the factory flows down through layers, coarsest to finest: stones and gravel catch big bits, sand (if your model has it) catches smaller dirt, charcoal holds some chemicals, colour and smell, and cotton at the bottom traps tiny particles and charcoal dust. The water comes out clearer — but it is NOT safe to drink; it may still have germs and dissolved chemicals.", "fun": "Activated charcoal is charcoal treated to have even more tiny pores, so more impurities can stick to its surface — that sticking is called adsorption!", "check": {"q": "Is the water from your filter safe to drink?", "a": "No — it may still have germs and dissolved chemicals."}, "hi": "गंदा पानी पत्थर, कोयले और रुई जैसी परतों से गुज़रकर साफ़ दिखता है, लेकिन यह पीने लायक नहीं है — इसमें कीटाणु और घुले रसायन हो सकते हैं।", "filePage": "p24", "link": "#model/filter", "caution": "Never say the filtered water is safe to drink. Mention sand only if your model filter really has a sand layer."},
  {"id": "md-filter-vs-etp", "topic": "model-talk", "q": "Is your filter the same as a real Effluent Treatment Plant (ETP)?", "alts": ["difference between your filter and an etp", "is your filter an etp", "filter vs etp", "how is a real etp different", "filter aur etp mein kya fark hai", "can your filter fully clean factory water", "real treatment plant vs your model", "filter and effluent plant difference", "etp vs filtr"], "keywords": ["filter vs etp", "difference", "effluent treatment plant", "biological step", "simple filtration"], "answer": "No. Your filter shows only the first, simple physical step — removing particles. A real ETP is a big plant: screens and settling tanks remove solids, chemicals balance the water and remove harmful things like chromium, useful bacteria 'eat' dissolved dirt, and then come final filtering, disinfection and testing. The treated water is reused or safely released — not drunk.", "fun": "Small factories can share one Common Effluent Treatment Plant (CETP), and some industries aim for 'Zero Liquid Discharge' — treating and reusing all their water!", "check": {"q": "Name one step a real ETP has that your filter doesn't.", "a": "The biological (bacteria) step, chemical treatment, or disinfection."}, "hi": "आपका फ़िल्टर सिर्फ़ पहला सरल कदम दिखाता है; असली ETP में भौतिक, रासायनिक और जैविक (बैक्टीरिया) सफ़ाई और जाँच होती है।", "filePage": "p24", "link": "#model/factory", "caution": "Say 'my filter shows only the first, simple step of cleaning water'."},
  {"id": "md-wte", "topic": "model-talk", "q": "How does the plastic-to-energy machine in your model work?", "alts": ["plastic to energy machine", "why does the bulb glow in your machine", "waste to energy in your model", "do you burn plastic for electricity", "plastic se bijli kaise", "what is the red fire chamber", "plastic-to-energy machin", "explain your wte machine", "how does waste make electricity in your model"], "keywords": ["plastic-to-energy", "machine", "bulb", "waste to energy", "turbine", "steam"], "answer": "Your handmade machine shows waste-to-energy: when it is switched on, the bulb glows to show electricity. In a real plant, only waste that CANNOT be recycled is treated at very high temperature in a closed furnace; the heat boils water into steam, the steam spins a turbine, and the turbine turns a generator. Real plants must clean their smoke — and we must never burn plastic in the open.", "fun": "India's waste-to-energy capacity grew from about 230 MW in 2014 to about 878 MW in 2026 — almost four times bigger!", "check": {"q": "Which comes first: recycling plastic or making energy from it?", "a": "Recycling — energy recovery is only for waste that can't be recycled."}, "hi": "मशीन का बल्ब दिखाता है कि जो कचरा रीसायकल नहीं हो सकता, उसे प्रदूषण-नियंत्रण वाले बंद प्लांट में ऊर्जा में बदला जाता है — प्लास्टिक खुले में कभी न जलाएँ।", "filePage": "p11", "link": "#model/wte", "caution": "Never say 'we just burn plastic for electricity'. Confirm with Ma'am what each of the two separate units represents."},
  {"id": "md-demos", "topic": "model-talk", "q": "What are the four working demonstrations in your model?", "alts": ["which things in your model really work", "what works in your model", "what are your demos", "show me what works in your model", "kaun se parts chalte hain", "four demonstrations", "live demo in your model", "what lights up in your model", "demostrations"], "keywords": ["demonstrations", "working", "demo", "four demos", "bulb glows", "lights up"], "answer": "1) The real solar panel lights a bulb in sunlight. 2) Pressing the EV-station button makes a green light glow to show charging. 3) Dirty water passes through the filter and comes out clearer — a first cleaning step, not drinking-safe. 4) The plastic-to-energy machine lights a bulb to show energy recovered from waste that cannot be recycled.", "fun": "Two of your four demos light a bulb — the solar panel and the plastic-to-energy machine — but with two very different energy sources: sunlight and waste!", "check": {"q": "Which demo needs sunlight or strong light to work?", "a": "The real solar panel."}, "hi": "चार डेमो: असली सोलर पैनल बल्ब जलाता है, ईवी बटन से हरी लाइट जलती है, फ़िल्टर पानी को साफ़ दिखाता है, और प्लास्टिक-से-ऊर्जा मशीन बल्ब जलाती है।", "filePage": "", "link": "", "caution": "Say the filtered water is 'clearer', not 'safe to drink'."},
  {"id": "md-why-topic", "topic": "model-talk", "q": "Why did you choose this topic?", "alts": ["why did you pick clean india as your topic", "why waste management topic", "reason for choosing this project", "aapne yeh topic kyon chuna", "why this project", "what made you pick this topic", "why did you choose swachh bharat", "why did you chose this topic", "reason for your project"], "keywords": ["choose", "chose", "topic", "reason", "why this project"], "answer": "A great answer starts with your opening question: every day we throw away plastic, food, fruit peels, paper and bottles — but where does all this waste go? Clean India touches everyone's health, water and air, and even a Class 6 student can help with small steps. Then add your OWN real reason, like something you noticed near your home or school.", "fun": "The Swachh Bharat Mission was launched on 2 October 2014, Mahatma Gandhi's birth anniversary, by Prime Minister Narendra Modi.", "check": {"q": "What big question does your speech begin with?", "a": "Where does all this waste go?"}, "hi": "अपने शुरुआती सवाल से जवाब दीजिए: हम रोज़ बहुत कचरा फेंकते हैं — पर वह जाता कहाँ है? फिर अपना असली कारण भी जोड़िए।", "filePage": "", "link": "#stage", "caution": "Use your own true reason — don't make up a story."},
  {"id": "md-learned", "topic": "model-talk", "q": "What did you learn from making this project?", "alts": ["what did you learn", "lessons from your project", "what is your main learning", "project se kya seekha", "what did this model teach you", "biggest lesson", "what did you lern", "key takeaways of your project", "what new things did you learn"], "keywords": ["learn", "learned", "lesson", "takeaway", "seekha"], "answer": "The biggest lesson: separated waste becomes a resource; mixed waste becomes garbage. Wet waste can become compost or biogas, and many kinds of dry waste can be recycled. Toilets protect our health and water. Clean energy reduces smoke, but its full benefit depends on how the electricity or hydrogen is made. Clear water is not always safe, and plastic must never be burnt in the open.", "fun": "", "check": {"q": "Finish the line: 'Mixed waste becomes garbage; separated waste becomes…'", "a": "…a resource."}, "hi": "सबसे बड़ी सीख: अलग किया गया कचरा संसाधन है और मिला हुआ कचरा बस कूड़ा; साफ़ दिखने वाला पानी हमेशा सुरक्षित नहीं होता और प्लास्टिक कभी खुले में नहीं जलाना चाहिए।", "filePage": "", "link": ""},
  {"id": "md-duties", "topic": "model-talk", "q": "What can students do to keep India clean?", "alts": ["what can we do to keep india clean", "our duties towards our nation", "how can students help", "what can you do as a student", "hum kya kar sakte hain", "duties for clean india", "how can i help swachh bharat", "student duties", "what should citizens do", "our dutys"], "keywords": ["duties", "students", "keep india clean", "help", "littering", "car pooling", "awareness"], "answer": "Your file's 'Our Duties Towards Our Nation' page lists nine: stop littering, segregate waste, maintain public cleanliness, promote behaviour change, spread awareness, plant more trees, use public transport, focus on recycling, and car pool. Your pledge adds: carry a cloth bag and your own water bottle. Small steps can make a big difference!", "fun": "Since 1 July 2022, India has banned 19 single-use plastic items, such as plastic straws, cutlery and ear-bud sticks.", "check": {"q": "Name three duties from your list.", "a": "Any three: stop littering, segregate waste, public cleanliness, behaviour change, awareness, plant trees, public transport, recycling, car pooling."}, "hi": "हमारे कर्तव्य: कूड़ा न फैलाएँ, कचरा अलग करें, सार्वजनिक जगहें साफ़ रखें, जागरूकता फैलाएँ, पेड़ लगाएँ, सार्वजनिक परिवहन और कार-पूलिंग अपनाएँ, और रीसाइक्लिंग करें।", "filePage": "", "link": ""},
  {"id": "md-quotes", "topic": "model-talk", "q": "What are your favourite quotes?", "alts": ["your quotes", "which quotes do you use", "favourite lines", "slogans in your project", "aapke quotes kaun se hain", "top quotes", "favorite quote", "quotes for my model", "famous lines from your file"], "keywords": ["quotes", "favourite", "slogans", "lines", "thought"], "answer": "Your three stage quotes: 'The best waste is the waste we never create' (for the 7Rs), 'Turn waste into energy, not pollution' (at the biogas plant), and 'Clean water is precious — treat it, reuse it, protect it' (at the water filter). Your closing line is 'A clean India is not just a dream; it is a responsibility we share.'", "fun": "", "check": {"q": "Which quote goes with your biogas plant?", "a": "Turn waste into energy, not pollution."}, "hi": "तीन मुख्य विचार: 'सबसे अच्छा कचरा वह है जो हम कभी बनाते ही नहीं', 'कचरे को प्रदूषण नहीं, ऊर्जा बनाइए', और 'पानी अनमोल है — इसे साफ़ करें, दोबारा इस्तेमाल करें, और बचाएँ'।", "filePage": "", "link": "#thoughts"},
  {"id": "md-quote-best-waste", "topic": "model-talk", "q": "What does 'The best waste is the waste we never create' mean?", "alts": ["meaning of the best waste quote", "explain the best waste is the waste we never create", "best waste quote meaning", "sabse achha kachra kaunsa hai", "what does never create waste mean", "explain your 7rs quote", "best wast quote", "waste we never create"], "keywords": ["best waste", "never create", "refuse", "reduce", "7rs quote"], "answer": "It means stopping waste before it is made is better than any clean-up. If you refuse a plastic bag and carry a cloth bag, there is nothing to collect, sort, recycle or burn. That's why Refuse and Reduce come first in the 7Rs and Recover comes last. It is the lesson your file's 7Rs page ends with.", "fun": "The 7Rs stretch the famous 3Rs (Reduce, Reuse, Recycle) by adding four more: Refuse, Repair, Repurpose and Recover.", "check": {"q": "Which R comes first in the 7Rs?", "a": "Refuse."}, "hi": "सबसे अच्छा कचरा वह है जो हम कभी बनाते ही नहीं — यानी कचरा बनने से पहले ही रोकना, जैसे प्लास्टिक थैली को मना करके कपड़े का थैला लेना।", "filePage": "p23", "link": "#thoughts"},
  {"id": "md-quote-dream", "topic": "model-talk", "q": "What does 'A clean India is not just a dream; it is a responsibility we share' mean?", "alts": ["meaning of clean india is not just a dream", "explain your closing quote", "responsibility we share meaning", "swachh bharat sirf sapna nahin", "what is your last line", "final quote meaning", "clean india dream quote", "whose job is clean india", "responsibilty quote"], "keywords": ["not just a dream", "responsibility", "share", "closing quote", "every citizen"], "answer": "It means a clean India won't happen just by wishing, or by the government alone — every one of us has to help, every day. Your file's conclusion says the same: the Clean India Mission is not only a government programme but a responsibility for every citizen. That's why it is your closing line before 'Thank you, Jai Hind!'", "fun": "India's 'Swachhata Hi Seva' (Cleanliness is Service) drive was first held from 15 September to 2 October 2017, ending on Gandhi Jayanti — and it has been held again in later years.", "check": {"q": "According to this quote, who is responsible for a clean India?", "a": "All of us — every citizen."}, "hi": "स्वच्छ भारत सिर्फ़ एक सपना नहीं, यह हम सबकी ज़िम्मेदारी है — सिर्फ़ सरकार नहीं, हर नागरिक को रोज़ मदद करनी है।", "filePage": "p9", "link": "#thoughts"},
  {"id": "md-quote-habit", "topic": "model-talk", "q": "What does your quote about cleanliness being a habit mean?", "alts": ["cleanliness is not a job we should do forcefully meaning", "october 2nd photo-op quote", "cleanliness is a good habit quote", "safai ek aadat hai", "why cleanliness every day", "explain the habit quote", "cleanliness everyday habit", "what does photo op mean", "habbit quote meaning"], "keywords": ["habit", "forcefully", "october 2nd", "every day", "photo-op", "way of life"], "answer": "Your file says, 'Cleanliness is not a job we should do forcefully. It is a good habit and healthy way of our life!' It means we keep things clean because we care, not because someone forces us. Another line in your file says cleanliness can't be just an October 2nd photo-op (a one-day show for photos) — it must happen every day.", "fun": "The Swachh Bharat tagline 'Ek kadam swachhata ki ore' (One step towards cleanliness) was written by Bhagyashree Sheth of Rajkot, Gujarat, who won a MyGov contest in 2014.", "check": {"q": "Should cleanliness be only for 2nd October?", "a": "No — it should be an everyday habit."}, "hi": "स्वच्छता कोई मजबूरी का काम नहीं, यह एक अच्छी आदत है — इसे सिर्फ़ 2 अक्टूबर को नहीं, हर दिन करना चाहिए।", "filePage": "p26", "link": "#thoughts"},
  {"id": "md-improve", "topic": "model-talk", "q": "What would you improve or add to your model?", "alts": ["if you had more time what would you add", "how can you improve your model", "what is missing in your model", "model mein kya sudhar karogi", "future improvements", "what would you change in your model", "improvment ideas", "next version of your model", "add something new to your model"], "keywords": ["improve", "add", "more time", "smart bin", "sensor", "compost pit"], "answer": "Pick one or two sensible ideas and say WHY: a compost pit next to the green bin, to show wet waste turning into manure; a smart bin with a fill-level sensor that sends an alert when it is nearly full; or a small label on every part so visitors understand it. Judges like an honest idea with a clear reason.", "fun": "A smart bin is part of the 'Internet of Things' (IoT) — everyday objects fitted with sensors that can share information over the internet!", "check": {"q": "How does a smart bin with a sensor help?", "a": "It sends an alert when it is nearly full, so it is emptied before it overflows."}, "hi": "हरे डिब्बे के पास कम्पोस्ट गड्ढा, सेंसर वाला स्मार्ट कूड़ेदान, या हर भाग पर लेबल जोड़ा जा सकता है — और बताइए कि इससे क्या फ़ायदा होगा।", "filePage": "", "link": "#viva"},
  {"id": "md-clean-india-link", "topic": "model-talk", "q": "How does your model connect to the Clean India Mission?", "alts": ["link between your model and swachh bharat", "how is your model related to clean india", "connection to swachh bharat abhiyan", "model aur swachh bharat ka sambandh", "why is this a clean india model", "how does your project help clean india", "clean inda mission link", "what message does your model give", "how does each part help india"], "keywords": ["clean india mission", "swachh bharat", "link", "connect", "message"], "answer": "Every part tells one story: less waste, cleaner air, cleaner water. Toilets show sanitation; the five bins, biogas plant and plastic-to-energy machine show waste management; solar, wind, EVs, buses and the hydrogen train show cleaner air; the factory and filter show cleaner water. As your file's conclusion says, Clean India is every citizen's responsibility.", "fun": "India has about 2,500 old dumpsites, and more than 1,000 of them have been fully cleared.", "check": {"q": "Which parts of your model are about clean water?", "a": "The factory, the pump and the water filter."}, "hi": "मॉडल का हर भाग एक ही कहानी कहता है — कम कचरा, साफ़ हवा और साफ़ पानी; यही स्वच्छ भारत मिशन का संदेश है।", "filePage": "p23", "link": ""},
  {"id": "md-eco-dost", "topic": "model-talk", "q": "Who is Eco-Dost?", "alts": ["who are you", "tell me about yourself", "are you a chatbot", "are you a real ai", "introduce yourself", "what is eco dost", "tum kaun ho", "what do you do", "are you a robot", "what can eco-dost do"], "keywords": ["eco-dost", "chatbot", "yourself", "buddy", "introduce", "bot"], "answer": "I'm Eco-Dost 🤖, your project buddy on this practice website! I answer questions about your project file and your model from fact-checked answer cards, and I don't make things up — if I don't know, I save your question for your mentor. Type or 🎤 speak a question, or tap 🎲 Quiz me to test yourself.", "fun": "'Dost' means 'friend' in Hindi — so Eco-Dost means 'eco-friend'!", "check": {"q": "What does 'dost' mean in Hindi?", "a": "Friend."}, "hi": "मैं इको-दोस्त हूँ, आपका प्रोजेक्ट साथी — मैं आपकी फ़ाइल और मॉडल के बारे में जाँचे हुए जवाब देता हूँ।", "filePage": "", "link": ""},
  {"id": "md-quiz", "topic": "model-talk", "q": "Can you quiz me?", "alts": ["quiz me", "test me", "ask me questions", "mujhse sawal pucho", "let's play a quiz", "give me a quiz", "how do i get points", "how do levels and badges work", "kwiz me", "check my knowledge"], "keywords": ["quiz", "test me", "points", "badges", "levels", "stars"], "answer": "Yes! Tap the 🎲 Quiz me button and I'll ask YOU a question. Try to answer out loud first, then tap 'Show answer' and be honest: 'I got it!' or 'Not yet'. You earn 1 ⭐ for each new question you ask, and 2 ⭐ the first time you get each quick check right.", "fun": "Ask 5 questions on one topic to win its badge — 5 model questions make you a 🏗️ Model Master — and 50 ⭐ makes you a 🌍 Planet Hero!", "check": {"q": "How many ⭐ do you get for getting a quick check right?", "a": "2 ⭐ (the first time for each check)."}, "hi": "हाँ! 🎲 'Quiz me' बटन दबाइए, मैं आपसे सवाल पूछूँगा — हर नए सवाल पर 1 ⭐ और सही जवाब पर 2 ⭐ मिलते हैं।", "filePage": "", "link": ""},
  {"id": "ci-twin-pit", "topic": "clean-india", "q": "What is a twin-pit toilet?", "alts": ["twin pit toilet", "what is a two pit toilet", "why does a toilet have two pits", "twin pit shauchalay kya hai", "do gaddhe wala toilet", "how does a twin pit latrine work", "twin-pit toilet in villages"], "keywords": ["twin-pit", "two pits", "pit", "manure", "village toilet"], "answer": "A twin-pit toilet is joined by a pipe to two pits. One pit is used until it is full, then the pipe is switched to the second pit. While the second pit is being used, the waste in the first pit rests and slowly (in about one to two years) turns into safe manure. It is a simple, low-cost toilet for villages.", "fun": "", "check": {"q": "Why does a twin-pit toilet have two pits?", "a": "So one pit can rest and turn into safe manure while the other is used."}, "hi": "ट्विन-पिट शौचालय में दो गड्ढे होते हैं: एक भर जाने पर दूसरा इस्तेमाल होता है, और पहले गड्ढे का मल धीरे-धीरे सुरक्षित खाद बन जाता है।", "filePage": "", "link": "#model/villagetoilet"},
  {"id": "md-materials", "topic": "model-talk", "q": "What materials did you use to make your model?", "alts": ["what is your model made of", "materials used in the model", "which things did you use to make the model", "model kis cheez se bana hai", "model banane mein kya use kiya", "what did you build the model with", "material list of your model"], "keywords": ["materials", "made of", "cardboard", "wooden base", "built with"], "answer": "My model is built on one large green wooden base. I used cardboard and paper for the buildings, two handmade solar panels and the hut; one real solar panel with a bulb; an EV charging station with a toy car, a button and a green light; two model electric buses and a hydrogen train on a railway track; charcoal, stones and cotton in a container for the water filter; a handmade plastic-to-energy machine with a bulb; and one windmill, two flower pots and five coloured dustbins.", "fun": "", "check": {"q": "What is the base of your model made of?", "a": "One large green wooden base."}, "hi": "मेरा मॉडल लकड़ी के एक बड़े हरे बेस पर बना है; इसमें गत्ता, कागज़, एक असली सोलर पैनल, बल्ब, खिलौना कार, दो इलेक्ट्रिक बसें, हाइड्रोजन ट्रेन, फ़िल्टर के लिए कोयला (चारकोल), पत्थर व रुई, प्लास्टिक-से-ऊर्जा मशीन, एक पवनचक्की, दो गमले और पाँच रंगीन कूड़ेदान इस्तेमाल हुए हैं।", "filePage": "", "link": "#project", "caution": "Check that this list matches your real model before you say it."},
  {"id": "md-about-me", "topic": "model-talk", "q": "Introduce yourself: your name, class, school and teacher.", "alts": ["what is your name", "which school are you from", "who is your teacher", "which class are you in", "introduce yourself", "apna parichay do", "who made this project", "tell me about yourself"], "keywords": ["name", "school", "class", "teacher", "introduce"], "answer": "I am Avni Choudhary from Class 6, Sharda Sarvhitkari Senior Secondary School, Chandigarh. My science teacher is Rajnish Ma'am, and my project is 'Clean India Mission and Waste Management'.", "fun": "", "check": {"q": "Say your opening line: greeting, name, class and topic!", "a": "Jai Hind! I am Avni Choudhary from Class 6, and my topic is Clean India Mission and Waste Management."}, "hi": "मैं अवनि चौधरी हूँ। मैं शारदा सर्वहितकारी सीनियर सेकेंडरी स्कूल, चंडीगढ़ में कक्षा 6 में पढ़ती हूँ। मेरी विज्ञान शिक्षिका रजनीश मैम हैं, और मेरा प्रोजेक्ट 'स्वच्छ भारत मिशन और कचरा प्रबंधन' है।", "filePage": "", "link": "#stage"},
  {"id": "bw-compost-vs-biogas", "topic": "biogas-water", "q": "What is the difference between compost and biogas?", "alts": ["compost vs biogas", "compost and biogas difference", "compost aur biogas mein kya fark hai", "which is better compost or biogas", "how is compost different from biogas", "aerobic vs anaerobic"], "keywords": ["compost", "biogas", "difference", "aerobic", "anaerobic"], "answer": "Both turn wet waste into something useful. Compost is made WITH air (aerobic), in an open pit or bin, and gives manure. Biogas is made WITHOUT air (anaerobic), in a closed tank, and gives fuel gas for cooking, plus slurry that is used as manure.", "fun": "When earthworms help to make compost, it is called vermicomposting!", "check": {"q": "Which one needs a closed tank with no air: compost or biogas?", "a": "Biogas."}, "hi": "कम्पोस्ट खाद हवा की मौजूदगी में खुले गड्ढे या डिब्बे में बनती है; बायोगैस बिना हवा के बंद टैंक में बनती है। यह खाना पकाने की गैस है, और टैंक से निकली स्लरी भी खाद के काम आती है।", "filePage": "p21", "link": "#model/biogas"}
] };
